/* Ngữ pháp theo cấp HSK (HSK 2.0, không gồm HSK 3.0).
   Mỗi mục: [tên cấu trúc, công thức, giải thích, [[câu Hán, pinyin, nghĩa Việt]], {py: pinyin của tên, use: cách dùng, note: lưu ý và lỗi thường gặp}].
   Lưu ý: kỳ thi HSK 2.0 không công bố danh sách ngữ pháp chính thức theo từng cấp; việc xếp cấp ở đây là tổng hợp tham khảo
   (đối chiếu danh sách ngữ pháp cộng đồng Chinese Grammar Wiki theo HSK, CC BY-NC-SA) và có thể khác các tài liệu khác.
   Giải thích do Hanzi AI soạn; các mục có src:"file" lấy giải thích và ví dụ từ tài liệu ngữ pháp HSK 3/4/5 do chủ dự án cung cấp. QUAN TRỌNG: tiến độ "Đã học" lưu theo số thứ tự mục (cấp-số), nên các mục cũ giữ nguyên vị trí; chỉ thêm mục mới ở cuối mỗi cấp. */
window.HSK_G={"1": [["是字句 (câu chữ 是)","A + 是 + B","Dùng để nói \"A là B\". Phủ định là 不是, không dùng 没是.",[["我是老师。","Wǒ shì lǎoshī","Tôi là giáo viên."],["李月不是老师。","Lǐ Yuè bú shì lǎoshī","Lý Nguyệt không phải là giáo viên"]],{"py": "shìzìjù","use": "Dùng để nối hai danh từ, nói ai đó/cái gì đó là gì (nghề nghiệp, quốc tịch, tên gọi).","note": "Không dùng 是 trước tính từ thông thường: nói 我很忙, không nói 我是忙. Phủ định là 不是, không dùng 没是.","src": "file"}],["Câu hỏi với 吗 và 呢","Câu trần thuật + 吗？ / A，B呢？","Thêm 吗 cuối câu để hỏi có/không. Dùng 呢 để hỏi lại \"còn... thì sao\".",[["你是美国人吗？","Nǐ shì Měiguó rén ma","Bạn là người Mỹ phải không? ."],["你是学生吗？","Nǐ shì xuésheng ma","Bạn là học sinh phải không?"]],{"py": "ma hé ne","use": "吗 đặt cuối câu trần thuật để hỏi có/không. 呢 dùng để hỏi lại cùng chủ đề (… thì sao) hoặc hỏi một vật đang ở đâu.","note": "Không dùng 吗 cùng với từ nghi vấn (什么, 谁, 哪儿...): câu 你是谁吗？ là sai.","src": "file"}],["有 và 没有","有 / 没有 + danh từ","Chỉ sự sở hữu hoặc tồn tại. Phủ định của 有 là 没有, không nói 不有.",[["我的家乡有一条小河。","Wǒ de jiāxiāng yǒu yì tiáo xiǎo hé","Quê tôi có một con sông nhỏ."],["房间里没有人。","Fángjiān lǐ méi yǒu rén","Trong phòng không có ai."]],{"py": "yǒu hé méiyǒu","use": "有 chỉ sở hữu hoặc có tồn tại; 没有 là phủ định. Hỏi có hay không: …有没有…?","note": "Không nói 不有. Với 有, phủ định luôn là 没有 (có thể nói tắt 没).","src": "file"}],["Trợ từ 的 chỉ sở hữu","Danh từ / đại từ + 的 + danh từ","Nối từ chỉ người sở hữu với vật. Với người thân thiết thường bỏ 的.",[["她是我的汉语老师。","Tā shì wǒ de Hànyǔ lǎoshī","Cô ấy là giáo viên tiếng Hán của tôi."],["这是我的书。","Zhè shì wǒ de shū","Đây là sách của tôi."]],{"py": "de (zhǐ suǒyǒu)","use": "的 nối người sở hữu với vật: A 的 B. Có thể dùng sau tính từ hoặc cụm từ để bổ nghĩa cho danh từ.","note": "Với người thân, nơi chốn thân thuộc thường bỏ 的 (我妈妈, 我们学校). Đừng thêm 的 sau tính từ đơn âm tiết: nói 好朋友 hơn là 好的朋友.","src": "file"}],["Số từ + lượng từ + danh từ","Số + lượng từ + danh từ","Tiếng Trung cần lượng từ giữa số và danh từ: 个 (thông dụng), 本 (sách), 杯 (cốc). Dùng 两 thay cho 二 trước lượng từ.",[["我想买两本书。","Wǒ xiǎng mǎi liǎng běn shū.","Tôi muốn mua hai quyển sách."],["请给我一杯水。","Qǐng gěi wǒ yì bēi shuǐ.","Cho tôi một cốc nước."]],{"py": "shù + liàngcí + míngcí","use": "Số từ không đứng thẳng trước danh từ; phải có lượng từ ở giữa. 个 dùng chung cho nhiều danh từ.","note": "Dùng 两 (không dùng 二) trước lượng từ: 两个人. Không nói 三人 khi cần đếm cụ thể trong câu nói thường ngày (三个人 tự nhiên hơn)."}],["不 phủ định","Chủ ngữ + 不 + động từ / tính từ","Dùng 不 để phủ định hành động ở hiện tại, tương lai, thói quen, hoặc tính từ.",[["我不喝咖啡。","Wǒ bù hē kāfēi.","Tôi không uống cà phê."],["今天不冷。","Jīntiān bù lěng.","Hôm nay không lạnh."],["他不是学生。","Tā bú shì xuésheng.","Anh ấy không phải là học sinh."]],{"py": "bù","use": "Đặt 不 ngay trước động từ hoặc tính từ cần phủ định. Khi đứng trước thanh 4 thì đọc thành bú.","note": "Không dùng 不 để phủ định quá khứ hay 有: nói 没有, không nói 不有. Đừng nói 我不是很忙 khi định nói 我不忙 (nghĩa khác nhau chút)."}],["没 phủ định quá khứ","Chủ ngữ + 没(有) + động từ","没 / 没有 phủ định việc đã không xảy ra hoặc chưa xảy ra, và phủ định của 有.",[["我昨天没去学校。","Wǒ zuótiān méi qù xuéxiào.","Hôm qua tôi không đến trường."],["他还没吃饭。","Tā hái méi chī fàn.","Anh ấy vẫn chưa ăn cơm."],["我没有时间。","Wǒ méiyǒu shíjiān.","Tôi không có thời gian."]],{"py": "méi","use": "Đặt 没 trước động từ, bỏ 了 trong câu phủ định. Câu hỏi: 动词 + 了没有?","note": "Không dùng 不 cho quá khứ: nói 我昨天没去, không nói 我昨天不去 (đó là 'ngày hôm qua tôi không định đi'). Câu phủ định có 没 thì không thêm 了."}],["都 (đều, tất cả)","Chủ ngữ (số nhiều) + 都 + động từ / tính từ","都 tổng hợp: mọi người, mọi vật được nói đến đều như vậy.",[["他们都喜欢看电视。","Tāmen dōu xǐhuan kàn diànshì","Họ đều thích xem TV."],["我们都是坐出租车来的。","Wǒmen dōu shì zuò chūzūchē lái de","Chúng tôi đều là đi taxi đến."]],{"py": "dōu","use": "Đặt 都 sau chủ ngữ và trước động từ hoặc tính từ. Chủ ngữ phải chỉ nhiều người/vật.","note": "Đặt 都 sau động từ là sai: nói 我们都是学生, không nói 我们是都学生. 都 không đi với chủ ngữ chỉ một cá nhân.","src": "file"}],["也 (cũng)","Chủ ngữ + 也 + động từ / tính từ","也 nói rằng một người/vật khác cũng giống như điều đã nêu trước.",[["我也是学生。","Wǒ yě shì xuésheng.","Tôi cũng là học sinh."],["你去，我也去。","Nǐ qù, wǒ yě qù.","Bạn đi thì tôi cũng đi."],["他也不喝茶。","Tā yě bù hē chá.","Anh ấy cũng không uống trà."]],{"py": "yě","use": "Đặt 也 sau chủ ngữ và trước động từ hoặc tính từ. Khi có 都, 也 đứng trước 都.","note": "Đặt 也 sau động từ là sai. Khi kết hợp: 我也都喜欢 (không nói 我都也喜欢)."}],["和 (và)","Danh từ 1 + 和 + danh từ 2","和 nối hai danh từ hoặc đại từ ngang hàng, nghĩa là 'và, cùng với'.",[["哥哥和姐姐都在家。","Gēge hé jiějie dōu zài jiā","Anh trai và chị gái đều ở nhà."],["我们学习了生词、语法和课文。","Wǒmen xuéxí le shēngcí hé yǔfǎ","Chúng tôi đã học từ mới và ngữ pháp."]],{"py": "hé","use": "Chỉ nối danh từ, đại từ. Với ba thành phần trở lên chỉ đặt 和 trước thành phần cuối.","note": "Không dùng 和 để nối hai động từ hoặc hai câu: dùng 然后 hoặc 又 thay thế. Không nói 我吃饭和看电视.","src": "file"}],["多 + tính từ (hỏi mức độ)","Chủ ngữ + 多 + tính từ?","Hỏi mức độ: 多大 (bao nhiêu tuổi/lớn thế nào), 多高 (cao bao nhiêu), 多远 (xa bao nhiêu).",[["你多大？","Nǐ duō dà?","Bạn bao nhiêu tuổi?"],["你有多高？","Nǐ yǒu duō gāo?","Bạn cao bao nhiêu?"],["从这儿到学校有多远？","Cóng zhèr dào xuéxiào yǒu duō yuǎn?","Từ đây đến trường xa bao nhiêu?"]],{"py": "duō + xíngróngcí","use": "Đặt 多 trước tính từ chỉ kích thước, tuổi, khoảng cách để hỏi về mức độ.","note": "Chỉ dùng với tính từ 'lớn' (大, 高, 长, 远, 重...), không dùng với tính từ 'nhỏ' như 小, 矮 trong cách hỏi thường gặp. Hỏi tuổi trẻ em dùng 几岁."}],["太……了 / 不太……","太 + tính từ + 了 ; 不太 + tính từ","太……了 nói mức độ quá mức hoặc rất, thường kèm cảm xúc. 不太 nghĩa là 'không... lắm'.",[["太热了。","Tài rè le","Nóng quá rồi."],["天气太冷了。","Tiānqì tài lěng le","Thời tiết lạnh quá rồi."]],{"py": "tài … le / bú tài …","use": "Đặt tính từ giữa 太 và 了. 不太 + tính từ là cách nói giảm nhẹ, lịch sự.","note": "Không thêm 很 cạnh 太: nói 太好了, không nói 很太好. Không nói 太好看了吗 như câu hỏi; 太……了 thường là câu cảm thán.","src": "file"}],["以前 / 以后","Thời điểm / động từ + 以前 / 以后, ……","以前 chỉ 'trước khi', 以后 chỉ 'sau khi' một thời điểm hay một sự việc.",[["吃饭以前，我先洗手。","Chī fàn yǐqián, wǒ xiān xǐ shǒu.","Trước khi ăn cơm, tôi rửa tay trước."],["下课以后，我们去吃饭。","Xià kè yǐhòu, wǒmen qù chī fàn.","Sau khi tan học, chúng ta đi ăn."],["三年以前，我住在北京。","Sān nián yǐqián, wǒ zhù zài Běijīng.","Ba năm trước, tôi sống ở Bắc Kinh."]],{"py": "yǐqián / yǐhòu","use": "Đứng sau từ chỉ thời gian hoặc sau cụm động từ, rồi đến vế sau.","note": "Không đặt 以前/以后 trước thời điểm: nói 三点以后, không nói 以后三点. Để nói 'sau này' không kèm mốc, dùng 以后 đứng đầu câu."}],["Trật tự từ chỉ thời gian","Chủ ngữ + từ chỉ thời gian + động từ ; từ chỉ thời gian + chủ ngữ + động từ","Từ chỉ thời gian đứng trước động từ (sau hoặc trước chủ ngữ), không đứng cuối câu như tiếng Việt.",[["明天我们去公园。","Míngtiān wǒmen qù gōngyuán.","Ngày mai chúng tôi đi công viên."],["晚上八点她看电视。","Wǎnshang bā diǎn tā kàn diànshì.","Lúc 8 giờ tối cô ấy xem TV."]],{"py": "shíjiān cí de wèizhi","use": "Đặt 今天, 明天, 下午, 八点... ngay sau chủ ngữ hoặc đầu câu.","note": "Không nói 我去商店明天. Khi có cả thời gian và nơi chốn: thời gian đứng trước nơi chốn.","src": "file"}],["岁 (tuổi)","Chủ ngữ + số + 岁","Nói tuổi bằng số đếm kèm 岁. Câu hỏi: 几岁 (trẻ em), 多大 (người lớn bình thường), 多大岁数 (người lớn tuổi).",[["我今年二十岁。","Wǒ jīnnián èrshí suì.","Năm nay tôi hai mươi tuổi."],["你儿子几岁了？","Nǐ érzi jǐ suì le?","Con trai bạn mấy tuổi rồi?"],["奶奶今年七十岁。","Nǎinai jīnnián qīshí suì.","Năm nay bà bảy mươi tuổi."]],{"py": "suì","use": "Không cần động từ 是 hay 有; số và 岁 làm vị ngữ trực tiếp.","note": "Không dùng 个 với 岁: nói 我二十岁, không nói 我二十个岁. Hỏi người lớn tuổi lịch sự: 您多大年纪？"}],["Ngày, tháng, năm","năm + 年 + tháng + 月 + ngày + 号 / 日","Ngày tháng trong tiếng Trung xếp từ lớn đến nhỏ: năm, tháng, ngày. Thứ: 星期 + số.",[["月 1 号, 星期三。","Jiǔ yuè yī hào, xīngqī sān","Ngày 1 tháng 9, thứ Tư 8"],["月 31 号, 星期二。","Bā yuè sān shí yī hào, xīngqī èr","Ngày 31 tháng 8, thứ Ba"]],{"py": "rìqī de biǎodá","use": "Đọc từng chữ số cho năm (二〇二四年). Nói chuyện thường dùng 号, văn viết dùng 日.","note": "Thứ tự ngược với tiếng Việt: 2024年5月3号, không đặt ngày trước. Chủ nhật là 星期天 / 星期日, không phải 星期七.","src": "file"}],["Giờ giấc: 点, 分, 半, 差","số + 点 (+ số + 分) ; 点 + 半 ; 差 + số + 分 + số + 点","Nói giờ bằng 点, phút bằng 分, 半 là 'rưỡi', 差 là 'kém'. 15 phút còn gọi là 一刻.",[["现在八点十八分。","Xiànzài bā diǎn shíbā fēn","Bây giờ là 8 giờ 18 phút."],["三点十五分","sān diǎn shíwǔ fēn","3 giờ 15 phút"]],{"py": "diǎn, fēn, bàn, chà","use": "Hỏi giờ: 几点？ Giờ chẵn: 三点; rưỡi: 三点半; kém: 差五分三点.","note": "Dưới 10 phút thường thêm 零: 三点零五分 (3:05); nói nhanh có thể bỏ 零 (三点五分). Đừng nhầm 三点五十 (3:50) với 三点五分 (3:05).","src": "file"}],["吧 (đề nghị, gợi ý)","Câu + 吧","吧 đặt cuối câu để đề nghị, giục nhẹ nhàng hoặc phỏng đoán.",[["我们走吧。","Wǒmen zǒu ba.","Mình đi thôi."],["她在工作呢，你下午打吧。","Tā zài gōngzuò ne, nǐ xiàwǔ dǎ ba","Cô ấy đang làm việc, chiều bạn gọi điện đi."]],{"py": "ba","use": "Dùng khi rủ, khuyên, ra lệnh nhẹ. Cũng dùng khi đoán: 你是学生吧？","note": "Không dùng 吧 trong câu hỏi có từ nghi vấn. 吧 làm lời đề nghị nghe mềm hơn, đừng dùng nó khi ra lệnh nghiêm khắc.","src": "file"}],["来 / 去 + địa điểm","Chủ ngữ + 来 / 去 + nơi chốn","来 là đến chỗ người nói; 去 là đi khỏi chỗ người nói đến nơi khác.",[["我去学校。","Wǒ qù xuéxiào.","Tôi đến trường."],["他明天来我家。","Tā míngtiān lái wǒ jiā.","Ngày mai anh ấy đến nhà tôi."],["你去哪儿？","Nǐ qù nǎr?","Bạn đi đâu?"]],{"py": "lái / qù + dìdiǎn","use": "Đặt thẳng nơi chốn sau 来/去, không cần giới từ.","note": "Không thêm 在 sau 来/去: nói 我去学校, không nói 我去在学校."}],["在 (ở, chỉ vị trí)","Chủ ngữ + 在 + nơi chốn","在 làm động từ: chỉ người hoặc vật đang ở nơi nào.",[["我朋友在学校。","Wǒ péngyou zài xuéxiào","Bạn tôi ở trường."],["小狗在椅子下面。","Xiǎogǒu zài yǐzi xiàmiàn","Con chó nhỏ ở dưới ghế."]],{"py": "zài (biǎo shì wèizhi)","use": "Chủ thể xác định đứng trước 在, nơi chốn đứng sau.","note": "Không dùng 有 thay 在 khi nói vị trí của một vật cụ thể đã xác định: 书在桌子上 (✓), 桌子上有书 là câu tồn tại (nhấn mạnh có gì).","src": "file"}],["有 (tồn tại ở nơi chốn)","Nơi chốn + 有 + người / vật","Nói ở nơi nào đó có cái gì hoặc người nào đó.",[["桌子上有一本书。","Zhuōzi shàng yǒu yì běn shū.","Trên bàn có một quyển sách."],["我家附近有一个公园。","Wǒ jiā fùjìn yǒu yí ge gōngyuán.","Gần nhà tôi có một công viên."],["教室里没有人。","Jiàoshì lǐ méiyǒu rén.","Trong lớp không có ai."]],{"py": "yǒu (cúnzài)","use": "Nơi chốn đứng đầu câu, 有 đứng sau, rồi tới người hoặc vật (chưa xác định).","note": "Câu tồn tại đi theo thứ tự nơi chốn → 有 → vật; không đảo thành 书有桌子上. Phủ định là 没有."}],["请 (xin mời, làm ơn)","请 + (你) + động từ","请 đặt trước động từ để nhờ hoặc mời một cách lịch sự.",[["请坐。","Qǐng zuò","Mời ngồi. ."],["请喝茶。","Qǐng hē chá","Mời uống trà."]],{"py": "qǐng","use": "Dùng 请 + động từ cho yêu cầu, 请 + người + động từ cho lời mời cụ thể.","note": "Không dùng 请 khi nói với người rất thân nếu không cần lịch sự. 请 không dùng đứng riêng để nói 'cảm ơn' (đó là 谢谢).","src": "file"}],["叫 (gọi là, tên là)","Chủ ngữ + 叫 + tên","叫 dùng để giới thiệu tên gọi: 我叫…, 他叫…. Hỏi tên: 你叫什么名字？",[["我叫小明。","Wǒ jiào Xiǎomíng.","Tôi tên là Tiểu Minh."],["你叫什么名字？","Nǐ jiào shénme míngzi?","Bạn tên là gì?"],["这个字叫什么？","Zhège zì jiào shénme?","Chữ này đọc/gọi là gì?"]],{"py": "jiào","use": "Đặt tên sau 叫. Với họ riêng dùng 姓.","note": "Không nói 我是叫小明. 叫 giới thiệu cả tên, 姓 chỉ họ: 我姓王, 我叫王明."}],["能 (có khả năng, được phép)","Chủ ngữ + 能 + động từ","能 nói khả năng thực hiện được hoặc điều kiện cho phép.",[["我能说汉语。","Wǒ néng shuō Hànyǔ.","Tôi có thể nói tiếng Trung."],["这里能停车吗？","Zhèlǐ néng tíngchē ma?","Ở đây có được đỗ xe không?"]],{"py": "néng","use": "Đặt 能 trước động từ chính. Phủ định: 不能. Hỏi: 能…吗？","note": "Khi nói 'biết' một kỹ năng học được, dùng 会 chứ không dùng 能. Phủ định của 能 là 不能, không phải 没能 trong câu đơn giản.","src": "file"}],["会 (biết, có kỹ năng)","Chủ ngữ + 会 + động từ","会 nói người đã học và biết làm một việc (nói ngoại ngữ, bơi, nấu ăn).",[["我会写汉字。","Wǒ huì xiě Hànzì","Tôi biết viết chữ Hán."],["你妈妈会做中国菜吗？","Nǐ māma huì zuò Zhōngguócài ma","Mẹ bạn có biết nấu món Trung Quốc không?"]],{"py": "huì (jìnéng)","use": "Đặt 会 trước động từ. Phủ định: 不会. Hỏi mức độ: 会不会?","note": "Không dùng 能 thay cho 会 khi nói kỹ năng học được. Không thêm 很 trước 会 khi mới muốn nói 'biết': dùng 很会 để nói 'rất giỏi'.","src": "file"}],["会 (sẽ, dự đoán)","Chủ ngữ + 会 + động từ (+ 的)","会 còn dùng để dự đoán sự việc sẽ xảy ra trong tương lai.",[["明天会下雨。","Míngtiān huì xiàyǔ.","Ngày mai sẽ mưa."],["他应该会同意。","Tā yīnggāi huì tóngyì.","Anh ấy chắc sẽ đồng ý."]],{"py": "huì (jiāng huì)","use": "Nhiều khi có 的 ở cuối câu để khẳng định chắc chắn hơn.","note": "Không nhầm với 'biết': xem ngữ cảnh. Chỉ dùng cho điều có khả năng cao, không dùng cho kế hoạch đã định (dùng 要 / 打算).","src": "file"}],["想 (muốn, nhớ)","Chủ ngữ + 想 + động từ","想 + động từ nghĩa là 'muốn, có ý định làm'. 想 + người/vật còn là 'nhớ'.",[["我想喝茶。","Wǒ xiǎng hē chá","Tôi muốn uống trà. ."],["明天我想去学校看书。","Míngtiān wǒ xiǎng qù xuéxiào kàn shū","Ngày mai tôi muốn đến trường đọc sách."]],{"py": "xiǎng","use": "Đặt 想 trước động từ. Phủ định: 不想. Hỏi: 你想…吗？","note": "想 khác 要: 想 nhẹ hơn, 要 mạnh hơn. Không nói 我想你 khi định nói 'tôi muốn bạn'; câu đó nghĩa là 'tôi nhớ bạn'.","src": "file"}],["怎么 + động từ (làm thế nào)","怎么 + động từ?","Hỏi cách thức thực hiện một việc.",[["这个汉字怎么读？","Zhège Hànzì zěnme dú","Chữ Hán này đọc như thế nào?"],["你怎么去饭店？","Nǐ zěnme qù fàn diàn","Bạn đi đến nhà hàng bằng cách nào?"]],{"py": "zěnme + dòngcí","use": "Đặt 怎么 trước động từ để hỏi 'làm như thế nào'.","note": "怎么 + động từ cũng có thể hỏi lý do (ở HSK2): 你怎么不吃？ Dựa vào ngữ cảnh để phân biệt.","src": "file"}],["在 + nơi chốn + động từ","Chủ ngữ + 在 + nơi chốn + động từ","Nơi chốn xảy ra hành động đứng giữa chủ ngữ và động từ, đi sau 在.",[["他们在学校工作。","Tāmen zài xuéxiào gōngzuò","Họ làm việc ở trường."],["我在朋友家喝茶。","Wǒ zài péngyou jiā hē chá","Tôi uống trà ở nhà bạn."]],{"py": "zài + dìdiǎn + dòngcí","use": "Cấu trúc cố định: 在 + nơi chốn đặt trước động từ.","note": "Đừng đặt nơi chốn sau động từ như tiếng Việt: nói 我在家吃饭, không nói 我吃饭在家.","src": "file"}],["Câu vị ngữ tính từ (很)","Chủ ngữ + 很 + tính từ","Tính từ làm vị ngữ trực tiếp, không cần 是. Thường thêm 很 để câu tự nhiên.",[["你的汉语很好。","Nǐ de Hànyǔ hěn hǎo","Tiếng Hán của bạn rất tốt."],["我妈妈的汉语不好。","Wǒ māma de Hànyǔ bù hǎo","Tiếng Hán của mẹ tôi không tốt."]],{"py": "xíngróngcí wèiyǔjù (hěn)","use": "Đặt 很 trước tính từ. 很 ở đây thường chỉ là chữ đệm, không nhất thiết nghĩa 'rất'.","note": "Không nói 她是漂亮. Nếu bỏ 很 mà không nhấn mạnh, câu nghe như đang so sánh ngầm. 很 mang nghĩa 'rất' thật chỉ khi nhấn giọng.","src": "file"}],["一些 (một vài, một ít)","一些 + danh từ","一些 chỉ số lượng không xác định, nhỏ, đi với nhiều danh từ.",[["我买了一些水果。","Wǒ mǎi le yìxiē shuǐguǒ.","Tôi đã mua một ít trái cây."],["桌子上有一些书。","Zhuōzi shàng yǒu yìxiē shū.","Trên bàn có vài quyển sách."],["请给我一些水。","Qǐng gěi wǒ yìxiē shuǐ.","Cho tôi một ít nước."]],{"py": "yìxiē","use": "Đặt 一些 trước danh từ, không cần lượng từ riêng.","note": "Không thêm 个 sau 一些. Không dùng 一些 để nói chính xác một số: dùng số từ thay thế. 一些 khác 有点儿 (dùng với tính từ)."}],["Nói giá tiền: 块, 毛","số + 块 (+ số + 毛)","Tiền Trung Quốc nói bằng 块 (khẩu ngữ, = 元) và 毛 (= 角, một phần mười 块). Hỏi giá: 多少钱？",[["这个多少钱？","Zhège duōshao qián?","Cái này bao nhiêu tiền?"],["一共二十五块。","Yígòng èrshíwǔ kuài.","Tổng cộng hai mươi lăm tệ."],["苹果三块五一斤。","Píngguǒ sān kuài wǔ yì jīn.","Táo ba tệ rưỡi một cân."]],{"py": "shuō jiàqián: kuài, máo","use": "Nói số rồi 块; nếu có lẻ thì thêm 毛. Số cuối cùng có thể lược đơn vị.","note": "Văn viết dùng 元 và 角, nói thường dùng 块 và 毛. 两 dùng cho 两块, không nói 二块 trong khẩu ngữ phổ biến."}],["几 / 多少 (hỏi số lượng)","几 + lượng từ + danh từ ; 多少 + (lượng từ) + danh từ","几 hỏi số nhỏ (dưới mười); 多少 hỏi số lượng bất kỳ.",[["你有几个汉语老师？","Nǐ yǒu jǐ ge Hànyǔ lǎoshī","Bạn có mấy giáo viên tiếng Hán?"],["你女儿几岁了？","Nǐ nǚ'ér jǐ suì le","Con gái bạn mấy tuổi rồi?"]],{"py": "jǐ / duōshao","use": "几 luôn cần lượng từ; 多少 có thể bỏ lượng từ.","note": "Không nói 几人: phải là 几个人. 多少 dùng khi dự đoán số lớn hơn 10; không dùng 几 để hỏi số tiền lớn (dùng 多少钱).","src": "file"}],["怎么样 (thế nào?)","Chủ đề + 怎么样？","怎么样 hỏi nhận xét, tình hình hoặc xin ý kiến, đặt cuối câu.",[["这部电影怎么样？","Zhè bù diànyǐng zěnmeyàng?","Bộ phim này như thế nào? (Hay dở ra sao?)"],["我们晚上吃火锅，怎么样？","Wǒmen wǎnshang chī huǒguō, zěnmeyàng?","Tối nay chúng ta ăn lẩu, thấy sao?"]],{"py": "zěnmeyàng","use": "Đặt 怎么样 sau chủ đề muốn hỏi, hoặc sau đề nghị để hỏi ý.","note": "Không thêm 吗 sau 怎么样. Khi rủ: 我们去吃饭，怎么样？ nghĩa 'thấy sao?'.","src": "file"}],["Từ nghi vấn giữ nguyên vị trí","Chủ ngữ + động từ + từ nghi vấn ?","Từ nghi vấn (什么, 谁, 哪儿, 几...) đứng đúng chỗ của thông tin cần hỏi, không đảo lên đầu câu.",[["你想吃什么？","Nǐ xiǎng chī shénme?","Bạn muốn ăn gì?"],["她是谁？","Tā shì shéi?","Cô ấy là ai?"],["你住在哪儿？","Nǐ zhù zài nǎr?","Bạn sống ở đâu?"]],{"py": "yíwèn cí de wèizhi","use": "Thay phần chưa biết trong câu trần thuật bằng từ nghi vấn.","note": "Không đảo từ nghi vấn lên đầu như tiếng Anh. Không thêm 吗 vào cuối: 你吃什么？ (✓), 你吃什么吗？ (✗)."}],["……了吗？ (đã…chưa?)","động từ + 了 + (tân ngữ) + 吗？","Hỏi một việc đã xảy ra hay chưa. Trả lời: 动词 + 了 hoặc 没(有) + 动词.",[["你吃饭了吗？","Nǐ chī fàn le ma?","Bạn ăn cơm chưa?"],["他来了吗？","Tā lái le ma?","Anh ấy đến chưa?"],["你看了那个电影吗？","Nǐ kàn le nàge diànyǐng ma?","Bạn đã xem bộ phim đó chưa?"]],{"py": "…le ma?","use": "Thêm 了 sau động từ rồi 吗 cuối câu. Có thể hỏi bằng 了没有？","note": "Câu trả lời phủ định dùng 没, không dùng 不: 你吃了吗？ → 没吃. Không dùng 了 trong câu trả lời phủ định."}],["是……的 (nhấn mạnh chi tiết)","Chủ ngữ + 是 + thông tin nhấn mạnh + động từ + 的","Dùng khi việc đã xảy ra rồi, người nói muốn nhấn vào thời gian, nơi chốn hoặc cách thức.",[["我们是坐出租车来的。","Wǒmen shì zuò chūzūchē lái de","Chúng tôi đến bằng taxi."],["你是什么时候开始学汉语的？","Nǐ shì shénme shíhou kāishǐ xué Hànyǔ de","Bạn là bắt đầu học tiếng Hán từ khi nào?"]],{"py": "shì … de (qiángdiào xìjié)","use": "Đặt 是 trước thông tin cần nhấn, 的 ở cuối câu (hoặc sau động từ).","note": "Chỉ dùng khi việc đã xảy ra. Không dùng với 了 cùng lúc. Khẳng định có thể bỏ 是, phủ định phải có 不是: 我不是坐飞机来的.","src": "file"}],["Đại từ nghi vấn “什么”","Đại từ nghi vấn “什么”","Dùng để hỏi người hoặc sự vật (cái gì, gì).",[["你叫什么名字","Nǐ jiào shénme míngzi","Tên bạn là gì?"],["你买什么？","Nǐ mǎi shénme","Bạn mua gì?"]],{"py": "shénme","use": "","note": "","src": "file"}],["Đại từ nghi vấn “哪”","Đại từ nghi vấn “哪”","Dùng để hỏi về người hoặc sự vật, thường đi kèm lượng từ.",[["你是哪国人？","Nǐ shì nǎ guó rén","Bạn là người nước nào?"],["哪本书？","Nǎ běn shū?","Quyển sách nào?"]],{"py": "nǎ","use": "","note": "","src": "file"}],["Trợ từ nghi vấn “呢” (HSK1)","Trợ từ nghi vấn “呢”","Dùng ở cuối câu để hỏi lại, truy vấn tình huống đã đề cập.",[["我喜欢喝咖啡。你呢？","Wǒ xǐhuan hē kāfēi. Nǐ ne","Tôi thích uống cà phê. Còn bạn?"],["他已经吃过饭了。你呢？","Tā yǐjīng chīguo fàn le. Nǐ ne","Anh ấy ăn rồi. Còn bạn?"]],{"py": "ne","use": "","note": "","src": "file"}],["Cách diễn đạt các số dưới 100","Cách diễn đạt các số dưới 100","Các số từ 11 đến 99 trong tiếng Trung được tạo thành theo cấu trúc: (Số hàng chục) + 十 + (Số hàng đơn vị)",[["李老师今年 50 岁了。","Lǐ lǎoshī jīnnián wǔshí suì le","Thầy Lí năm nay 50 tuổi rồi."],["二十三","èr shí sān","Hai mươi ba."]],{"py": "","use": "","note": "","src": "file"}],["Trợ từ “了 -”","Trợ từ “了 -”","Dùng ở cuối câu chỉ sự thay đổi, sự xuất hiện của 1 tình huống mới.",[["我朋友的女儿今年四岁了。","Wǒ péngyou de nǚ'ér jīnnián sì suì le","Con gái bạn tôi năm nay đã bốn tuổi rồi."],["李老师今年50岁了。","Lǐ lǎoshī jīnnián wǔshí suì le","Thầy Lí năm nay đã 50 tuổi rồi.),"]],{"py": "le","use": "","note": "","src": "file"}],["Câu có vị ngữ là danh từ","Câu có vị ngữ là danh từ","Vị ngữ là danh từ hoặc cụm danh từ (thường diễn tả tuổi tác, thời gian).",[["今天 9 月 1 号。","Jīntiān jiǔ yuè yī hào","Hôm nay là ngày 1 tháng"],["我的汉语老师 33 岁。","Wǒ de Hànyǔ lǎoshī sān shí sān suì","Giáo viên tiếng Hán của tôi 33 tuổi."]],{"py": "","use": "","note": "","src": "file"}],["Cấu trúc liên động từ","Cấu trúc liên động từ","Hành động thứ nhất biểu thị phương thức hoặc mục đích của hành động thứ hai. Cả hai hành động đều do cùng một chủ thể thực hiện.",[["我去图书馆看书。","Wǒ qù túshūguǎn kàn shū","Tôi đi thư viện đọc sách."],["妈妈上街买菜。","Māma shàng jiē mǎi cài","Mẹ ra chợ mua thức ăn."]],{"py": "","use": "","note": "","src": "file"}],["Đại từ nghi vấn “多少”","Đại từ nghi vấn “多少”","Dùng để hỏi số lượng từ 10 trở lên, hoặc hỏi giá cả.",[["你们学校有多少个学生？","Nǐmen xuéxiào yǒu duōshao ge xuésheng","Trường các bạn có bao nhiêu học sinh?"],["这个杯子多少钱？","Zhège bēizi duōshao qián","Cái cốc này bao nhiêu tiền?"]],{"py": "duōshao","use": "","note": "","src": "file"}],["Lượng từ “个 kǒu”","Lượng từ “个 kǒu”","个 /gè/ Lượng từ phổ biến nhất, dùng cho hầu hết danh từ chỉ người, sự vật, đồ vật. Dùng khi không biết rõ lượng từ chuyên biệt. 口 /kǒu/ Lượng từ dùng cho số thành viên trong gia đình.",[["一个老师","yí gè lǎoshī","một giáo viên"],["三个苹果","sān gè píngguǒ","ba quả táo"],["我家有四口人","Wǒ jiā yǒu sì kǒu rén","Nhà tôi có bốn người"],["我们家三口人","Wǒmen jiā sān kǒu rén","Gia đình tôi có ba người"]],{"py": "kǒu","use": "","note": "","src": "file"}],["Đại từ nghi vấn “哪儿”","Đại từ nghi vấn “哪儿”","Dùng để hỏi về vị trí của người hoặc vật (ở đâu).",[["你的杯子在哪儿？","Nǐ de bēizi zài nǎr","Cái cốc của bạn ở đâu?"],["你的中国朋友在哪儿？","Nǐ de péngyou zài nǎr","Bạn của bạn ở đâu?"]],{"py": "nǎr","use": "","note": "","src": "file"}],["Trợ từ nghi vấn “呢” (HSK1) (2)","Trợ từ nghi vấn “呢”","Dùng ở cuối câu, hỏi lại về vị trí hoặc truy vấn về người/vật.",[["我的小猫呢？","Wǒ de xiǎomāo ne","Con mèo nhỏ của tôi đâu?"],["他在哪儿呢？","Tā zài nǎr ne","Anh ấy ở đâu vậy?"]],{"py": "ne","use": "","note": "","src": "file"}],["Danh từ “前”","Danh từ “前”","Biểu thị một khoảng thời gian trước thời điểm hiện tại/được đề cập.",[["三天前","sān tiān qián","Ba ngày trước."],["我以前住在北京。","Wǒ yǐqián zhù zài Běijīng","Trước đây tôi sống ở Bắc Kinh."]],{"py": "qián","use": "","note": "","src": "file"}],["Câu có vị ngữ là kết cấu chủ-vị","Câu có vị ngữ là kết cấu chủ-vị","Vị ngữ là một cụm từ có cấu trúc chủ-vị: [Chủ ngữ 1] + [Vị ngữ (Chủ ngữ 2 + Động từ 2)]",[["这本书内容很有趣。","Zhè běn shū nèiróng hěn yǒuqù","Cuốn sách này nội dung rất thú vị."],["这家餐厅价格很贵。","Zhè jiā cāntīng jiàgé hěn guì","Nhà hàng này giá cả rất đắt."]],{"py": "","use": "","note": "","src": "file"}],["Thán từ “喂”","Thán từ “喂”","Dùng để gọi, thu hút sự chú ý hoặc bắt đầu cuộc trò chuyện, đặc biệt là qua điện thoại.",[["喂，李老师在家吗？","Wèi, Lǐ lǎoshī zài jiā ma?","A lô, thầy Lý có ở nhà không?"],["喂，你是张小姐吗？","Wèi, nǐ shì Zhāng xiǎojiě ma","A lô, cô là cô Trương phải không?"]],{"py": "wèi","use": "","note": "","src": "file"}],["Cấu trúc “在 ……呢”","Cấu trúc “在 ……呢”","Biểu thị hành động đang diễn ra (đang).",[["你在做什么呢？","Nǐ zài zuò shénme ne","Bạn đang làm gì vậy?"],["我在看书呢。","Wǒ zài kàn shū ne","Tôi đang đọc sách."]],{"py": "","use": "","note": "","src": "file"}],["Cách đọc số điện thoại","Cách đọc số điện thoại","Đọc từng chữ số một, tuần tự từ trái sang phải. Số \"1\" đọc là /yāo/.",[["82304156","bā èr sān líng sì yāo wǔ liù","Đọc từng chữ số từ trái sang phải; số 1 đọc là yāo."],["13851897623","yāo sān bā wǔ yāo bā jiǔ qī liù èr sān","Số điện thoại di động 11 chữ số, đọc từng số một."]],{"py": "","use": "","note": "","src": "file"}],["Trợ từ 了","Trợ từ 了","Dùng sau động từ/tính từ để biểu thị sự việc đã xảy ra hay hoàn thành.",[["她去商店了。","Tā qù shāngdiàn le","Cô ấy đã đi cửa hàng rồi."],["我买了一点儿苹果。","Wǒ mǎi le yì diǎnr píngguǒ","Tôi đã mua một ít táo."]],{"py": "le","use": "","note": "","src": "file"}],["Danh từ 后","Danh từ 后","Biểu thị một khoảng thời gian sau thời điểm được đề cập (sau).",[["五点四十分钟后。","Wǔ diǎn sì shí fēnzhōng hòu","Sau 5 giờ 40 phút"],["五点后。","Wǔ diǎn hòu","Sau 5 giờ."]],{"py": "hòu","use": "","note": "","src": "file"}],["Trợ từ ngữ khí 啊","Trợ từ ngữ khí 啊","Trợ từ ngữ khí 啊 /a/ (có thể biến âm thành /ya/, /wa/, /na/... tùy âm tiết trước nó) khi đặt cuối câu trần thuật có tác dụng làm mềm mại, thân mật, nhấn mạnh hoặc bày tỏ cảm xúc",[["小心啊！","Xiǎoxīn a","Cẩn thận đấy!"],["快点儿啊，要迟到了！","Kuài diǎnr a, yào chídào le!","Nhanh lên nào, sắp muộn rồi!"]],{"py": "","use": "","note": "","src": "file"}],["Cách diễn tả ngày tháng","Cách diễn tả ngày tháng","Diễn tả đầy đủ năm, tháng, ngày, thứ, theo thứ tự từ lớn đến nhỏ.",[["今天是 2025 年 1 月 5 号。","Jīntiān shì èr líng èr wǔ nián yī yuè wǔ hào.","Hôm nay là ngày 5 tháng 1 năm 2025."],["明天是 2024 年 12 月 18 号，星期三。","Míngtiān shì èr líng èr sì nián shí'èr yuè shíbā hào, xīngqīsān.","Ngày mai là thứ Tư, ngày 18 tháng 12 năm 2024."]],{"py": "","use": "","note": "","src": "file"}]],"2": [["比字句 (so sánh hơn)","A + 比 + B + tính từ (+ mức chênh)","Dùng 比 để so sánh. Không thêm 很 trước tính từ. Phủ định: A 没有 B + tính từ.",[["哥哥比姐姐高。","Gēge bǐ jiějie gāo","Anh trai cao hơn chị gái."],["今天比昨天热。","Jīntiān bǐ zuótiān rè","Hôm nay nóng hơn hôm qua."]],{"py": "bǐzìjù","use": "So sánh hai đối tượng: A hơn B ở một đặc điểm. Có thể thêm mức chênh lệch sau tính từ.","note": "Không thêm 很/非常 trước tính từ trong câu 比: nói 他比我高, không nói 他比我很高. Muốn nhấn thì dùng 更 hoặc 得多.","src": "file"}],["Trợ từ 了 (hoàn thành, thay đổi)","Động từ + 了 / Câu + 了","了 sau động từ chỉ hành động đã hoàn thành. 了 cuối câu chỉ sự việc đã xảy ra hoặc tình huống mới.",[["我买了一件衣服。","Wǒ mǎile yí jiàn yīfu.","Tôi đã mua một cái áo."],["下雨了。","Xià yǔ le.","Trời mưa rồi."]],{"py": "le (wánchéng, biànhuà)","use": "了 sau động từ nói hành động đã hoàn thành; 了 cuối câu nói tình huống mới hoặc thay đổi.","note": "Phủ định dùng 没(有) và bỏ 了: 我没去. Câu có số lượng ('mua hai quyển') thường dùng 了 sau động từ."}],["过 (từng trải qua)","Động từ + 过 / 没(有) + động từ + 过","Diễn tả kinh nghiệm đã từng có. Phủ định dùng 没 và vẫn giữ 过.",[["他们来过我家。","Tāmen lái guo wǒ jiā","Họ đã từng đến nhà tôi."],["我看过那个电影。","Wǒ kàn guo nàge diànyǐng","Tôi đã từng xem bộ phim đó."]],{"py": "guo (cóng jīnglì)","use": "Động từ + 过 nói trải nghiệm đã từng có trong quá khứ (không nói rõ thời điểm).","note": "Phủ định là 没(有)……过, không dùng 不……过. Không dùng 过 với việc đã làm xong ở một thời điểm xác định (dùng 了).","src": "file"}],["正在 / 在 (đang làm)","正在 / 在 + động từ (+ 呢)","Diễn tả hành động đang diễn ra. 呢 ở cuối câu làm câu tự nhiên hơn.",[["我正在看电视。","Wǒ zhèngzài kàn diànshì.","Tôi đang xem tivi."],["他在打电话呢。","Tā zài dǎ diànhuà ne.","Anh ấy đang gọi điện thoại."]],{"py": "zhèngzài / zài","use": "正在/在 + động từ nói hành động đang diễn ra. Cuối câu có thể thêm 呢.","note": "Không dùng 正在 với tính từ hoặc với động từ trạng thái như 是, 有, 喜欢. Phủ định dùng 没在 chứ không dùng 不在 (nghĩa khác)."}],["要……了 (sắp)","要 / 快要 / 就要 + động từ + 了","Diễn tả việc sắp xảy ra. Có thể thêm từ chỉ thời gian trước 就要.",[["火车要来了。","Huǒchē yào lái le","Tàu hỏa sắp đến rồi."],["新的一年快要到了。","Xīn de yī nián kuàiyào dào le","Năm mới sắp đến rồi."]],{"py": "yào … le","use": "要/快要/就要 + động từ + 了 nói sự việc sắp xảy ra.","note": "就要 đi được với mốc thời gian cụ thể (明天就要走了); 快要 thì không (không nói 明天快要走了).","src": "file"}],["还 (vẫn, còn)","chủ ngữ + 还 + động từ / tính từ","还 nói sự việc vẫn tiếp tục chưa thay đổi, hoặc nói thêm một việc nữa ('còn').",[["你还知道回来啊？","Nǐ hái zhīdào huílái a","Còn biết về đấy à?"],["今天还挺冷的。","Jīntiān hái tǐng lěng de","Hôm nay còn khá lạnh đấy."]],{"py": "hái","use": "Đặt 还 sau chủ ngữ, trước động từ hoặc tính từ. Với phủ định: 还没……(vẫn chưa).","note": "Không đặt 还 sau động từ. 还 (hái, vẫn) khác 还 (huán, trả lại).","src": "file"}],["再 (lại, nữa — tương lai)","chủ ngữ + 再 + động từ","再 nói một hành động sẽ lặp lại hoặc tiếp tục trong tương lai.",[["你再看看这本书。","Nǐ zài kàn kàn zhè běn shū","Bạn xem lại cuốn sách này đi."],["你明天再给我打电话吧。","Nǐ míngtiān zài gěi wǒ dǎ diànhuà ba","Ngày mai bạn gọi điện thoại cho tôi nhé."]],{"py": "zài","use": "Dùng cho việc chưa xảy ra. Cũng dùng trong 再见, 再说.","note": "Không dùng 再 cho việc đã xảy ra: dùng 又. Nói 我明天再来 (✓), không nói 我昨天再来.","src": "file"}],["已经……了 (đã … rồi)","chủ ngữ + 已经 + động từ / tính từ + 了","已经……了 nhấn mạnh việc đã xảy ra hoặc trạng thái đã đạt tới.",[["他已经走了。","Tā yǐjīng zǒu le.","Anh ấy đã đi rồi."],["现在已经十二点了。","Xiànzài yǐjīng shí'èr diǎn le.","Bây giờ đã mười hai giờ rồi."],["我已经吃过饭了。","Wǒ yǐjīng chī guo fàn le.","Tôi đã ăn cơm rồi."]],{"py": "yǐjīng … le","use": "Đặt 已经 trước động từ, 了 ở cuối câu hoặc sau động từ.","note": "Không dùng 已经 cho tương lai. Phủ định thường dùng 还没……, không nói 已经没……了 khi định nói 'chưa'."}],["就 (thì, ngay, sớm)","chủ ngữ + 就 + động từ","就 nối sự việc xảy ra ngay lập tức hoặc sớm hơn dự tính; cũng dùng trong câu điều kiện 'nếu… thì…'.",[["你既然不喜欢这份工作，那就辞职吧。","Nǐ jìrán bù xǐhuan zhè fèn gōngzuò, nà jiù cízhí ba","Cậu đã không thích công việc này, vậy thì nghỉ việc đi."],["天气这么冷，你穿这么少，就会感冒的。","Tiānqì zhème lěng, nǐ chuān zhème shǎo, jiù huì gǎnmào de","Thời tiết lạnh thế, cậu mặc ít vậy, ắt là sẽ bị cảm."]],{"py": "jiù","use": "Đặt 就 trước động từ. Nhấn mạnh khoảng thời gian ngắn hoặc sớm.","note": "Không nhầm với 才 (muộn hơn dự tính). 他六点就来了 (sáu giờ đã đến, sớm) khác với 他六点才来 (sáu giờ mới đến, muộn).","src": "file"}],["别 / 不要 (đừng)","别 / 不要 + động từ","Dùng để ngăn cản hoặc khuyên đừng làm gì.",[["不要玩手机了。","Bú yào wán shǒujī le","Đừng chơi điện thoại nữa."],["别睡觉了。","Bié shuìjiào le","Đừng ngủ nữa."]],{"py": "bié / búyào","use": "别 và 不要 mang nghĩa tương tự; 别 dùng nhiều trong khẩu ngữ.","note": "Không dùng 不 hoặc 没 cho mệnh lệnh phủ định. Có thể thêm 了 ở cuối (别说了) để nói 'đừng nói nữa'.","src": "file"}],["有点儿 + tính từ (hơi)","chủ ngữ + 有点儿 + tính từ","有点儿 nói 'hơi…', thường mang sắc thái không hài lòng.",[["今天天气有点儿冷。","Jīntiān tiānqì yǒudiǎnr lěng","Hôm nay thời tiết hơi lạnh."],["我昨晚睡有点儿晚。","Wǒ zuówǎn shuì yǒudiǎnr wǎn","Tối qua tôi ngủ hơi muộn."]],{"py": "yǒudiǎnr","use": "Đặt 有点儿 trước tính từ hoặc động từ tâm lý.","note": "有点儿 thường dùng cho điều không như ý. Muốn nói 'hơn một chút' dùng 一点儿 đứng sau tính từ (大一点儿).","src": "file"}],["离 (cách, khoảng cách)","A + 离 + B + (có xa/gần) + khoảng cách","离 nói khoảng cách giữa hai địa điểm hoặc hai mốc thời gian.",[["我家离学校很远","Wǒ jiā lí xuéxiào hěn yuǎn","Nhà tôi cách trường rất xa."],["学校离机场有20公里。","Xuéxiào lí jīchǎng yǒu èr shí gōnglǐ","Trường học cách sân bay 20 km."]],{"py": "lí","use": "Đặt 离 giữa hai địa điểm, rồi nói xa hay gần hoặc khoảng cách cụ thể.","note": "Không dùng 从 thay cho 离 để nói khoảng cách: nói 我家离学校很近, không nói 我家从学校很近.","src": "file"}],["更 / 最 (hơn nữa / nhất)","更 + tính từ ; 最 + tính từ","更 dùng khi so sánh để nói 'còn hơn nữa'. 最 nói 'nhất'.",[["大卫的汉语最好。","Dàwèi de Hànyǔ zuì hǎo","Tiếng Hán của Đại Vệ là tốt nhất."],["我最喜欢吃米饭。","Wǒ zuì xǐhuān chī mǐfàn","Tôi thích ăn cơm nhất."]],{"py": "gèng / zuì","use": "Đặt 更/最 trước tính từ. 最 có thể kèm phạm vi: 我们班最高的人.","note": "Không dùng 很 cùng lúc với 更 hoặc 最. Nói 他比我更高, không nói 他比我很高.","src": "file"}],["真 (thật là)","真 + tính từ / động từ tâm lý","真 nhấn mạnh cảm xúc của người nói, tương tự 'thật là, quả thật'.",[["你真好！","Nǐ zhēn hǎo","Bạn thật tốt!"],["你女儿的房间真漂亮！","Nǐ nǚ'ér de fángjiān zhēn piàoliang","Phòng của con gái bạn thật đẹp!"]],{"py": "zhēn","use": "Đặt 真 trước tính từ hoặc động từ tâm lý.","note": "Dùng trong câu cảm thán, không dùng trong câu hỏi trung tính. Có thể kết hợp 真的 ở đầu câu.","src": "file"}],["Định ngữ + 的","cụm từ / tính từ + 的 + danh từ","Cụm từ, mệnh đề hoặc tính từ bổ nghĩa cho danh từ, nối bằng 的.",[["新买的自行车","xīn mǎi de zìxíngchē","Chiếc xe đạp mới mua."],["和你一起唱歌的人","hé nǐ yìqǐ chànggē de rén","Người hát cùng với bạn."]],{"py": "dìngyǔ + de","use": "Phần bổ nghĩa luôn đứng trước danh từ. Trong tiếng Việt thì ngược lại.","note": "Đừng đặt phần bổ nghĩa sau danh từ như tiếng Việt. Khi danh từ đã rõ có thể bỏ: 这本书是我的.","src": "file"}],["……的时候 (khi …)","Cụm từ / động từ + 的时候, ……","的时候 chỉ thời điểm xảy ra một sự việc: 'khi…, lúc…'.",[["睡觉的时候，请保持安静。","Shuìjiào de shíhou, qǐng bǎochí ānjìng","Khi ngủ, hãy giữ yên lặng."],["你忙的时候，不用回我的消息。","Nǐ máng de shíhou, búyòng huí wǒ de xiāoxi","Khi bạn bận, không cần phải trả lời tin nhắn của tôi."]],{"py": "… de shíhou","use": "Đặt 的时候 sau cụm động từ hoặc danh từ chỉ thời gian.","note": "Không bỏ 的 trong cấu trúc này (với danh từ ngắn như 小时候 vẫn dùng được). Vế sau thường có chủ ngữ riêng.","src": "file"}],["Số + 多 (hơn, có dư)","số + 多 + lượng từ (+ danh từ)","多 đặt sau số tròn để nói 'hơn, có dư'.",[["他二十多岁。","Tā èrshí duō suì.","Anh ấy hơn hai mươi tuổi."],["我买了三百多块的书。","Wǒ mǎi le sānbǎi duō kuài de shū.","Tôi mua sách hơn ba trăm tệ."],["教室里有十多个学生。","Jiàoshì lǐ yǒu shí duō ge xuésheng.","Trong lớp có hơn mười học sinh."]],{"py": "shù + duō","use": "Dùng với số tròn: 十多个, 三百多块; với số nhỏ hơn 10 thì 多 đứng sau lượng từ.","note": "Không đặt 多 trước số. Với số hàng chục, đặt 多 sau số: 二十多岁 (hơn hai mươi tuổi)."}],["着 (đang ở trạng thái)","động từ + 着","着 sau động từ nói trạng thái kéo dài, tư thế hoặc kết quả còn tồn tại.",[["门开着。","Mén kāi zhe","Cửa đang mở. ."],["他们穿着红色的衣服。","Tāmen chuān zhe hóngsè de yīfu","Họ đang mặc quần áo màu đỏ."]],{"py": "zhe","use": "Dùng với các động từ như 坐, 站, 开, 穿, 拿...","note": "Không dùng 着 để nói hành động đang diễn ra tạm thời: dùng 在.","src": "file"}],["给 (cho, giúp, đưa)","chủ ngữ + 给 + người nhận + động từ","给 làm giới từ: làm việc gì đó vì ai, hoặc dành cho ai.",[["我给妈妈打电话。","Wǒ gěi māma dǎ diànhuà.","Tôi gọi điện cho mẹ."],["他给我做了一个蛋糕。","Tā gěi wǒ zuò le yí ge dàngāo.","Anh ấy làm cho tôi một cái bánh."],["他给我寄了一封信。","Tā gěi wǒ jì le yì fēng xìn.","Anh ấy đã gửi cho tôi một lá thư."]],{"py": "gěi","use": "Đặt 给 + người nhận trước động từ chính.","note": "Không đặt 给 + người sau động từ chính khi nói 'làm cho ai' (khác với 送给, 寄给). Không nhầm với động từ 给 (cho tặng)."}],["从……到…… (từ … đến …)","从 + nơi / thời điểm + 到 + nơi / thời điểm","Nói điểm xuất phát và điểm đến của không gian hoặc thời gian.",[["商店从上午九点开到下午六点。","Shāngdiàn cóng shàngwǔ jiǔ diǎn kāi dào xiàwǔ liù diǎn","Cửa hàng mở cửa từ 9 giờ sáng đến 6 giờ chiều."],["从这儿到地铁站怎么走？","Cóng zhèr dào dìtiě zhàn zěnme zǒu","Từ đây đến ga tàu điện đi thế nào?"]],{"py": "cóng … dào …","use": "Đặt 从 trước điểm đầu, 到 trước điểm cuối, rồi tới động từ nếu có.","note": "Không bỏ 从 hoặc 到 nếu muốn nói trọn nghĩa. Có thể dùng riêng 从 + nơi + động từ để nói 'từ đâu'.","src": "file"}],["往 (hướng về)","往 + phương hướng / nơi + động từ","往 nói hướng di chuyển của hành động.",[["从这儿往前走，就是我们学校。","Cóng zhèr wǎng qián zǒu, jiù shì wǒmen xuéxiào","Từ đây đi về phía trước là trường của chúng tôi."],["你看，往左是医院，往右是银行。","Nǐ kàn, wǎng zuǒ shì yīyuàn, wǎng yòu shì yínháng","Bạn xem, rẽ trái là bệnh viện, rẽ phải là ngân hàng."]],{"py": "wǎng","use": "Đặt 往 + hướng trước động từ chỉ di chuyển: 往前走, 往右拐.","note": "Không dùng 往 trước đối tượng không phải hướng đi. 往 khác 向 ở chỗ 往 thiên về hướng di chuyển.","src": "file"}],["对 (với, đối với)","chủ ngữ + 对 + người + động từ","对 chỉ đối tượng mà hành động hoặc thái độ hướng tới.",[["跑步对身体很好。","Pǎobù duì shēntǐ hěn hǎo","Chạy bộ rất tốt cho sức khỏe."],["看电视对学习汉语有帮助。","Kàn diànshì duì xuéxí Hànyǔ yǒu bāngzhù","Xem TV có ích cho việc học tiếng Hán."]],{"py": "duì","use": "Đặt 对 + đối tượng trước động từ hoặc tính từ: 对我很好, 对他说.","note": "Không dùng 对 thay cho 跟 (cùng làm với) hoặc 给 (làm cho).","src": "file"}],["要 (nhiều nghĩa)","要 + danh từ / động từ","要 có nhiều nghĩa: muốn, cần, sẽ, phải. Nghĩa phụ thuộc vào ngữ cảnh.",[["王方要学习英语。","Wáng Fāng yào xuéxí Yīngyǔ","Vương Phương muốn học tiếng Anh."],["我要吃米饭。","Wǒ yào chī mǐfàn","Tôi muốn ăn cơm."]],{"py": "yào","use": "Trước danh từ: 'muốn/cần'; trước động từ: 'muốn/sẽ/phải'.","note": "Phủ định của 要 (phải, cần) là 不用 hoặc 不必; phủ định của 要 (muốn) là 不想. Không dùng 不要 để phủ định 'muốn'.","src": "file"}],["可以 (được phép, có thể)","chủ ngữ + 可以 + động từ","可以 nói sự cho phép hoặc điều kiện cho phép.",[["我可以坐这里吗？","Wǒ kěyǐ zuò zhèlǐ ma?","Tôi có thể ngồi đây không?"],["这里可以拍照。","Zhèlǐ kěyǐ pāizhào.","Ở đây được chụp ảnh."],["你可以用我的电脑。","Nǐ kěyǐ yòng wǒ de diànnǎo.","Bạn có thể dùng máy tính của tôi."]],{"py": "kěyǐ","use": "Hỏi xin phép: 我可以……吗？ Phủ định: 不可以 hoặc 不能.","note": "Phủ định lịch sự thường dùng 不能 hơn 不可以. 可以 khác 会/能 (khả năng)."}],["Câu liên động (chuỗi động từ)","chủ ngữ + động từ 1 + (tân ngữ) + động từ 2 + (tân ngữ)","Hai hay nhiều động từ liên tiếp cho cùng một chủ ngữ, xếp theo thứ tự xảy ra.",[["我去商店买东西。","Wǒ qù shāngdiàn mǎi dōngxi.","Tôi đi cửa hàng mua đồ."],["他坐地铁去上班。","Tā zuò dìtiě qù shàngbān.","Anh ấy đi tàu điện ngầm đi làm."],["我们去公园玩儿吧。","Wǒmen qù gōngyuán wánr ba.","Chúng ta đi công viên chơi đi."]],{"py": "liándòngjù","use": "Không cần từ nối giữa các động từ.","note": "Không thêm 和 hay 然后 khi hai hành động liền nhau và có quan hệ mục đích: nói 我去商店买东西, không nói 我去商店和买东西."}],["一起 (cùng nhau)","chủ ngữ + 一起 + động từ","一起 nói nhiều người cùng làm một việc.",[["我们一起去吧。","Wǒmen yìqǐ qù ba.","Chúng ta cùng đi nhé."],["我跟朋友一起吃饭。","Wǒ gēn péngyou yìqǐ chī fàn.","Tôi ăn cơm cùng bạn."],["他们一起学习汉语。","Tāmen yìqǐ xuéxí Hànyǔ.","Họ cùng nhau học tiếng Trung."]],{"py": "yìqǐ","use": "Đặt 一起 trước động từ. Có thể dùng 跟/和 + người + 一起 + động từ.","note": "Không đặt 一起 sau động từ. Nói 我们一起去, không nói 我们去一起."}],["Động lượng từ (次, 遍, 下)","động từ + số + động lượng từ","Động lượng từ nói số lần hoặc cách thực hiện hành động.",[["我们看过三次电影。","Wǒmen kàn guò sān cì diànyǐng","Chúng tôi đã xem phim ba lần."],["他们坐过飞机一次。","Tāmen zuò guò fēijī yī cì","Họ đã từng đi máy bay một lần."]],{"py": "dòngliàngcí","use": "Đặt số + động lượng từ sau động từ. Nếu tân ngữ là đại từ, nó đứng giữa động từ và động lượng từ.","note": "Với tân ngữ là đại từ: 看他一次, không nói 看一次他. 次 chỉ số lần; 遍 chỉ toàn bộ quá trình từ đầu đến cuối.","src": "file"}],["Lặp động từ (V V)","động từ + động từ ; động từ + 一 + động từ","Lặp động từ làm hành động nhẹ nhàng hơn, ngắn hơn hoặc thử làm.",[["我看看你的新手机。","Wǒ kànkan nǐ de xīn shǒujī","Tôi xem thử điện thoại mới của bạn."],["让我想想再回答。","Ràng wǒ xiǎngxiǎng zài huídá","Để tôi nghĩ một chút rồi trả lời."]],{"py": "chóngdié dòngcí","use": "Dùng cho hành động chưa xảy ra hoặc thường ngày; động từ một âm tiết lặp thành VV hoặc V一V.","note": "Không dùng với 了 sau lặp (V了V cho quá khứ). Không dùng lặp cho động từ trạng thái như 是, 有.","src": "file"}],["Động từ + 在 (住在, 坐在)","chủ ngữ + động từ + 在 + nơi chốn","Một số động từ (住, 坐, 站, 放, 躺...) đi với 在 để nói vị trí kết quả hoặc nơi ở.",[["我住在北京。","Wǒ zhù zài Běijīng.","Tôi sống ở Bắc Kinh."],["他坐在我旁边。","Tā zuò zài wǒ pángbiān.","Anh ấy ngồi bên cạnh tôi."],["请把书放在桌子上。","Qǐng bǎ shū fàng zài zhuōzi shàng.","Xin hãy đặt sách lên bàn."]],{"py": "dòngcí + zài","use": "Đặt 在 + nơi chốn ngay sau động từ.","note": "Khác với 在 + nơi chốn + động từ (hành động diễn ra ở đâu): 他在床上睡觉 (nơi ngủ) khác 他睡在床上 (nằm lại trên giường)."}],["一下 (một chút)","động từ + 一下","一下 làm hành động nhẹ, ngắn, lịch sự hơn, hoặc nói 'thử một lần'.",[["我看一下。","Wǒ kàn yíxià","Tôi xem một chút."],["你休息一下吧。","Nǐ xiūxī yíxià ba","Bạn nghỉ ngơi một chút đi."]],{"py": "yíxià","use": "Đặt sau động từ, tân ngữ đứng sau 一下.","note": "Không dùng với tính từ hay động từ trạng thái. Không dùng cho hành động kéo dài lâu.","src": "file"}],["Tân ngữ kép (cho, dạy, nói…)","chủ ngữ + động từ + tân ngữ gián tiếp + tân ngữ trực tiếp","Một số động từ (给, 教, 告诉, 问, 送) cần hai tân ngữ: người nhận và vật/việc.",[["他教我们汉语。","Tā jiāo wǒmen Hànyǔ.","Anh ấy dạy chúng tôi tiếng Trung."],["老师给了我一本书。","Lǎoshī gěi le wǒ yì běn shū.","Thầy giáo đưa cho tôi một quyển sách."],["请告诉我你的名字。","Qǐng gàosu wǒ nǐ de míngzi.","Xin cho tôi biết tên bạn."]],{"py": "shuāng bīnyǔ","use": "Người nhận đứng trước, vật hoặc việc đứng sau.","note": "Không đảo thứ tự hoặc thêm 给 vào giữa: nói 他教我汉语, không nói 他教汉语我."}],["Bổ ngữ mức độ 得","động từ + 得 + tính từ ; (động từ +) tân ngữ + động từ + 得 + tính từ","得 nối động từ với phần mô tả mức độ hoặc cách thức thực hiện hành động.",[["他跑得很快。","Tā pǎo de hěn kuài","Anh ấy chạy rất nhanh."],["房间打扫得特别干净。","Fángjiān dǎsǎo de tèbié gānjìng","Phòng được dọn đặc biệt sạch sẽ."]],{"py": "chéngdù bǔyǔ de","use": "Nếu có tân ngữ, lặp lại động từ: 他说汉语说得很好.","note": "Không đặt tính từ trực tiếp sau động từ. Phủ định đặt 不 trước tính từ: 说得不好. Không nói 他说得很好汉语.","src": "file"}],["Bổ ngữ kết quả (完, 好, 到, 见)","động từ + bổ ngữ kết quả","Bổ ngữ kết quả đặt ngay sau động từ để nói kết quả của hành động (xong, tốt, đạt, thấy...).",[["我看见你的朋友了。","Wǒ kàn jiàn nǐ de péngyǒu le","Tôi nhìn thấy bạn của bạn rồi."],["大卫找到工作了。","Dàwèi zhǎo dào gōngzuò le","Đại Vệ đã tìm được việc làm rồi."]],{"py": "jiéguǒ bǔyǔ","use": "Dùng 没 để phủ định, không dùng 不.","note": "Phủ định dùng 没(有), thêm 了 vào câu khẳng định: 我看完了 / 我没看完. Không nói 我不看完.","src": "file"}],["Bổ ngữ khả năng cơ bản (V不懂)","động từ + 得 / 不 + bổ ngữ","Chèn 得 hoặc 不 giữa động từ và bổ ngữ kết quả để nói 'có thể / không thể làm được'.",[["我听不懂。","Wǒ tīng bu dǒng.","Tôi nghe không hiểu."],["你看得清楚吗？","Nǐ kàn de qīngchu ma?","Bạn có nhìn rõ không?"],["太远了，我听不见。","Tài yuǎn le, wǒ tīng bu jiàn.","Xa quá, tôi không nghe thấy."]],{"py": "kěnéng bǔyǔ","use": "Khẳng định: 听得懂; phủ định: 听不懂. Dùng nhiều với 懂, 见, 到, 完.","note": "Phủ định thường dùng nhiều hơn khẳng định. Không dùng 能 + động từ + 懂 một cách thừa."}],["每 (mỗi), 每次……都","每 + lượng từ + danh từ + 都 + động từ","每 chỉ từng cá thể trong tổng thể; thường kết hợp 都 để nhấn 'ai cũng như vậy'.",[["山姆每年都去中国旅游。","Shānmǔ měi nián dōu qù Zhōngguó lǚyóu","Sam mỗi năm đều đi du lịch Trung Quốc. ."],["我每天六点起床工作吗？","Wǒ měi tiān liù diǎn qǐchuáng gōngzuò ma","Tôi có phải mỗi ngày 6 giờ thức dậy làm việc không?"]],{"py": "měi, měi cì … dōu","use": "Dùng 每 + lượng từ; 都 đặt trước động từ ở vế sau.","note": "Không bỏ lượng từ giữa 每 và danh từ (trừ 每天, 每年). Không nói 每次都不…. nhầm với 每次不…","src": "file"}],["第 + số (thứ tự)","第 + số + lượng từ + danh từ","第 đặt trước số để nói số thứ tự: thứ nhất, thứ hai...",[["第一本书","Dì yī běn shū","Cuốn sách thứ nhất."],["第二次跳舞","Dì èr cì tiàowǔ","Lần múa thứ hai."]],{"py": "dì + shù","use": "Dùng 第 + số + lượng từ (+ danh từ).","note": "Số thứ tự không bắt buộc dùng 第 trong ngày tháng. 第一 là thứ nhất; không nói 一第.","src": "file"}],["Câu hỏi chính phản (V不V)","động từ + 不 + động từ ; tính từ + 不 + tính từ","Hỏi bằng cách đặt khẳng định và phủ định cạnh nhau; câu trả lời chọn một trong hai.",[["你去不去？","Nǐ qù bu qù?","Bạn có đi không?"],["这个好不好吃？","Zhège hǎo bu hǎochī?","Cái này có ngon không?"],["你有没有时间？","Nǐ yǒu méiyǒu shíjiān?","Bạn có thời gian không?"]],{"py": "zhèngfǎn wènjù","use": "Không thêm 吗 vào cuối.","note": "Không dùng 吗 cùng cấu trúc này: 你去不去？ (✓), 你去不去吗？ (✗). Với 有 dùng 有没有."}],["Hỏi lý do: 为什么 / 怎么","为什么 / 怎么 + câu","Hỏi nguyên nhân của một sự việc.",[["你怎么不高兴？","Nǐ zěnme bù gāoxìng","Sao bạn không vui?"],["今天怎么这么热？","Jīntiān zěnme zhème rè","Sao hôm nay nóng thế?"]],{"py": "wèishénme / zěnme","use": "为什么 dùng được ở nhiều ngữ cảnh; 怎么 mang nghĩa ngạc nhiên hoặc thắc mắc.","note": "怎么 + động từ có hai nghĩa: 'làm thế nào' và 'sao lại'. Câu 你怎么没来？ hỏi lý do và mang sắc thái ngạc nhiên.","src": "file"}],["Câu hỏi đuôi (……，好吗？)","câu + ，好吗？ / 对吗？ / 可以吗？","Thêm một câu hỏi ngắn ở cuối để xin ý kiến hoặc xác nhận.",[["我们一起去吃饭，好吗？","Wǒmen yìqǐ qù chī fàn, hǎo ma","Chúng ta cùng đi ăn cơm nhé?"],["你明天下午给我打电话，好吗？","Nǐ míngtiān xiàwǔ gěi wǒ dǎ diànhuà, hǎo ma","Chiều mai bạn gọi điện thoại cho tôi nhé?"]],{"py": "wèn wěi","use": "Dùng 好吗, 对吗, 是吗, 可以吗 sau dấu phẩy.","note": "Không dùng 吗 sau 好不好. Nếu câu đề nghị đã có 吧 thì không cần thêm 好吗.","src": "file"}],["因为……所以……","因为 + nguyên nhân，所以 + kết quả","Nói quan hệ nguyên nhân – kết quả.",[["因为天气不好，所以我没去商店。","Yīnwèi tiānqì bù hǎo, suǒyǐ wǒ méi qù shāngdiàn","Bởi vì thời tiết không tốt, nên tôi không đi cửa hàng."],["因为汉字太难了，所以我不喜欢写汉字。","Yīnwèi Hànyǔ tài nán le, suǒyǐ wǒ bù xǐhuān xiě Hànzì","Bởi vì chữ Hán khó quá, nên tôi không thích viết chữ Hán."]],{"py": "yīnwèi … suǒyǐ …","use": "Có thể dùng đủ cặp hoặc chỉ một từ.","note": "Không dùng 因为 và 所以 cùng ở một vế. Tiếng Việt có thể dùng cặp 'vì… nên…', tiếng Trung cũng vậy nhưng không bắt buộc dùng cả hai.","src": "file"}],["什么都 / 谁都 (bất cứ…)","什么 / 谁 / 哪儿 + 都 / 也 + động từ","Từ nghi vấn kết hợp 都 để nói 'bất cứ ... đều'; phủ định thì thành 'không ... nào cả'.",[["我什么都不想吃。","Wǒ shénme dōu bù xiǎng chī.","Tôi chẳng muốn ăn gì cả."],["这个问题谁都知道。","Zhège wèntí shéi dōu zhīdào.","Vấn đề này ai cũng biết."],["他哪儿都没去。","Tā nǎr dōu méi qù.","Anh ấy chẳng đi đâu cả."]],{"py": "shénme dōu / shéi dōu","use": "Từ nghi vấn đứng trước 都 và động từ.","note": "Thường đặt chủ đề trước: 我什么都不想吃. Không dùng với 吗."}],["So sánh: 一点儿 / 得多 / 多了","A + 比 + B + tính từ + 一点儿 / 得多 / 多了","Thêm mức chênh lệch vào câu 比: nhẹ (一点儿) hoặc lớn (得多, 多了).",[["西瓜比苹果贵两块钱。","Xīguā bǐ píngguǒ guì liǎng kuài qián","Dưa hấu đắt hơn táo hai tệ."],["她比我们老师小两岁。","Tā bǐ wǒmen lǎoshī xiǎo liǎng suì","Cô ấy nhỏ hơn giáo viên của chúng tôi hai tuổi."]],{"py": "yìdiǎnr / de duō / duō le","use": "Mức chênh lệch đặt sau tính từ.","note": "Không đặt 很 trước tính từ trong câu 比. Không dùng 比 + 非常; nói 比他高得多 (✓).","src": "file"}],["会 / 能 / 可以 (phân biệt)","会 / 能 / 可以 + động từ","会 là biết (học được), 能 là có khả năng hoặc điều kiện cho phép, 可以 là được phép.",[["他会说汉语。","Tā huì shuō Hànyǔ.","Anh ấy biết nói tiếng Trung."],["我感冒了，不能去。","Wǒ gǎnmào le, bù néng qù.","Tôi bị cảm nên không đi được."],["这里可以坐吗？","Zhèlǐ kěyǐ zuò ma?","Ở đây ngồi được không?"]],{"py": "huì / néng / kěyǐ","use": "Chọn theo nghĩa: kỹ năng (会), khả năng/điều kiện (能), cho phép (可以).","note": "Với 能 và 可以 trong nghĩa 'được phép' thường dùng thay nhau. 会 không dùng để hỏi xin phép."}],["Cách diễn tả số lượng\"几\"","Cách diễn tả số lượng\"几\"","几 dùng để hỏi về số lượng ít, ước chừng dưới 10. Cấu trúc cơ bản: 几 + Lượng từ + Danh từ?",[["这里住着几个人？","Zhèlǐ zhù zhe jǐ gè rén","Ở đây có mấy người ở?"],["你学中文学了几年了？","Nǐ xué Zhōngwén xué le jǐ nián le","Bạn học tiếng Trung được mấy năm rồi?"]],{"py": "jǐ","use": "","note": "","src": "file"}],["Câu hỏi với\"是 不是...\"","Câu hỏi với\"是 不是...\"","Nếu đưa ra phỏng đoán về một sự việc hoặc tình huống và muốn xác minh thêm, có thể dùng cấu trúc câu hỏi này. \"是不 是...\" thường dùng ở phía trước vị ngữ, nhưng cũng có thể dùng ở đầu hoặc cuối câu.",[["你很少生病，是不是喜欢运动？","Nǐ hěn shǎo shēngbìng, shì bù shì xǐhuan yùndòng","Cậu rất ít khi ốm, có phải là thích vận động không?"],["是不是明天爸爸休息?","Shì bù shì míngtiān bàba xiūxi","Có phải ngày mai bố nghỉ không?"]],{"py": "shì.bú shì..","use": "","note": "","src": "file"}],["Đại từ nghi vấn\"多”\"","Đại từ nghi vấn\"多”\"","多 được dùng để hỏi về độ cao, chiều dài, tuổi tác, khoảng cách, thời gian, giá cả... - tức là những thứ có thể đo lường được bằng con số.",[["你多大？","Nǐ duō dà","Bạn bao nhiêu tuổi?"],["他儿子多高？","Tā érzi duō gāo","Con trai anh ấy cao bao nhiêu?"]],{"py": "duō","use": "","note": "","src": "file"}],["Cụm từ có\"的”\"","Cụm từ có\"的”\"","Đại từ, tính từ, động từ kết hợp với \"的\" để tạo thành cụm từ trung tâm ngữ, tương đương với cụm danh từ để thay thế",[["这本书不是我的。","Zhè běn shū bú shì wǒ de","Cuốn sách này không phải của tôi."],["这块表是你的吗？","Zhè kuài shǒubiǎo shì nǐ de ma","Cái đồng hồ này là của bạn à?"]],{"py": "de","use": "","note": "","src": "file"}],["Cấu trúc\"是...的\"","Cấu trúc\"是...的\"","Dùng để nhấn mạnh chi tiết (thời gian, địa điểm, cách thức, đối tượng, mục đích...) của một sự việc đã xảy ra trong quá khứ.",[["这本书是我买的。","Zhè běn shū shì wǒ mǎi de","Cuốn sách này là do tôi mua."],["手机不是我弄坏的。","Shǒujī bú shì wǒ nòng huài de","Điện thoại không phải là tôi làm hỏng đâu."]],{"py": "shì... de","use": "","note": "","src": "file"}],["Sự lặp lại lượng từ","Sự lặp lại lượng từ","Lượng từ (量词) khi được lặp lại sẽ có dạng \"AA\" hoặc \"一AA\", biểu thị ý nghĩa \"mỗi/từng...\", \"từng cái một\", \"rất nhiều\", hoặc tạo nhịp điệu, tính hình tượng cho câu văn.",[["这些苹果个个都很甜。","Zhèxiē píngguǒ gègè dōu hěn tián","Những quả táo này quả nào cũng rất ngọt."],["这个商店的衣服件件都很漂亮。","Zhège shāngdiàn de yīfu jiàn jiàn dōu hěn piàoliang","Quần áo ở cửa hàng này cái nào cũng rất đẹp."]],{"py": "","use": "","note": "","src": "file"}],["Phó từ ngữ khí\"还”\"","Phó từ ngữ khí\"还”\"","Biểu thị hành động hoặc trạng thái vẫn đang tiếp diễn.",[["八点了，他还在睡觉。","Bā diǎn le, tā hái zài shuìjiào","Tám giờ rồi, anh ấy vẫn còn ngủ."],["你怎么还没吃饭？","Nǐ zěnme hái méi chī fàn","Sao bạn vẫn chưa ăn cơm?"]],{"py": "hái","use": "","note": "","src": "file"}],["Phó từ chỉ thời gian\"就\"","Phó từ chỉ thời gian\"就\"","Nhấn mạnh sự việc xảy ra sớm, thuận lợi hoặc đạt được quan điểm của người nói.",[["电影七点开始，他六点就来了。","Diànyǐng qī diǎn kāishǐ, tā liù diǎn jiù lái le","Phim 7 giờ bắt đầu, anh ấy 6 giờ đã đến rồi."],["我昨天就知道这个消息了。","Wǒ zuótiān jiù zhīdào zhège xiāoxi le","Tôi hôm qua đã biết tin này rồi."]],{"py": "jiù","use": "","note": "","src": "file"}],["Trợ từ ngữ khí\"呢\"","Trợ từ ngữ khí\"呢\"","Dùng ở cuối câu trần thuật sau động từ/tính từ, biểu thị sự khẳng định, tin tưởng.",[["八点上课，时间还早呢。","Bā diǎn shàngkè, shíjiān hái zǎo ne","Tám giờ vào lớp, thời gian vẫn còn sớm."],["医院离我们这儿还远呢。","Yīyuàn lí wǒmen zhèr hái yuǎn ne","Bệnh viện cách chỗ chúng ta còn xa đấy."]],{"py": "ne","use": "","note": "","src": "file"}],["Câu kiêm ngữ (兼语)","Câu kiêm ngữ (兼语)","Câu kiêm ngữ do hai cụm động từ tạo thành, trong đó động từ thứ nhất thường là \"请 /qǐng/, 让 /ràng/, 叫 /jiào/\". Cấu trúc: Chủ ngữ 1 + Động từ 1 + Kiêm ngữ + Động từ 2 + (Tân ngữ)",[["我请你吃饭。","Wǒ qǐng nǐ chī fàn","Tôi mời bạn ăn cơm."],["老师让我写汉字。","Lǎoshī ràng wǒ xiě Hànzì","Giáo viên bảo tôi viết chữ Hán."]],{"py": "","use": "","note": "","src": "file"}],["Trợ động từ\"可 能\"","Trợ động từ\"可 能\"","Biểu thị sự phỏng đoán, có lẽ, có thể. Thường dùng trước động từ hoặc sau chủ ngữ.",[["他可能就知道这件事情了。","Tā kěnéng jiù zhīdào zhè jiàn shìqing le","Có lẽ anh ấy biết chuyện này rồi."],["你可能不认识他。","Nǐ kěnéng bù rènshi tā","Bạn có thể không quen biết anh ấy."]],{"py": "kěnéng","use": "","note": "","src": "file"}],["Câu có từ\"比\"với bổ ngữ trạng thái","Câu có từ\"比\"với bổ ngữ trạng thái","Nếu động từ có bổ ngữ trạng thái, \"比\" có thể đặt trước động từ hoặc trước bổ ngữ.",[["他比我学得好。","Tā bǐ wǒ xué de hǎo","Anh ấy học tốt hơn tôi."],["他比我跑得快得多。","Tā bǐ wǒ pǎo de kuài de duō","Anh ấy chạy nhanh hơn tôi nhiều."]],{"py": "bǐ","use": "","note": "","src": "file"}],["Câu hỏi phản vấn\"不是......吗?\"","Câu hỏi phản vấn\"不是......吗?\"","Thường dùng để nhắc nhở hoặc biểu thị sự không hiểu, không hài lòng.",[["不是今天没有雨吗？","Bú shì jīntiān méiyǒu yǔ ma","Không phải hôm nay không có mưa sao?"],["不是你是北京人吗？","Bú shì nǐ shì Běijīng rén ma","Không phải bạn là người Bắc Kinh sao?"]],{"py": "","use": "","note": "","src": "file"}],["Cấu trúc\"虽然..., 但是...\"","Cấu trúc\"虽然..., 但是...\"","Kết nối hai phân câu, cấu thành quan hệ chuyển ngoặt.",[["虽然外面很冷，但是房间里很热。","Suīrán wàimiàn hěn lěng, dànshì fángjiān lǐ hěn rè","Mặc dù bên ngoài rất lạnh, nhưng trong phòng rất ấm."],["虽然汉语很难，但是我很喜欢写汉字。","Suīrán Hànyǔ hěn nán, dànshì wǒ hěn xǐhuān xiě Hànzì","Mặc dù tiếng Hán khó, nhưng tôi rất thích viết chữ Hán."]],{"py": "","use": "","note": "","src": "file"}],["Cấu trúc\"都...了\"","Cấu trúc\"都...了\"","Biểu thị ý nghĩa \"đã\", thường chứa sự nhấn mạnh hoặc ngữ khí không hài lòng.",[["都8点了，快点儿起床吧。","Dōu bā diǎn le, kuài diǎnr qǐchuáng ba","Đã 8 giờ rồi, mau dậy đi."],["你都十岁了，可以自己洗衣服了。","Nǐ dōu shí suì le, kěyǐ zìjǐ xǐ yīfu le","Bạn đã 10 tuổi rồi, có thể tự giặt quần áo rồi."]],{"py": "dōu... le","use": "","note": "","src": "file"}]],"3": [["把字句","S + 把 + O + V + thành phần khác","Nhấn mạnh việc \"xử lý\" tân ngữ. Sau động từ phải có thành phần khác như 了, bổ ngữ kết quả hoặc 到.",[["请同学们把书拿出来。","Qǐng tóngxuémen bǎ shū ná chūlái","Mời các bạn học sinh lấy sách ra."],["你把灯关了吧。","Nǐ bǎ dēng guān le ba","Bạn tắt đèn đi."]],{"py": "bǎzìjù","use": "Đưa tân ngữ lên trước động từ để nhấn mạnh việc xử lý, tác động lên tân ngữ đó và kết quả của nó.","note": "Tân ngữ sau 把 phải xác định (这本书, 那杯茶). Sau động từ cần có thành phần khác (了, kết quả, xu hướng, ...), không để động từ trơ trọi.","src": "file"}],["被字句 (bị động)","O + 被 + (S) + V + thành phần khác","Chủ ngữ là đối tượng chịu tác động. Thường dùng khi có việc không mong muốn.",[["我的自行车被偷了。","Wǒ de zìxíngchē bèi tōu le","Xe đạp của tôi bị trộm rồi."],["我被朋友影响了。","Wǒ bèi péngyou yǐngxiǎng le","Tôi bị bạn bè ảnh hưởng."]],{"py": "bèizìjù","use": "Câu bị động: chủ thể chịu tác động đứng đầu, 被 dẫn tác nhân; thường mang sắc thái không như ý nhưng không bắt buộc.","note": "Sau động từ cần có thành phần khác như 了 hay bổ ngữ. Có thể lược tác nhân sau 被. Khẩu ngữ hay dùng 让/叫 thay 被 khi có tác nhân.","src": "file"}],["虽然……但是……","虽然 A，但是 B","Diễn tả sự nhượng bộ: \"tuy... nhưng...\". Trong tiếng Trung thường dùng cả hai vế, khác với tiếng Việt có thể bỏ một.",[["虽然很累，但是我很高兴。","Suīrán hěn lèi, dànshì wǒ hěn gāoxìng.","Tuy rất mệt nhưng tôi rất vui."],["虽然天气不好，我们还是去了。","Suīrán tiānqì bù hǎo, wǒmen háishi qù le.","Tuy thời tiết không tốt, chúng tôi vẫn đi."]],{"py": "suīrán … dànshì …","use": "Nhượng bộ: thừa nhận vế trước nhưng vế sau nói điều ngược lại.","note": "Không nên bỏ 但是/可是/不过 ở vế sau. Trong tiếng Trung có thể dùng cả hai từ, khác tiếng Anh 'although… but' chỉ dùng một."}],["如果……就……","如果 A，就 B","Câu điều kiện: nếu A thì B. 如果 có thể đứng sau chủ ngữ.",[["如果你太累了，就休息一会儿。","Rúguǒ nǐ tài lèi le, jiù xiūxí yīhuìr","Nếu bạn quá mệt rồi, thì nghỉ ngơi một lát đi."],["如果你喜欢，我就给你买。","Rúguǒ nǐ xǐhuan, wǒ jiù gěi nǐ mǎi","Nếu bạn thích, tôi sẽ mua cho bạn."]],{"py": "rúguǒ … jiù …","use": "Điều kiện giả định: nếu vế trước xảy ra thì có vế sau.","note": "Dùng 就 ở vế sau; không dùng 才 trong cấu trúc này. Có thể thay 如果 bằng 要是, 假如 (văn phong thân mật hoặc trang trọng hơn).","src": "file"}],["越来越……","越来越 + tính từ / động từ tâm lý","Diễn tả mức độ tăng dần theo thời gian: \"ngày càng...\".",[["这个问题越来越复杂。","Zhège wèntí yuè lái yuè fùzá","Vấn đề này càng lúc càng phức tạp."],["他的汉语说得越来越流利。","Tā de Hànyǔ shuō de yuè lái yuè liúlì","Tiếng Trung của anh ấy nói ngày một lưu loát."]],{"py": "yuè lái yuè …","use": "Diễn tả mức độ tăng dần theo thời gian: ngày càng...","note": "Không dùng với tính từ chỉ trạng thái cố định (như 对, 错). Không đi với số lượng cụ thể. Dùng 越……越…… khi hai yếu tố cùng thay đổi.","src": "file"}],["……极了 (cực kỳ)","tính từ / động từ tâm lý + 极了","Đặt 极了 sau tính từ để nhấn mức độ rất cao, tương đương 'cực kỳ, quá chừng'.",[["我的小狗可爱极了。","Wǒ de xiǎo gǒu kě'ài jíle","Chú chó nhỏ của tôi đáng yêu vô cùng."],["他满意极了。","Tā mǎnyì jíle","Anh ấy cực kỳ hài lòng."]],{"py": "jí le","use": "Đứng cuối cụm, thường có thêm 了 ở cuối câu.","note": "Không dùng 很 hay 非常 cùng 极了. Không dùng với phủ định: không nói 不好极了.","src": "file"}],["Lặp tính từ (AA, AABB)","AA / AABB + (的 / 地)","Lặp tính từ để tăng tính sinh động hoặc thân mật; AA cho tính từ một âm, AABB cho tính từ hai âm.",[["你送的红红的花，我很喜欢。","Nǐ sòng de hónghóng de huā, wǒ hěn xǐhuan","Bó hoa đỏ tươi bạn tặng, tôi rất thích."],["你女儿长得白白的，胖胖的，真可爱。","Nǐ nǚ'ér zhǎng de báibái de, pàngpàng de, zhēn kě'ài","Con gái bạn trắng trẻo, mũm mĩm, thật đáng yêu"]],{"py": "xíngróngcí chóngdié","use": "Dùng AA trước danh từ (大大的眼睛) hoặc làm trạng ngữ (慢慢地走).","note": "Không thêm 很 trước tính từ đã lặp. Không phải tính từ nào cũng lặp được, ví dụ 对 và 错 không lặp.","src": "file"}],["一直 (suốt, liên tục)","chủ ngữ + 一直 + động từ","一直 nói một trạng thái hay hành động kéo dài không gián đoạn, hoặc đi thẳng một hướng.",[["昨晚我一直在等你。","Zuówǎn wǒ yìzhí zài děng nǐ.","Tối qua tôi cứ đợi bạn suốt."],["一直往前走，就能看到银行。","Yìzhí wǎng qián zǒu, jiù néng kàndào yínháng.","Đi thẳng phía trước là thấy ngân hàng."]],{"py": "yìzhí","use": "Đặt 一直 trước động từ; có thể đi với 以来 hoặc từ chỉ thời gian.","note": "Không dùng 一直 với hành động chỉ xảy ra một lần. Phủ định: 一直没……(suốt chưa…)."}],["总是 (luôn luôn)","chủ ngữ + 总是 + động từ","总是 nói một việc lặp lại đều đặn, có khi mang ý phàn nàn.",[["他总是迟到。","Tā zǒngshì chídào.","Anh ấy lúc nào cũng đến muộn."],["妈妈总是关心我。","Māma zǒngshì guānxīn wǒ.","Mẹ lúc nào cũng quan tâm tôi."]],{"py": "zǒngshì","use": "Đặt 总是 trước động từ.","note": "Phủ định hoàn toàn nên dùng 从来不 (không phải 不总是). 不总是 nghĩa là 'không phải lúc nào cũng'."}],["终于 (cuối cùng cũng)","chủ ngữ + 终于 + động từ (+ 了)","终于 nói điều đã mong đợi hoặc chờ lâu nay đã xảy ra.",[["他终于找到工作了。","Tā zhōngyú zhǎodào gōngzuò le.","Cuối cùng anh ấy cũng tìm được việc."],["等了两个小时，车终于来了。","Děng le liǎng ge xiǎoshí, chē zhōngyú lái le.","Đợi hai tiếng, cuối cùng xe cũng đến."]],{"py": "zhōngyú","use": "Đặt 终于 trước động từ; thường kèm 了 ở cuối.","note": "Chỉ dùng cho điều xảy ra sau một thời gian chờ. Không dùng với kết quả không như ý (dùng 最后)."}],["才 (mới, muộn)","thời điểm + 才 + động từ ; 只有……才……","才 nói việc xảy ra muộn, khó khăn, hoặc số lượng ít hơn mong đợi.",[["他十二点才回家。","Tā shí'èr diǎn cái huí jiā.","Mười hai giờ anh ấy mới về nhà."],["这件衣服才五十块。","Zhè jiàn yīfu cái wǔshí kuài.","Bộ này mới có năm mươi tệ."]],{"py": "cái","use": "Đặt 才 sau thời điểm hay điều kiện, trước động từ.","note": "So với 就: 才 nhấn muộn hoặc ít, 就 nhấn sớm hoặc nhanh. Không dùng 了 sau động từ khi có 才."}],["只 (chỉ)","只 + động từ / số lượng","只 giới hạn phạm vi: chỉ có, chỉ làm.",[["我只会说一点儿汉语。","Wǒ zhǐ huì shuō yìdiǎnr Hànyǔ.","Tôi chỉ biết nói một chút tiếng Trung."],["教室里只有三个人。","Jiàoshì lǐ zhǐ yǒu sān ge rén.","Trong lớp chỉ có ba người."]],{"py": "zhǐ","use": "Đặt 只 trước động từ hoặc trước số từ.","note": "Khác 只有 (chỉ có … mới) và 只要 (chỉ cần). 只 đứng trước 动词 hoặc 数量词."}],["先……再…… (trước … sau …)","先 + động từ 1，再 + động từ 2","Sắp xếp thứ tự hai hành động: làm A trước rồi mới làm B.",[["我先洗完澡，然后再给你回电话。","Wǒ xiān xǐ wán zǎo, ránhòu zài gěi nǐ huí diànhuà","Tôi đi tắm xong trước, sau đó gọi lại cho bạn."],["你先把饭菜做好，然后再把一块新鲜的水果放进去。","Nǐ xiān bǎ fàncài zuò hǎo, ránhòu zài bǎ yī kuài xīnxiān de shuǐguǒ fàng jìnqù","Bạn làm xong cơm trước, sau đó đặt thêm một miếng hoa quả tươi vào."]],{"py": "xiān … zài …","use": "Cũng có thể thêm 然后 giữa hai vế.","note": "Không dùng 才 thay cho 再 trong cấu trúc này. 再 ở đây chỉ việc làm sau, chưa xảy ra.","src": "file"}],["一边……一边……","(chủ ngữ) + 一边 + động từ 1 + 一边 + động từ 2","Hai hành động xảy ra đồng thời với cùng một chủ ngữ.",[["妈妈一边唱歌一边做饭。","Māmā yībiān chànggē yībiān zuòfàn","Mẹ vừa hát vừa nấu cơm."],["我丈夫喜欢一边吃早饭一边看报纸。","Wǒ zhàngfu xǐhuan yībiān chī zǎofàn yībiān kàn bàozhǐ","Chồng tôi thích vừa ăn sáng vừa đọc báo."]],{"py": "yìbiān … yìbiān …","use": "Có thể bỏ 一 trước 边 trong khẩu ngữ.","note": "Chủ ngữ phải giống nhau. Hai hành động nên là hành động kéo dài, không dùng với 去 hay 来.","src": "file"}],["又……又…… (vừa … vừa …)","又 + tính từ / động từ + 又 + tính từ / động từ","Nêu hai đặc điểm hoặc hai trạng thái cùng tồn tại.",[["这个西瓜又大又甜。","Zhège xīguā yòu dà yòu tián","Quả dưa hấu này vừa to vừa ngọt."],["她工作又认真又热情。","Tā gōngzuò yòu rènzhēn yòu rèqíng","Cô ấy làm việc vừa nghiêm túc vừa nhiệt tình."]],{"py": "yòu … yòu …","use": "Hai vế cùng loại: tính từ với tính từ, động từ với động từ.","note": "Hai vế nên cùng nghĩa tốt hoặc cùng nghĩa xấu: không nói 又便宜又不好吃 nếu muốn khen.","src": "file"}],["比较 (khá, tương đối)","比较 + tính từ","比较 nói mức độ ở mức khá, tương đối, thường mang ý so sánh ngầm.",[["这里的东西比较贵。","Zhèlǐ de dōngxi bǐjiào guì.","Đồ ở đây khá đắt."],["我比较喜欢吃面条。","Wǒ bǐjiào xǐhuan chī miàntiáo.","Tôi khá thích ăn mì."]],{"py": "bǐjiào","use": "Đặt 比较 trước tính từ hoặc động từ tâm lý.","note": "比较 ≠ 比 (câu so sánh). Không nói 比较比. Dùng để nêu nhận xét nhẹ nhàng."}],["跟……一样 (giống như)","A + 跟 + B + 一样 (+ tính từ)","So sánh sự giống nhau giữa hai đối tượng.",[["这本书跟那本书一样。","Zhè běn shū gēn nà běn shū yīyàng","Quyển sách này giống quyển sách kia."],["她的汉语说得跟中国人一样好。","Tā de Hànyǔ shuō de gēn Zhōngguó rén yīyàng hǎo","Tiếng Hán của cô ấy nói hay như người Trung Quốc."]],{"py": "gēn … yíyàng","use": "Phủ định: 不一样 hoặc 跟……不一样.","note": "Không dùng 很 trước 一样 khi cần nói 'giống hệt' (dùng 一模一样). Có thể thêm tính từ sau 一样.","src": "file"}],["没有 (so sánh không bằng)","A + 没有 + B + (这么 / 那么) + tính từ","Phủ định so sánh: A không bằng B.",[["今年没有去年冷。","Jīnnián méiyǒu qùnián lěng.","Năm nay không lạnh bằng năm ngoái."],["我没有他那么忙。","Wǒ méiyǒu tā nàme máng.","Tôi không bận như anh ấy."]],{"py": "méiyǒu","use": "Không thêm mức độ như 很 sau 没有.","note": "没有 nghĩa 'không bằng'; 不比 nghĩa 'không hơn' (có thể ngang hoặc kém), hai cấu trúc không thay nhau hoàn toàn."}],["还是 (hay là) và 或者","A 还是 B ? ; A 或者 B","还是 dùng trong câu hỏi lựa chọn; 或者 dùng trong câu trần thuật.",[["你喜欢喝咖啡还是喝茶？","Nǐ xǐhuan hē kāfēi háishì hē chá","Bạn thích uống cà phê hay trà?"],["明天是晴天或者阴天都可以。","Míngtiān shì qíngtiān huòzhě yīntiān dōu kěyǐ","Ngày mai trời nắng hoặc trời râm đều được."]],{"py": "háishi / huòzhě","use": "Hỏi: 你喝茶还是咖啡？ Nêu: 茶或者咖啡都可以.","note": "Không dùng 或者 trong câu hỏi lựa chọn; không dùng 还是 trong câu trần thuật.","src": "file"}],["刚才 và 刚","刚才 + động từ ; 刚 + động từ","刚才 chỉ khoảng thời gian vừa qua; 刚 chỉ hành động vừa kết thúc.",[["刚才我喝了一杯咖啡。","Gāngcái wǒ hē le yī bēi kāfēi","Lúc nãy tôi đã uống một tách cà phê."],["我刚喝完一杯咖啡。","Wǒ gāng hē wán yī bēi kāfēi","Tôi vừa mới uống xong một tách cà phê."]],{"py": "gāngcái / gāng","use": "刚才 là danh từ thời gian, đặt đầu hoặc sau chủ ngữ; 刚 là phó từ đặt trước động từ.","note": "刚才 là danh từ thời gian nên đứng đầu câu được; 刚 là phó từ nên chỉ đứng trước động từ.","src": "file"}],["后来 (sau đó, về sau)","后来 + động từ","后来 kể diễn biến sau một mốc trong quá khứ.",[["他先去北京，后来去了上海。","Tā xiān qù Běijīng, hòulái qù le Shànghǎi.","Anh ấy đi Bắc Kinh trước, sau đó đi Thượng Hải."],["我们后来再也没见过面。","Wǒmen hòulái zài yě méi jiàn guo miàn.","Sau đó chúng tôi không gặp lại nhau lần nào."]],{"py": "hòulái","use": "Dùng trong lời kể quá khứ; đầu câu hoặc sau chủ ngữ.","note": "Chỉ dùng cho quá khứ, không dùng cho tương lai (dùng 以后). Không đi sau số lượng thời gian."}],["关于 (về)","关于 + chủ đề + (的 + danh từ)","关于 nêu chủ đề của nội dung được nói đến hay viết về.",[["我最近看了一些关于中国文化的电影。","Wǒ zuìjìn kàn le yīxiē guānyú Zhōngguó wénhuà de diànyǐng","Gần đây tôi xem một vài bộ phim về văn hóa Trung Quốc."],["关于这个工作，还有什么问题吗？","Guānyú zhège gōngzuò, hái yǒu shénme wèntí ma","Về công việc này, còn có vấn đề gì không?"]],{"py": "guānyú","use": "Thường làm định ngữ (关于……的书) hoặc đầu câu.","note": "Không dùng 关于 để chỉ đối tượng người (dùng 对). 关于 không đứng sau chủ ngữ trong câu ngắn.","src": "file"}],["直到 (mãi đến, cho đến khi)","直到 + thời điểm / sự việc，……","Nói một trạng thái kéo dài cho tới một mốc.",[["他工作到很晚，直到十二点才睡。","Tā gōngzuò dào hěn wǎn, zhídào shí'èr diǎn cái shuì.","Anh ấy làm việc đến khuya, mãi mười hai giờ mới ngủ."],["直到天黑，孩子们才回家。","Zhídào tiānhēi, háizimen cái huí jiā.","Mãi đến khi trời tối, bọn trẻ mới về nhà."]],{"py": "zhídào","use": "Có thể đi trước hoặc sau vế chính.","note": "Không dùng với hành động ngắn tức thời. Thường kết hợp với 才 ở vế sau để nhấn muộn."}],["向 (về phía)","向 + người / hướng + động từ","向 chỉ hướng hoặc đối tượng của hành động (học hỏi, xin, chào).",[["我要向你学习。","Wǒ yào xiàng nǐ xuéxí.","Tôi muốn học hỏi bạn."],["他向老师问了一个问题。","Tā xiàng lǎoshī wèn le yí ge wèntí.","Cậu ấy hỏi thầy giáo một câu."]],{"py": "xiàng","use": "Đặt 向 + đối tượng trước động từ.","note": "向 dùng được cho cả hướng (向前走) và đối tượng là người (向你学习); 往 chỉ thiên về hướng di chuyển."}],["看起来 (trông có vẻ)","看起来 + tính từ / cụm từ","Nêu nhận xét bề ngoài dựa trên quan sát.",[["他看起来很累。","Tā kàn qǐlái hěn lèi.","Anh ấy trông có vẻ rất mệt."],["看起来要下雨了。","Kàn qǐlái yào xià yǔ le.","Trông có vẻ sắp mưa."]],{"py": "kàn qǐlái","use": "Đặt đầu câu hoặc sau chủ ngữ.","note": "看起来 dựa trên quan sát trực tiếp; khác 听起来 (nghe có vẻ)."}],["Câu khiến: 让 / 叫 / 使","A + 让 / 叫 / 使 + B + động từ / tính từ","Nói A khiến hoặc cho phép B làm gì.",[["读书使我快乐。","Dúshū shǐ wǒ kuàilè","Đọc sách khiến tôi vui vẻ."],["考试让我很紧张。","Kǎoshì ràng wǒ hěn jǐnzhāng","Kỳ thi khiến tôi rất hồi hộp."]],{"py": "shǐdòngjù","use": "让 và 叫 dùng cho người, 使 dùng cho nguyên nhân trừu tượng.","note": "Phủ định: 不让, 不叫; không đặt 不 sau 让. 使 thường không dùng để ra lệnh.","src": "file"}],["应该 (nên, phải)","chủ ngữ + 应该 + động từ","Diễn đạt nghĩa vụ hoặc lời khuyên: nên, cần, đáng lẽ.",[["你应该早点儿睡觉。","Nǐ yīnggāi zǎodiǎnr shuì jiào.","Bạn nên đi ngủ sớm một chút."],["他应该已经到了。","Tā yīnggāi yǐjīng dào le.","Chắc anh ấy đã đến rồi."]],{"py": "yīnggāi","use": "Phủ định: 不应该. Cũng dùng để suy đoán: 他应该到了.","note": "Không thêm 很 trước 应该. Với hành động đã qua dùng 本来应该 hoặc 应该……了."}],["难 / 好 + động từ","难 / 好 + động từ","难 + động từ (khó làm), 好 + động từ (dễ làm, tốt để).",[["这个汉字很难写。","Zhège Hànzì hěn nán xiě.","Chữ Hán này rất khó viết."],["这首歌真好听。","Zhè shǒu gē zhēn hǎotīng.","Bài hát này nghe thật hay."]],{"py": "nán / hǎo + dòngcí","use": "Cặp thường gặp: 难看/好看, 难吃/好吃, 难听/好听, 难学/好学.","note": "Không thể dùng 难/好 trước mọi động từ; đây là các từ ghép cố định."}],["Thời lượng với 了","động từ + 了 + thời lượng + (的) + tân ngữ ; động từ + 了 + thời lượng + 了","Nói hành động kéo dài bao lâu. Thêm 了 cuối câu nghĩa là còn đang tiếp diễn đến giờ.",[["我学习了两年汉语了。","Wǒ xuéxí le liǎng nián Hànyǔ le","Tôi đã học tiếng Hán được hai năm rồi."],["我们在这儿坐了半个小时了。","Wǒmen zài zhèr zuò le bàn gè xiǎoshí le","Chúng tôi đã ngồi ở đây được nửa tiếng rồi."]],{"py": "shíliàng bǔyǔ + le","use": "Thời lượng đặt sau động từ, tân ngữ sau thời lượng hoặc lặp động từ.","note": "Không đặt thời lượng trước động từ: nói 我学了三年汉语, không nói 我三年学汉语.","src": "file"}],["没办法 (hết cách)","没办法 + động từ ; 没办法……","Nói không có cách nào làm được điều gì đó.",[["路堵得太厉害，我没办法准时到。","Lù dǔ de tài lìhai, wǒ méi bànfǎ zhǔnshí dào.","Tắc đường quá, tôi không cách nào đến đúng giờ."],["他不听我的，我也没办法。","Tā bù tīng wǒ de, wǒ yě méi bànfǎ.","Anh ấy không nghe tôi, tôi cũng hết cách."]],{"py": "méi bànfǎ","use": "Đặt trước động từ, nhấn sự bó tay.","note": "Không dùng 没办法 cho khả năng thông thường (dùng 不会/不能). Có thể đứng riêng như một câu: 没办法!"}],["Bổ ngữ xu hướng (上, 下, 进, 出...)","động từ + 来 / 去 / 上 / 下 / 进 / 出 / 回","Chỉ hướng di chuyển của hành động so với người nói.",[["我们在楼上等你呢，你上来吧。","Wǒmen zài lóu shàng děng nǐ ne, nǐ shàng lái ba","Chúng tôi ở trên lầu đợi bạn đấy, bạn lên đây đi."],["你把这张椅子搬过去吧。","Nǐ bǎ zhè zhāng yǐzi bān guòqù ba","Bạn chuyển cái ghế này qua đó đi."]],{"py": "qūxiàng bǔyǔ","use": "来 là về phía người nói, 去 là đi xa người nói.","note": "Khi có tân ngữ nơi chốn, đặt giữa: 他回学校去了 (✓); không nói 他回去学校了.","src": "file"}],["Bổ ngữ khả năng: V得了 / V不了","động từ + 得了 / 不了","得了 / 不了 nói có thể hoặc không thể hoàn thành một việc, đặc biệt về sức lực hoặc số lượng.",[["这个汉字太难，我写不对。","Zhège Hànzì tài nán, wǒ xiě bù duì","Chữ Hán này khó quá, tôi viết không đúng."],["你说慢一点儿，我听得懂","Nǐ shuō màn yīdiǎnr, wǒ tīng de dǒng","Bạn nói chậm một chút, tôi có thể nghe hiểu."],["这么多作业，你今天做得完做不完？","Zhème duō zuòyè, nǐ jīntiān zuò de wán zuò bù wán","Nhiều bài tập thế này, hôm nay bạn làm xong được không?"]],{"py": "kěnéng bǔyǔ liǎo","use": "Dùng khi kết quả phụ thuộc vào khả năng hoặc điều kiện.","note": "了 đọc là liǎo trong cấu trúc này. Không nhầm với 了 le hoàn thành.","src": "file"}],["有的 (một số)","有的 + danh từ ... ，有的 ……","有的 chỉ một phần trong tổng thể; thường lặp để đối chiếu.",[["班里有的同学喜欢唱歌，有的同学喜欢画画。","Bān lǐ yǒude tóngxué xǐhuan chàng gē, yǒude tóngxué xǐhuan huà huà.","Trong lớp có bạn thích hát, có bạn thích vẽ."],["这些书有的我看过。","Zhèxiē shū yǒude wǒ kàn guo.","Trong những sách này, có cuốn tôi đã đọc."]],{"py": "yǒude","use": "Đặt trước danh từ, hoặc dùng độc lập sau khi đã nêu chủ thể.","note": "有的 chỉ một bộ phận của tổng thể đã nêu trước đó, nên cần có tổng thể rõ ràng; không dùng với số lượng cụ thể."}],["一点儿也不 / 一……也不……","一点儿 / 一 + lượng từ + 也 / 都 + 不 / 没","Nhấn mạnh phủ định hoàn toàn: không … chút nào.",[["我一点儿东西也不想吃。","Wǒ yìdiǎnr dōngxi yě bù xiǎng chī","Một chút đồ ăn tôi cũng không muốn ăn."],["他一点儿也不累。","Tā yìdiǎnr yě bù lèi","Anh ấy một chút cũng không mệt."]],{"py": "yìdiǎnr yě bù","use": "Đặt 也/都 sau 一点儿 hoặc 一+lượng từ, rồi phủ định.","note": "Chỉ đi với phủ định. Không nói 一点儿也很好.","src": "file"}],["为了 (để, vì)","为了 + mục đích，……","为了 nêu mục đích của hành động.",[["为了身体健康，他每天跑步。","Wèile shēntǐ jiànkāng, tā měitiān pǎobù.","Để giữ sức khỏe, anh ấy chạy bộ mỗi ngày."],["我为了学汉语来中国。","Wǒ wèile xué Hànyǔ lái Zhōngguó.","Tôi đến Trung Quốc để học tiếng Trung."]],{"py": "wèile","use": "Đặt đầu vế đầu hoặc sau chủ ngữ.","note": "Dùng cho mục đích đã có kế hoạch. Không dùng 因为 để nêu mục đích."}],["跟……比 / 比……(so sánh mở rộng)","跟 + B + 比，A + …","Dùng 跟……比 để mở đầu so sánh: 'so với B thì A…'.",[["大山比大卫高一点儿。","Dàshān bǐ Dàwèi gāo yīdiǎn","Đại Sơn cao hơn Đại Vệ một chút"],["数学比历史难多了。","Shùxué bǐ lìshǐ nán duō le","Môn Toán khó hơn môn Lịch sử nhiều."]],{"py": "gēn … bǐ","use": "Đặt cụm 跟……比 đầu câu rồi nêu nhận xét.","note": "Không dùng 比 + 更 + 很. Có thể dùng 比起 (HSK5) với nghĩa tương tự.","src": "file"}],["要是……的话 (nếu … thì)","要是 + điều kiện + (的话)，就 + kết quả","要是 giống 如果; 的话 đặt cuối vế điều kiện để nhấn giả định.",[["要是明天下雨的话，我们就不去了。","Yàoshi míngtiān xià yǔ dehuà, wǒmen jiù bú qù le.","Nếu ngày mai mưa thì chúng ta không đi."],["你要是累了，就休息一下。","Nǐ yàoshi lèi le, jiù xiūxi yíxià.","Nếu bạn mệt thì nghỉ một chút."]],{"py": "yàoshi … dehuà","use": "Hai vế có thể bỏ 要是 hoặc 的话, giữ một trong hai là đủ.","note": "Không dùng 要是 cùng 如果 trong một vế. 就 ở vế sau là tùy chọn nhưng nghe tự nhiên."}],["Từ nghi vấn chỉ bất định (有人, 什么…)","有 + từ nghi vấn ; từ nghi vấn + (câu khẳng định)","Từ nghi vấn dùng trong câu khẳng định hoặc đề nghị mang nghĩa 'ai đó, cái gì đó, chỗ nào đó'.",[["什么东西便宜我就买什么。","Shénme dōngxi piányi wǒ jiù mǎi shénme","Cái gì rẻ thì tôi mua cái đó."],["你坐哪儿我就坐哪儿。","Nǐ zuò nǎr wǒ jiù zuò nǎr","Bạn ngồi đâu thì tôi ngồi đó."]],{"py": "bù dìng zhǐ","use": "Ví dụ: 有人 (có ai đó), 什么时候 (lúc nào đó), 想吃点儿什么.","note": "Không có 吗 để hỏi. Không nhầm với nghĩa nghi vấn: cần ngữ cảnh.","src": "file"}],["想怎么……就怎么……","想 + 怎么 / 什么 + 动词，就 + 怎么 / 什么 + 动词","Cặp từ nghi vấn lặp lại để nói 'muốn thế nào thì thế đó'.",[["你想吃什么就吃什么。","Nǐ xiǎng chī shénme jiù chī shénme.","Bạn muốn ăn gì thì ăn nấy."],["你想怎么做就怎么做。","Nǐ xiǎng zěnme zuò jiù zěnme zuò.","Bạn muốn làm thế nào thì cứ làm thế đó."]],{"py": "xiǎng zěnme … jiù zěnme …","use": "Từ nghi vấn ở hai vế hô ứng với nhau.","note": "Hai từ nghi vấn phải giống nhau và có nghĩa tương ứng. Cũng gặp 谁……谁……, 哪儿……哪儿……"}],["又 và 再 (phân biệt)","又 + động từ (đã lặp) ; 再 + động từ (sắp lặp)","又 nói việc đã lặp lại; 再 nói việc sẽ lặp lại.",[["你上午已经喝了一杯咖啡，下午怎么又喝了一杯？","Nǐ shàngwǔ yǐjīng hē le yī bēi kāfēi, xiàwǔ zěnme yòu hē le yī bēi","Buổi sáng bạn đã uống một ly cà phê rồi, buổi chiều sao lại uống thêm một ly nữa?"],["你只吃了一点儿饭，再吃一点儿吧。","Nǐ zhǐ chī le yīdiǎn fàn, zài chī yīdiǎn ba","Bạn chỉ ăn một chút cơm, ăn thêm chút nữa đi."]],{"py": "yòu / zài","use": "Chọn theo quá khứ hay tương lai.","note": "Không dùng 再 với việc đã xảy ra. 又 cũng dùng cho lịch quy luật (明天又是周一了).","src": "file"}],["Câu tồn hiện (墙上挂着…)","Nơi chốn + động từ + 着 / 了 + danh từ","Cấu trúc nói vật hay người tồn tại ở một nơi theo một tư thế hay trạng thái.",[["桌子上放着一杯咖啡。","Zhuōzi shàng fàng zhe yī bēi kāfēi","Trên bàn đặt một tách cà phê"],["冰箱里放着很多水果。","Bīngxiāng lǐ fàng zhe hěn duō shuǐguǒ","Trong tủ lạnh để rất nhiều hoa quả."]],{"py": "cúnxiànjù","use": "Động từ thường là 挂, 放, 坐, 站, 写... kèm 着.","note": "Chủ ngữ là nơi chốn, danh từ đứng sau động từ. Không đặt 在 trước nơi chốn.","src": "file"}],["这么 / 那么 + tính từ","这么 / 那么 + tính từ / động từ","这么 chỉ mức độ gần người nói, 那么 chỉ mức độ xa; nhấn mạnh mức độ.",[["今天怎么这么冷？","Jīntiān zěnme zhème lěng?","Hôm nay sao lạnh thế này?"],["他没有你那么高。","Tā méiyǒu nǐ nàme gāo.","Anh ấy không cao như bạn."]],{"py": "zhème / nàme","use": "Đặt trước tính từ hoặc động từ tâm lý.","note": "Không dùng 很 cùng lúc với 这么/那么. Có thể dùng với số lượng: 这么多."}],["那 (vậy thì, thế thì)","A: ……。B: 那 + kết luận / đề nghị","那 đặt đầu câu để rút ra kết luận hoặc đề nghị dựa trên điều vừa được nói.",[["我不想去看电影。那我也不去了。我早复习好了。那也不能一直玩儿啊。","Wǒ bù xiǎng qù kàn diànyǐng Nà wǒ yě bù qù le Wǒ zǎo fùxí hǎo le Nà yě bù néng yìzhí wánr a","Tôi không muốn đi xem phim. / Thế thì tôi cũng không đi nữa. / Tôi đã ôn tập xong sớm rồi. / Thế thì cũng không thể cứ chơi mãi được."]],{"py": "nà","use": "Dùng trong hội thoại, nối với lời người khác.","note": "Không nhầm với 那 (kia, đại từ chỉ thị). Ở nghĩa liên từ, 那 đứng đầu câu và theo sau thường có dấu phẩy hoặc 么.","src": "file"}],["Phản vấn: 能……吗？","能 + động từ + 吗？","Câu hỏi tu từ, không để hỏi mà để phủ định hoặc phản đối: 'sao có thể … được'.",[["你不做作业，也不练习，能学好吗？","Nǐ bù zuò zuòyè, yě bù liànxí, néng xué hǎo ma","Bạn không làm bài tập, cũng không luyện tập, làm sao mà học tốt được"],["你每天晚上吃了饭就睡觉，也不出去走走，能不胖吗？","Nǐ měitiān wǎnshàng chī le fàn jiù shuìjiào, yě bù chūqù zǒuzou, néng bù pàng ma","Bạn mỗi tối ăn cơm xong là đi ngủ, cũng không ra ngoài đi dạo, làm sao mà không béo được?"]],{"py": "néng … ma?","use": "Có thể thay 能 bằng 会, 可以. Nghĩa tương đương câu phủ định.","note": "Phải chú ý ngữ điệu và ngữ cảnh: đây không phải câu hỏi xin phép. 这能怪我吗？ = Không thể trách tôi.","src": "file"}],["Động từ + 了 + 就 + động từ 2 (hai việc liên tiếp)","V1 + 了 + (tân ngữ) + 就 + V2","Việc thứ hai xảy ra ngay sau khi việc thứ nhất hoàn thành.",[["我下了课就吃饭。","Wǒ xià le kè jiù chī fàn","Tôi tan học là ăn cơm ngay."],["妈妈起了就做早饭。","Māma qǐ le jiù zuò zǎofàn","Mẹ thức dậy là làm bữa sáng ngay."]],{"py": "V1 le jiù V2","use": "Dùng cho hành động đã xảy ra hoặc thói quen.","note": "Thường dùng 了 sau V1 và 就 trước V2. Khác 一……就…… ở chỗ nhấn việc 1 đã xong.","src": "file"}],["Số ước lượng: 二三十 / 左右 / 来","hai số liền nhau + lượng từ ; số + 左右 ; số + 来 + lượng từ","Nói số lượng ước chừng: ghép hai số liên tiếp (两三个), thêm 左右 (khoảng), hoặc 来 (hơn một chút).",[["你每天都喝三四杯咖啡了，别再喝了。","Nǐ měitiān dōu hē sān sì bēi kāfēi le, bié zài hē le","Ngày nào bạn cũng uống ba bốn ly cà phê rồi, đừng uống nữa."],["我们已经学了两三个小时。","Wǒmen yǐjīng xué le liǎng sān gè xiǎoshí","Chúng tôi đã học được khoảng hai ba tiếng."]],{"py": "èr sān shí / zuǒyòu / lái","use": "Khi dùng số liền nhau thì không thêm 左右. 来 đi sau số tròn: 十来个.","note": "Không dùng 左右 với số không rõ ràng. Không nói 三四左右.","src": "file"}],["对……感兴趣 / 有兴趣","主语 + 对 + 事物 + 感兴趣 / 有兴趣","Nói chủ thể quan tâm, thấy hứng thú với điều gì.",[["他们对电影不感兴趣。","Tāmen duì diànyǐng bù gǎn xìngqù","Họ không hứng thú với phim ảnh."],["同学们对打篮球很感兴趣。","Tóngxuémen duì dǎ lánqiú hěn gǎn xìngqù","Các bạn học rất hứng thú với bóng rổ."]],{"py": "duì … gǎn xìngqù","use": "Phủ định: 不感兴趣, 没有兴趣.","note": "Đối tượng đứng sau 对. Không nói 感兴趣中文; phải là 对中文感兴趣.","src": "file"}],["Bổ ngữ xu hướng kép (上来, 下去, 进来, 出去…)","động từ + 上 / 下 / 进 / 出 / 回 / 过 / 起 + 来 / 去","Hai chữ chỉ hướng kết hợp: hướng đến người nói dùng 来, hướng ra xa dùng 去.",[["老师拿出了一本书来。","Lǎoshī ná chū le yī běn shū lái.","Thầy giáo lấy ra một quyển sách."],["小狗从房间跑出来了。","Xiǎo gǒu cóng fángjiān pǎo chūlái le","Chú chó nhỏ chạy ra khỏi phòng."]],{"py": "shànglái, xiàqù, jìnlái, chūqù","use": "Tân ngữ nơi chốn đứng giữa: 跑进教室去.","note": "Phải chọn 来 hoặc 去 theo người nói. Tân ngữ chỉ nơi chốn bắt buộc đặt giữa hai chữ.","src": "file"}],["哪 (nào) và 哪儿 (đâu)","哪 + (số) + lượng từ + danh từ ; 哪儿 + động từ","哪 hỏi chọn trong nhóm, đi với lượng từ; 哪儿 hỏi nơi chốn.",[["卫生间在哪儿？","Wèishēngjiān zài nǎr","Nhà vệ sinh ở đâu?"],["你去哪儿？","Nǐ qù nǎr","Bạn đi đâu?"]],{"py": "nǎ / nǎr","use": "Dạng 哪个, 哪本, 哪国.","note": "哪 (hỏi chọn) khác 那 (kia). Hỏi nơi chốn dùng 哪儿/哪里, không dùng 哪 trực tiếp.","src": "file"}],["Kết quả ngữ\"好\"","Kết quả ngữ\"好\"","Đặt sau động từ, biểu thị hành động đã được hoàn thành và đạt được kết quả thỏa đáng .",[["我吃好了。","Wǒ chī hǎo le","Tôi đã ăn ăn no rồi"],["你准备好了吗？","Nǐ zhǔnbèi hǎo le ma","Bạn chuẩn bị xong chưa?"]],{"py": "hǎo","use": "","note": "","src": "file"}],["Trợ động từ\"会\"","Trợ động từ\"会\"","Dùng trong câu biểu thị khả năng. Thường dùng để diễn tả những sự việc chưa xảy ra.",[["你穿得那么少，会感冒的。","Nǐ chuān de nàme shǎo, huì gǎnmào de","Bạn mặc ít đồ như vậy, sẽ bị cảm lạnh đấy."],["喝杯热茶会很舒服。","Hē bēi rè chá huì hěn shūfu","Uống một tách trà nóng sẽ rất dễ chịu."]],{"py": "huì","use": "","note": "","src": "file"}],["Động tác kèm trạng thái","Động tác kèm trạng thái","Cấu trúc \"Động từ 1 + 着 + (trạng thái), Động từ 2 + (tân ngữ 2)\" biểu thị hai hành động xảy ra đồng thời, diễn tả trạng thái hoặc cách thức tiến hành hành động thứ hai.",[["小丽站着跟同事聊天儿。","Xiǎo Lì zhàn zhe gēn tóngshì liáotiānr","Tiểu Lệ đứng trò chuyện với đồng nghiệp."],["她总是笑着跟客人说话。","Tā zǒng shì xiào zhe gēn kèrén shuōhuà","Cô ấy luôn cười nói chuyện với khách hàng."]],{"py": "","use": "","note": "","src": "file"}],["Trợ từ chỉ sự thay đổi\"了\"","Trợ từ chỉ sự thay đổi\"了\"","Biểu thị tình huống đã thay đổi, hoặc xuất hiện tình huống mới.",[["我以前有钱，现在没钱了。","Wǒ yǐqián yǒu qián, xiànzài méi qián le","Trước đây tôi có tiền, giờ không có tiền nữa."],["这条裙子是去年的，今年就不能穿了。","Zhè tiáo qúnzi shì qùnián de, jīnnián jiù bùnéng chuān le","Chiếc váy này là của năm ngoái, năm nay không mặc được nữa rồi."]],{"py": "le","use": "","note": "","src": "file"}],["Dùng\"刻\",\"半\",\"差\"diễn tả thời gian","Dùng\"刻\",\"半\",\"差\"diễn tả thời gian","Dùng để biểu thị thời gian. \"刻\" /kè/: Mười lăm phút \"半\" /bàn/: \"Rưỡi\" hoặc \"ba mươi phút \"差\" /chà/: Thiếu, kém, chưa tới.",[["三点一刻","Sān diǎn yí kè","Ba giờ mười lăm"],["差五分八点","Chà wǔ fēn bā diǎn","Kém năm phút tám giờ. (Tức là 7:55)"],["六点半","Liù diǎn bàn","Sáu giờ rưỡi Sáu giờ ba mươi."]],{"py": "","use": "","note": "","src": "file"}],["Cấu trúc\"越A越 B\"","Cấu trúc\"越A越 B\"","Biểu thị sự thay đổi đi kèm với sự thay đổi của A (càng... càng).",[["雨越下越大了。","Yǔ yuè xià yuè dà le","Mưa càng lúc càng to."],["你说的中文越说越好了。","Nǐ shuō de Zhōngwén yuè shuō yuè hǎo le","Tiếng Trung của bạn càng nói càng hay."]],{"py": "yuè A yuè B","use": "","note": "","src": "file"}],["Cách diễn tả số ước lượng (2)","Cách diễn tả số ước lượng (2)","Dùng \"左右\" /zuǒyòu/ sau số để diễn tả số ước lượng (khoảng).",[["周末我一般十点左右起床。","Zhōumò wǒ yībān shí diǎn zuǒyòu qǐchuáng","Cuối tuần tôi thường dậy vào khoảng mười giờ."],["我们公司有五百人左右。","Wǒmen gōngsī yǒu wǔbǎi rén zuǒyòu","Công ty chúng tôi có khoảng năm trăm người."]],{"py": "","use": "","note": "","src": "file"}],["Phân biệt\"才\"và\"就\"","Phân biệt\"才\"và\"就\"","\"就\" biểu thị hành động xảy ra sớm, nhanh, thuận lợi. \"才\" biểu thị hành động xảy ra muộn, chậm, không thuận lợi.",[["我早上五点就起床了。","Wǒ zǎoshang wǔ diǎn jiù qǐchuáng le","Tôi sáng năm giờ đã dậy rồi."],["八点上课，他九点才起来。","Bā diǎn shàngkè, tā jiǔ diǎn cái qǐlái","Tám giờ vào học, anh ấy chín giờ mới dậy."]],{"py": "cái","use": "","note": "","src": "file"}],["Cấu trúc với\"把\" (HSK3)","Cấu trúc với\"把\"","Diễn tả một hành động làm cho vị trí của đối tượng B bị thay đổi (A把B + Động từ + 在/到/给/...).",[["我把照片放在你包里了。","Wǒ bǎ zhàopiàn fàng zài nǐ bāo li le","Tôi đã đặt ảnh vào trong túi của bạn rồi."],["你帮我把这本书带给小丽。","Nǐ bāng wǒ bǎ zhè běn shū dài gěi Xiǎo Lì","Bạn giúp tôi mang quyển sách này cho Tiểu Lệ."]],{"py": "","use": "","note": "","src": "file"}],["Cấu trúc với\"把\" (HSK3) (2)","Cấu trúc với\"把\"","Hành động làm cho đối tượng B đạt được kết quả nào đó hoặc thay đổi vị trí (A把B + Động từ + Bổ ngữ kết quả/phương hướng).",[["我把衣服洗干净了。","Wǒ bǎ yīfu xǐ gānjìng le","Tôi giặt quần áo sạch sẽ rồi."],["你把水果拿过来。","Nǐ bǎ shuǐguǒ ná guòlái","Bạn mang hoa quả lại đây."]],{"py": "","use": "","note": "","src": "file"}],["除了……以外","除了 A 以外，B 还 / 也 / 都 ...","Có hai nghĩa: ngoài A ra còn thêm (dùng 还/也), hoặc trừ A ra thì tất cả (dùng 都).",[["除了你以外，大家都听懂了。","Chúle nǐ yǐwài, dàjiā dōu tīng dǒng le","Trừ bạn ra, mọi người đều đã hiểu."],["除了唱歌以外，他还喜欢跳舞。","Chúle chànggē yǐwài, tā hái xǐhuan tiàowǔ","Ngoài ca hát ra, anh ấy còn thích khiêu vũ."]],{"py": "chúle … yǐwài …","use": "Hai cách dùng: loại trừ ('ngoài … ra thì đều …') hoặc bổ sung ('ngoài … ra còn …').","note": "Phân biệt bằng vế sau: 都 cho loại trừ, 还/也 cho bổ sung. 以外 có thể lược.","src": "file"}],["Đại từ nghi vấn dùng linh hoạt (2)","Đại từ nghi vấn dùng linh hoạt (2)","Dùng \"什么\" thay thế cho người/sự vật không xác định, biểu đạt ý nhún nhường, lịch sự.",[["这个饭馆没有什么特别好吃的菜。","Zhège fànguǎn méiyǒu shénme tèbié hǎo chī de cài","Quán ăn này không có món nào đặc biệt ngon cả."],["你写得很好，没什么问题。","Nǐ xiě de hěn hǎo, méi shénme wèntí","Bạn viết rất tốt, không có vấn đề gì."]],{"py": "","use": "","note": "","src": "file"}],["Bổ ngữ trạng thái phức hợp","Bổ ngữ trạng thái phức hợp","Dùng \"得\" /de/ nối động từ/tính từ với cụm bổ ngữ trạng thái, miêu tả trạng thái/mức độ.",[["孩子们玩儿得不想回家。","Háizimen wánr de bù xiǎng huí jiā","Các con chơi đến mức không muốn về nhà."],["他们忙得没有时间跟别人见面。","Tāmen máng de méiyǒu shíjiān gēn biérén jiànmiàn","Họ bận đến mức không có thời gian gặp ai."]],{"py": "","use": "","note": "","src": "file"}],["Điệp âm động từ hai âm tiết (Hình thức\"ABAB\")","Điệp âm động từ hai âm tiết (Hình thức\"ABAB\")","Biểu đạt hành động xảy ra trong thời gian ngắn, hoặc mang ý thử.",[["他是新的，有时间你帮助帮助他吧。","Tā shì xīn de, yǒu shíjiān nǐ bāngzhù bāngzhù tā ba","Anh ấy là người mới, có thời gian bạn giúp đỡ anh ấy một chút đi."],["我真应该多锻炼锻炼了。","Wǒ zhēn yīnggāi duō duànliàn duànliàn le","Tôi thật sự nên tập thể dục nhiều hơn một chút."]],{"py": "","use": "","note": "","src": "file"}],["Đại từ nghi vấn dùng linh hoạt (3)","Đại từ nghi vấn dùng linh hoạt (3)","Thay thế cho một phạm vi rộng, biểu thị mọi đối tượng đều có tình huống tương đồng.",[["谁都喜欢小丽。","Shéi dōu xǐhuan Xiǎo Lì.","Ai cũng thích Tiểu Lệ."],["我们怎么去公园都可以。","Wǒmen zěnme qù gōngyuán dōu kěyǐ","Chúng ta đi công viên bằng cách nào cũng được."]],{"py": "","use": "","note": "","src": "file"}],["Cấu trúc điều kiện:\"只要......, 就......\"","Cấu trúc điều kiện:\"只要......, 就......\"","\"只要\" là điều kiện cần. \"就\" là kết quả sẽ xảy ra trong điều kiện đó.",[["只要我有时间，就一定跟你去旅游。","Zhǐyào wǒ yǒu shíjiān, jiù yīdìng gēn nǐ qù lǚyóu","Chỉ cần tôi có thời gian, nhất định sẽ đi du lịch với bạn."],["只要你给我钱，我就能照顾好它。","Zhǐyào nǐ gěi wǒ qián, wǒ jiù néng zhàogù hǎo tā","Chỉ cần bạn đưa tiền cho tôi, tôi sẽ chăm sóc nó tốt."]],{"py": "","use": "","note": "","src": "file"}],["Mở rộng ý nghĩa của bổ ngữ chỉ phương hướng","Mở rộng ý nghĩa của bổ ngữ chỉ phương hướng","\"出来\" có thể biểu thị từ không có gì đến có gì, phát sinh sự vật, sự việc mới, hoặc sự phân biệt, nhận ra. \"起来\" biểu thị sự bắt đầu (hành động/trạng thái), hoặc hồi tưởng/nhớ lại.",[["照片我选了几张洗出来了。","Zhàopiàn wǒ xuǎn le jǐ zhāng xǐ chūlái le","Ảnh tôi chọn đã rửa ra mấy tấm rồi."],["你能想起来那是什么时候的事吗？","Nǐ néng xiǎng qǐlái nà shì shénme shíhòu de shì ma","Bạn có thể nhớ lại chuyện đó là lúc nào không?"]],{"py": "","use": "","note": "","src": "file"}],["Cấu trúc\"只......, 才......\"","Cấu trúc\"只......, 才......\"","\"只\" là điều kiện. \"才\" là kết quả xuất hiện trong điều kiện này.",[["只有写完作业，才能看电视。","Zhǐyǒu xiě wán zuòyè, cái néng kàn diànshì","Chỉ khi làm xong bài tập, mới có thể xem TV."],["看起来只有爱，才能让人有变化。","Kàn qǐlái zhǐyǒu ài, cái néng ràng rén yǒu biànhuà","Có vẻ chỉ có tình yêu, mới có thể khiến người ta thay đổi."]],{"py": "","use": "","note": "","src": "file"}]],"4": [["只要……就…… / 只有……才……","只要 A 就 B / 只有 A 才 B","只要 chỉ điều kiện đủ (chỉ cần A là B). 只有 chỉ điều kiện duy nhất (chỉ có A mới B).",[["你只要想去，我就带你去。","Nǐ zhǐyào xiǎng qù, wǒ jiù dài nǐ qù","Chỉ cần bạn muốn đi, thì tôi sẽ đưa bạn đi."]],{"py": "zhǐyào … jiù … / zhǐyǒu … cái …","use": "只要 nêu điều kiện đủ ('chỉ cần'); 只有 nêu điều kiện cần ('chỉ có … mới').","note": "Nhớ cặp: 只要……就……; 只有……才……. Không nhầm 才 với 就: 才 nhấn điều kiện duy nhất.","src": "file"}],["连……都 / 也……","连 + A + 都 / 也 + ...","Nhấn mạnh: đến cả A còn như vậy, huống chi những thứ khác.",[["如果你连自己都不喜欢，又怎么能让别人喜欢你呢?","Rúguǒ nǐ lián zìjǐ dōu bù xǐhuān, yòu zěnme néng ràng biérén xǐhuān nǐ ne","Nếu bạn ngay cả bản thân mình còn không thích, làm sao có thể khiến người khác thích bạn?"]],{"py": "lián … dōu / yě …","use": "Nhấn mạnh một trường hợp cực đoan để nói 'đến cả … cũng …'.","note": "Thành phần sau 连 là cái nhấn mạnh; 都/也 đặt trước động từ. Thường dùng phủ định: 连……都不…….","src": "file"}],["不但……而且……","不但 A，而且 B","Quan hệ tăng tiến: không chỉ A mà còn B. Nếu hai vế khác chủ ngữ, 不但 đứng trước chủ ngữ.",[["不仅是足球踢得好，而且他也非常热情.","Bùjǐn shì zúqiú tī de hǎo, érqiě tā yě fēicháng rèqíng","Không chỉ đá bóng giỏi, mà anh ấy còn rất nhiệt tình."]],{"py": "búdàn … érqiě …","use": "Quan hệ tăng tiến: không chỉ A mà còn B.","note": "Vế sau thường có 还/也/更 đi kèm. Hai vế có thể cùng hoặc khác chủ ngữ; nếu cùng chủ ngữ thì 不但 đứng sau chủ ngữ.","src": "file"}],["一……就……","一 + A + 就 + B","Hành động A vừa xảy ra thì B xảy ra ngay, hoặc dùng cho thói quen \"hễ A là B\".",[["女儿一回来就告诉她这个好消息.","Nǚ'ér yī huílái jiù gàosu tā zhège hǎo xiāoxi","Con gái vừa về thì lập tức nói cho cô ấy tin vui này."]],{"py": "yī … jiù …","use": "Hai việc nối tiếp ngay nhau, hoặc điều kiện kéo theo kết quả.","note": "Không nhầm với 一……就 trong nghĩa 'vừa… là…' (nối tiếp) và nghĩa 'cứ… là…' (thói quen).","src": "file"}],["全 / 所有 (toàn bộ, tất cả)","全 + danh từ ; 所有 + (的) + danh từ","全 nói toàn bộ, 所有 nói tất cả mọi thứ thuộc nhóm đó.",[["全班同学都来了。","Quán bān tóngxué dōu lái le.","Cả lớp đều đến rồi."],["所有的问题我都回答了。","Suǒyǒu de wèntí wǒ dōu huídá le.","Tất cả câu hỏi tôi đều đã trả lời."]],{"py": "quán / suǒyǒu","use": "全 đứng trước danh từ hoặc làm trạng ngữ; 所有 thường đi với 的 hoặc 都.","note": "所有 thường đi kèm 都 ở vế sau. Không thêm lượng từ giữa 全 và danh từ kiểu 全个."}],["……死了 (… chết đi được)","tính từ / động từ tâm lý + 死了","死了 đứng sau tính từ để nhấn mức độ cực đoan, thường là tiêu cực.",[["我累死了。","Wǒ lèi sǐ le.","Tôi mệt chết đi được."],["今天热死了。","Jīntiān rè sǐ le.","Hôm nay nóng chết đi được."]],{"py": "sǐ le","use": "Thường dùng trong khẩu ngữ với 累, 饿, 气, 热...","note": "Không dùng trong văn phong trang trọng. Không dùng với tính từ tích cực như 好 (dùng 极了)."}],["差不多 (gần như, xấp xỉ)","差不多 + động từ / số lượng ; A 和 B 差不多","差不多 nói sự gần giống hoặc gần đạt.",[["他俩差不多高.","Tā liǎng chàbùduō gāo","Hai người họ gần như cao bằng nhau."]],{"py": "chàbuduō","use": "Đứng trước động từ, số lượng, hoặc làm vị ngữ.","note": "Không dùng 差不多 để nói hoàn toàn giống (dùng 一样). Có thể làm trạng ngữ: 差不多够了.","src": "file"}],["看来 (xem ra)","看来 + phán đoán","看来 đưa ra phán đoán dựa trên tình hình đã quan sát.",[["看来明天要下雨了。","Kànlái míngtiān yào xià yǔ le.","Xem ra ngày mai sắp mưa."],["他没回消息，看来是太忙了。","Tā méi huí xiāoxi, kànlái shì tài máng le.","Anh ấy không nhắn lại, xem ra là quá bận."]],{"py": "kànlái","use": "Đứng đầu câu, vế sau là kết luận.","note": "Khác 看起来: 看来 là suy luận từ tình hình, không chỉ từ vẻ ngoài."}],["正好 (vừa đúng, vừa khéo)","正好 + động từ / tính từ","正好 nói sự trùng hợp hoặc vừa vặn, thích hợp.",[["我妹妹出生那天，正好下雪，所以爸妈叫她“小雪”.","Wǒ mèimei chūshēng nà tiān, zhènghǎo xià xuě, suǒyǐ bà mā jiào tā \"Xiǎoxuě\"","Em gái tôi sinh ra ngày hôm đó, vừa đúng lúc tuyết rơi, nên bố mẹ đặt tên nó là \"Tiểu Tuyết\"."],["我的冰箱太旧了，正好商场在打折，我们便买一台吧.","Wǒ de bīngxiāng tài jiù le, zhènghǎo shāngchǎng zài dǎzhé, wǒmen biàn mǎi yī tái ba","Tủ lạnh nhà tôi cũ quá rồi, vừa hay trung tâm thương mại đang giảm giá, chúng ta mua một cái đi."]],{"py": "zhènghǎo","use": "Dùng làm trạng ngữ hoặc vị ngữ.","note": "正好 vừa nói trùng hợp (vừa khéo), vừa nói kích thước vừa vặn. Dựa vào ngữ cảnh.","src": "file"}],["原来 và 本来","原来 + …，… ; 本来 + …","原来 nói trước đây thế này (hoặc phát hiện ra sự thật); 本来 nói dự định ban đầu.",[["这件事情本来应该听他的","Zhè jiàn shìqing běnlái yīnggāi tīng tā de","Việc này vốn dĩ nên nghe lời anh ấy."]],{"py": "yuánlái / běnlái","use": "原来 dùng khi vỡ lẽ ra; 本来 dùng khi kế hoạch thay đổi.","note": "Khác 原来: 'hóa ra' (phát hiện); 本来: 'vốn dĩ' (dự định). Không thay thế cho nhau hoàn toàn.","src": "file"}],["差点儿 (suýt nữa)","差点儿 + (没) + động từ","差点儿 nói điều suýt xảy ra nhưng đã không xảy ra (hoặc có xảy ra nếu là điều mong muốn).",[["我差点儿迟到。","Wǒ chàdiǎnr chídào.","Tôi suýt nữa thì đến muộn."],["路很滑，他差点儿摔倒。","Lù hěn huá, tā chàdiǎnr shuāidǎo.","Đường trơn, anh ấy suýt ngã."]],{"py": "chàdiǎnr","use": "Với điều không mong muốn, có 没 hay không đều nghĩa là không xảy ra.","note": "Điều mong muốn: 差点儿没……= đã xảy ra, suýt không kịp. Dễ nhầm; nên dựa vào ngữ cảnh."}],["从来 (từ trước đến nay)","从来 + 不 / 没 + động từ","从来 nhấn mạnh một tình trạng chưa bao giờ thay đổi, chủ yếu trong phủ định.",[["我从来没去过日本。","Wǒ cónglái méi qù guo Rìběn","Tôi chưa từng đi Nhật Bản bao giờ."]],{"py": "cónglái","use": "Đặt trước 不 hoặc 没, hiếm khi dùng khẳng định.","note": "Phủ định hoàn toàn: 从来不 (thói quen) và 从来没 (chưa từng trải nghiệm).","src": "file"}],["结果 (kết quả là)","……，结果 + kết quả","结果 nêu kết quả thực tế của một sự việc, thường ngoài dự kiến.",[["比赛的结果将在晚上八点公布。","Bǐsài de jiéguǒ jiāng zài wǎnshang bā diǎn gōngbù.","Kết quả của trận đấu sẽ được công bố lúc 8 giờ tối."],["我们找了半天钥匙，结果发现它就在口袋里。","Wǒmen zhǎo le bàntiān yàoshi, jiéguǒ fāxiàn tā jiù zài kǒudài lǐ.","Chúng tôi tìm chìa khóa mãi, rốt cuộc phát hiện nó nằm ngay trong túi."]],{"py": "jiéguǒ","use": "Đứng đầu vế sau, sau sự việc đã xảy ra.","note": "Dùng cho việc đã xảy ra. Khác 所以 (kết luận logic), 结果 nhấn mạnh kết quả thực tế.","src": "file"}],["恐怕 (e rằng)","恐怕 + suy đoán","恐怕 nêu lo ngại hoặc dự đoán không mong muốn một cách nhẹ nhàng.",[["我恐怕此事會帶來不良後果。","Wǒ kǒngpà cǐ shì huì dàilái bùliáng hòuguǒ","Tôi e rằng việc này sẽ mang lại hậu quả không tốt."],["看這天氣，恐怕要下大雨了。","Kàn zhè tiānqì, kǒngpà yào xià dàyǔ le","Nhìn thời tiết thế này, có lẽ sắp có mưa to rồi."]],{"py": "kǒngpà","use": "Đứng trước động từ hoặc đầu câu.","note": "Chủ yếu dùng cho điều xấu. Với điều tốt dùng 也许 hoặc 可能.","src": "file"}],["够 (đủ)","够 + (了) ; 够 + tính từ + (了)","够 nói đủ về số lượng hoặc mức độ.",[["这些钱够我们旅行吗？","Zhèxiē qián gòu wǒmen lǚxíng ma","Số tiền này có đủ cho chúng tôi đi du lịch không?"],["你今天看起来够漂亮的！","Nǐ jīntiān kàn qǐlái gòu piàoliang de","Hôm nay trông bạn thật là xinh đẹp!"]],{"py": "gòu","use": "Dùng làm vị ngữ hoặc bổ ngữ.","note": "Phủ định: 不够. 够 + tính từ nghĩa là 'đủ … rồi' có thể mang nghĩa tiêu cực (够累的).","src": "file"}],["甚至 (thậm chí)","……，甚至 + ví dụ cực đoan","甚至 nêu mức cực đoan hơn của sự việc đã nói.",[["这个房子离公司也不远，你可以坐公共汽车甚至可以骑自行车上班","Zhège fángzi lí gōngsī yě bù yuǎn, nǐ kěyǐ zuò gōnggòng qìchē shènzhì kěyǐ qí zìxíngchē shàngbān","Căn nhà này cách công ty không xa, bạn có thể đi xe buýt thậm chí có thể đạp xe đi làm."]],{"py": "shènzhì","use": "Thường đi cùng 都 hoặc 也: 甚至……也……","note": "Không đặt 甚至 ở vế đầu. Phải có đối chiếu mức thấp hơn ở trước.","src": "file"}],["最好 (tốt nhất là)","最好 + động từ","最好 đưa ra lời khuyên mạnh: tốt nhất nên làm thế.",[["你最好早点儿去。","Nǐ zuìhǎo zǎodiǎnr qù.","Tốt nhất bạn nên đi sớm."],["感冒了，最好多休息。","Gǎnmào le, zuìhǎo duō xiūxi.","Bị cảm rồi, tốt nhất nên nghỉ nhiều."]],{"py": "zuìhǎo","use": "Đứng trước động từ, có thể đi với 你 / 我们.","note": "最好 mạnh hơn 还是, 还是 dùng khi chọn một trong hai. 最好 có thể kèm 别/不要 để khuyên đừng."}],["到底 (rốt cuộc)","到底 + câu hỏi","到底 dùng trong câu hỏi để truy hỏi: rốt cuộc, cuối cùng thì.",[["你到底想说什么？","Nǐ dàodǐ xiǎng shuō shénme","Bạn rốt cuộc muốn nói gì?"]],{"py": "dàodǐ","use": "Đặt trước động từ hoặc từ nghi vấn.","note": "Chỉ dùng trong câu hỏi hoặc câu có nghĩa truy hỏi. 到底 không dùng trong câu trần thuật hoàn toàn khẳng định.","src": "file"}],["竟然 (không ngờ)","竟然 + động từ / tính từ","竟然 biểu thị bất ngờ trước một việc ngoài dự kiến.",[["他三年没练钢琴，竟然弹得还这么好。","Tā sān nián méi liàn gāngqín, jìngrán tán de hái zhème hǎo","Anh ấy ba năm không luyện piano, không ngờ vẫn chơi hay đến thế."]],{"py": "jìngrán","use": "Đứng trước động từ hoặc tính từ.","note": "Không dùng cho việc nằm trong dự đoán. 竟然 nhấn bất ngờ, 居然 gần nghĩa nhưng mạnh hơn.","src": "file"}],["千万 (nhất định phải)","千万 + 要 / 别 / 不要 + động từ","千万 dùng để dặn dò mạnh: nhất định, ngàn vạn lần.",[["过马路时千万要小心，不要闯红灯。","Guò mǎlù shí qiānwàn yào xiǎoxīn, bú yào chuǎng hóngdēng","Khi sang đường nhất định phải cẩn thận, đừng vượt đèn đỏ."]],{"py": "qiānwàn","use": "Đi với 要 hoặc 别, không dùng trong câu khẳng định thường.","note": "Chỉ dùng trong lời dặn. Không nói 他千万来了.","src": "file"}],["什么的 / 等等","A、B、C 什么的 ; A、B 等等","Kết thúc một danh sách không liệt kê hết.",[["他喜欢苹果、香蕉什么的。","Tā xǐhuan píngguǒ, xiāngjiāo shénme de.","Anh ấy thích táo, chuối và những thứ như vậy."],["桌子上有书、笔、本子等等。","Zhuōzi shàng yǒu shū, bǐ, běnzi děngděng.","Trên bàn có sách, bút, vở, v.v."]],{"py": "shénme de / děngděng","use": "什么的 dùng khẩu ngữ, 等等 dùng trang trọng hơn.","note": "Sau 等等 không thêm 什么的. Không dùng sau danh sách chỉ có hai hạng mục cố định."}],["不过 / 可是 (nhưng)","vế 1，不过 / 可是 + vế 2","不过 là 'nhưng' nhẹ nhàng; 可是 mạnh hơn, chuyển ý rõ.",[["我本来想当律师，可是后来我发现自己对新闻更感兴趣.","Wǒ běnlái xiǎng dāng lǜshī, kěshì hòulái wǒ fāxiàn zìjǐ duì xīnwén gèng gǎnxìngqù","Tôi vốn định làm luật sư, nhưng sau này tôi phát hiện bản thân lại hứng thú hơn với báo chí."]],{"py": "búguò / kěshì","use": "Đặt đầu vế sau, thường sau dấu phẩy.","note": "Không dùng cùng 虽然 nếu vế sau đã có 不过 và 但是. 不过 làm giảm sắc thái so với 但是.","src": "file"}],["于是 (thế là)","vế 1，于是 + vế 2","于是 nêu hành động hoặc kết quả theo sau và do vế trước gây ra.",[["听爷爷奶奶说，我妹妹出生那天，下了场大雪，于是我爸妈就给她取名叫夏雪.","Tīng yéyé nǎinai shuō, wǒ mèimei chūshēng nà tiān, xià le chǎng dà xuě, yúshì wǒ bà mā jiù gěi tā qǔ míng jiào Xiàxuě","Nghe ông bà nói... thế là bố mẹ tôi đặt tên em ấy là Hạ Tuyết."]],{"py": "yúshì","use": "Đứng đầu vế sau, thường dùng trong kể chuyện.","note": "Khác 所以: 于是 nhấn chuỗi sự việc theo thời gian, không phải lập luận.","src": "file"}],["另外 / 再说 (ngoài ra)","……，另外 / 再说 + …","Bổ sung thêm thông tin hoặc lý do.",[["这本书不好看，我们看另外的吧。","Zhè běn shū bù hǎokàn, wǒmen kàn lìngwài de ba","Cuốn sách này không hay, chúng ta xem cuốn khác đi."],["工资之外，公司会另外发一笔奖金。","Gōngzī zhī wài, gōngsī huì lìngwài fā yī bǐ jiǎngjīn","Ngoài lương ra, công ty sẽ phát thêm một khoản tiền thưởng."],["这家餐厅菜很好吃，另外，环境也很不错。","Zhè jiā cāntīng cài hěn hǎo chī, lìngwài, huánjìng yě hěn bùcuò","Nhà hàng này đồ ăn rất ngon, thêm vào đó, không gian cũng rất tuyệt."]],{"py": "lìngwài / zàishuō","use": "另外 thêm ý; 再说 thêm lý do bổ trợ.","note": "再说 dùng trong khẩu ngữ để đưa lý do thêm, không dùng cho thông tin mới.","src": "file"}],["而 (còn, mà)","A，而 B ; A 而 B","而 nối hai vế đối lập hoặc bổ sung, mang tính văn viết.",[["即使没有人支持我，我也会继续做下去。","Jíshǐ méiyǒu rén zhīchí wǒ, wǒ yě huì jìxù zuò xiàqù","Ngay cả khi không có ai ủng hộ tôi, tôi cũng sẽ tiếp tục làm."]],{"py": "ér","use": "Đứng giữa hai thành phần, nối ý đối lập hoặc kết quả.","note": "Không dùng 而 để nối hai động từ liên tiếp trong khẩu ngữ. Phổ biến hơn trong văn viết.","src": "file"}],["其中 (trong đó)","……，其中 + phần trong tổng thể","其中 chỉ một phần nằm trong tập hợp vừa nêu.",[["我们班有二十名学生，其中十名是女生。","Wǒmen bān yǒu èrshí míng xuéshēng, qízhōng shí míng shì nǚshēng","Lớp chúng tôi có 20 học sinh, trong đó có 10 bạn là nữ."]],{"py": "qízhōng","use": "Đứng đầu vế sau để chỉ rõ thành phần.","note": "Chỉ dùng sau khi đã nói về một tập hợp. Không dùng thay 里面 cho vị trí vật lý.","src": "file"}],["Phân số: N 分之 M","N + 分之 + M","Phân số đọc mẫu trước, tử sau: 三分之一 = một phần ba.",[["全班三分之一的人戴眼镜。","Quán bān sān fēn zhī yī de rén dài yǎnjìng.","Một phần ba số người trong lớp đeo kính."],["我的收入有一半用来交房租。","Wǒ de shōurù yǒu yíbàn yòng lái jiāo fángzū.","Một nửa thu nhập của tôi dùng để trả tiền thuê nhà."]],{"py": "fēnshù","use": "Phần trăm đọc 百分之 + số.","note": "Thứ tự ngược tiếng Việt: mẫu trước, tử sau. 1/3 là 三分之一, không phải 一分之三."}],["随着 (cùng với, theo đà)","随着 + sự thay đổi，……","随着 nói một sự thay đổi diễn ra kéo theo sự thay đổi khác.",[["随着社会的发展，京剧也在改变.","Suízhe shèhuì de fāzhǎn, Jīngjù yě zài gǎibiàn","Cùng với sự phát triển của xã hội, Kinh kịch cũng đang thay đổi."]],{"py": "suízhe","use": "Đặt đầu câu, sau đó nêu kết quả.","note": "Chủ đề sau 随着 phải là sự thay đổi, không dùng với danh từ tĩnh.","src": "file"}],["好像 (hình như)","好像 + phán đoán ; 好像……一样","好像 nêu suy đoán nhẹ hoặc so sánh: giống như.",[["他好像生病了。","Tā hǎoxiàng shēngbìng le.","Hình như anh ấy bị ốm."],["她笑得好像孩子一样。","Tā xiào de hǎoxiàng háizi yíyàng.","Cô ấy cười giống như trẻ con."]],{"py": "hǎoxiàng","use": "Đứng trước động từ hoặc vị ngữ; 好像……一样 để so sánh.","note": "Khi dùng như phỏng đoán thì không chắc chắn; khi dùng như so sánh thì cần 一样."}],["以为 (tưởng rằng)","以为 + điều tưởng (nhưng sai)","以为 nói điều người nói đã nghĩ nhưng hóa ra không đúng.",[["我以为今天的会议室里一个人都没有","Wǒ yǐwéi jīntiān de huìyì shì lǐ yī gè rén dōu méi yǒu","Tôi tưởng rằng trong phòng họp hôm nay không có một người nào."]],{"py": "yǐwéi","use": "Thường có 其实 hay 没想到 theo sau.","note": "以为 mang ý sai; nếu muốn nói 'cho rằng' (đúng hoặc sai không xác định) dùng 认为.","src": "file"}],["通过 (thông qua)","通过 + phương tiện / quá trình，……","通过 nêu phương tiện hoặc quá trình dẫn đến kết quả.",[["通过努力，任何困难都会解决.","Tōngguò nǔlì, rènhé kùnnan dōu huì jiějué","Thông qua nỗ lực, bất kỳ khó khăn nào cũng sẽ được giải quyết."],["这条街只能通过.","Zhè tiáo jiē zhǐ néng tōngguò","Con phố này chỉ có thể đi qua."]],{"py": "tōngguò","use": "Đứng đầu câu hoặc trước động từ.","note": "Cũng có nghĩa 'đi qua, vượt qua' (通过考试). Với nghĩa 'qua' phải có tân ngữ.","src": "file"}],["来自 (đến từ)","chủ ngữ + 来自 + nơi / nguồn","来自 nói nguồn gốc, xuất xứ của người hoặc vật.",[["他来自越南。","Tā láizì Yuènán.","Anh ấy đến từ Việt Nam."],["这个消息来自可靠的朋友。","Zhège xiāoxi láizì kěkào de péngyou.","Tin này đến từ một người bạn đáng tin."]],{"py": "láizì","use": "Đứng giữa chủ ngữ và nơi chốn.","note": "Không thêm 从 trước nơi chốn: nói 他来自越南, không nói 他来自从越南."}],["不用 (không cần)","不用 + động từ","不用 nói không cần phải làm, phủ định của 要 (cần).",[["你不用来了，我自己去。","Nǐ búyòng lái le, wǒ zìjǐ qù.","Bạn không cần đến đâu, tôi tự đi."],["这点儿小事，不用谢。","Zhè diǎnr xiǎoshì, búyòng xiè.","Chuyện nhỏ này, không cần cảm ơn."]],{"py": "búyòng","use": "Đặt trước động từ hoặc dùng riêng để từ chối.","note": "Không dùng 不用 để cấm (đó là 别). 不用 không có dạng 没用 trong nghĩa này."}],["得 (děi, phải)","chủ ngữ + 得 + động từ","得 (děi) nói điều bắt buộc phải làm theo hoàn cảnh.",[["时间不早了，我得走了。","Shíjiān bù zǎo le, wǒ děi zǒu le.","Không còn sớm nữa, tôi phải đi rồi."],["你得多练习才行。","Nǐ děi duō liànxí cái xíng.","Bạn phải luyện tập nhiều mới được."]],{"py": "děi","use": "Dùng khẩu ngữ, phủ định là 不用 hoặc 不必.","note": "Không đọc de. Phủ định không dùng 不得, dùng 不用."}],["值得 (đáng)","值得 + động từ","值得 nói một việc xứng đáng được làm, hoặc có giá trị.",[["这本书很值得一读。","Zhè běn shū hěn zhíde yì dú","Cuốn sách này rất đáng đọc."]],{"py": "zhídé","use": "Đặt trước động từ, hoặc dùng đứng riêng.","note": "Không thêm 很 sau 值得 trước tân ngữ. 值得 + động từ thường không bị động.","src": "file"}],["倒 / 却 (lại, nhưng ngược lại)","chủ ngữ + 倒 / 却 + động từ","倒 và 却 biểu thị sự trái với dự kiến hoặc đối lập.",[["很多人虽然住在一个楼里，但却从来没说过话","Hěn duō rén suīrán zhù zài yī gè lóu lǐ, dàn què cónglái méi shuō guò huà","Rất nhiều người dù sống cùng một tòa nhà, nhưng lại chưa từng nói chuyện với nhau."]],{"py": "dào / què","use": "却 đứng sau chủ ngữ, nhấn sự chuyển ý; 倒 hay dùng trong khẩu ngữ.","note": "却 nhấn đối lập mạnh hơn; 倒 có thể làm lời nhận xét nhẹ. Không đặt 却 đầu câu.","src": "file"}],["由于 / 因此","由于 + nguyên nhân，因此 + kết quả","Cặp văn viết nói nguyên nhân và kết quả.",[["做好小事是完成大事的第一步，因此，件件小事都应该被看成是一次学习的机会.","Zuò hǎo xiǎo shì shì wánchéng dà shì de dì yī bù, yīncǐ, jiànjiàn xiǎo shì dōu yīnggāi bèi kànchéng shì yī cì xuéxí de jīhuì","Làm tốt việc nhỏ là bước đầu tiên để hoàn thành việc lớn, vì thế, mỗi việc nhỏ nên được xem là cơ hội học tập."]],{"py": "yóuyú / yīncǐ","use": "由于 thay 因为, 因此 thay 所以 trong văn trang trọng.","note": "Không dùng 由于 cùng 因为 một vế. 因此 chỉ có ở vế kết quả.","src": "file"}],["Bổ ngữ xu hướng 起来","động từ / tính từ + 起来","起来 có ba nghĩa: bắt đầu một trạng thái, hướng lên, hoặc nhận xét từ góc nhìn nào đó.",[["你先把桌子上的东西收拾起来.","Nǐ xiān bǎ zhuōzi shàng de dōngxi shōushi qǐlái","Bạn dọn dẹp đồ trên bàn trước đi."],["这件事说起来容易，做起来难。","Zhè jiàn shì shuō qǐlái róngyì, zuò qǐlái nán","Việc này nói ra thì dễ, làm thì mới khó."]],{"py": "qǐlái","use": "Dùng sau động từ hoặc tính từ để nói bắt đầu và tiếp tục.","note": "Nghĩa 'bắt đầu' dùng với động từ như 笑, 哭, 唱, 跑. 看起来 (xem ra) là nghĩa nhận xét.","src": "file"}],["不管……都…… (dù … cũng …)","不管 + từ nghi vấn / A 还是 B ，都 / 也 + kết quả","不管 nói dù điều kiện nào thì kết quả vẫn như vậy.",[["山东不管做什么事都非常认真.","Tóngxué bùguǎn zuò shénme shì dōu fēicháng rènzhēn","Tiểu Vương bất kể làm việc gì cũng rất nghiêm túc."]],{"py": "bùguǎn … dōu …","use": "Thường dùng khẩu ngữ, ngang với 无论.","note": "Vế sau bắt buộc có 都 hoặc 也. 不管 thân mật hơn 无论.","src": "file"}],["之一 (một trong những)","……是 + định ngữ + 之一","之一 nói một thành viên trong một nhóm.",[["北京是中国最大的城市之一。","Běijīng shì Zhōngguó zuì dà de chéngshì zhī yī.","Bắc Kinh là một trong những thành phố lớn nhất Trung Quốc."],["他是我最好的朋友之一。","Tā shì wǒ zuì hǎo de péngyou zhī yī.","Anh ấy là một trong những người bạn tốt nhất của tôi."]],{"py": "zhī yī","use": "Đứng cuối cụm danh từ.","note": "Không dùng 一个 thay 之一 trong cấu trúc này. Nhóm phía trước thường là số nhiều."}],["(在)……上 / 下 / 中","(在) + danh từ + 上 / 下 / 中","Chỉ phạm vi, phương diện hoặc điều kiện: 在工作上 (trong công việc), 在帮助下 (nhờ sự giúp đỡ), 在比赛中 (trong cuộc thi).",[["今天的工作上有很多问题.","Jīntiān de gōngzuò shàng yǒu hěnduō wèntí","Hôm nay có nhiều vấn đề về công việc."]],{"py": "(zài) … shang / xià / zhōng","use": "Thường đứng đầu câu, tạo thành trạng ngữ.","note": "Không dịch sát nghĩa 'trên/dưới'. Chọn 上, 下, 中 theo từ: 在……上 (phương diện), 在……下 (điều kiện), 在……中 (trong quá trình).","src": "file"}],["挺……的 (khá, tương đối)","挺 + tính từ / động từ tâm lý + 的","挺 nói mức độ khá cao nhưng nhẹ nhàng, thân mật; 的 ở cuối thường đi kèm.",[["昨天晚上去的那家饭馆味道挺好的","Zuótiān wǎnshàng qù de nà jiā fànguǎn wèidào tǐng hǎo de","Quán ăn tối qua tôi đến khá ngon."]],{"py": "tǐng … de","use": "Dùng khẩu ngữ, đặt trước tính từ hoặc động từ tâm lý.","note": "Không dùng 挺 với phủ định mạnh. 挺 nhẹ hơn 非常 và gần 很. Có thể bỏ 的.","src": "file"}],["首先……其次…… (trước hết … tiếp theo …)","首先 + ý 1，其次 + ý 2，最后 + ý 3","Dùng khi nêu các điểm theo thứ tự trong lập luận hoặc kế hoạch.",[["不管以后做什么工作，你首先应该有一个好身体","Bùguǎn yǐhòu zuò shénme gōngzuò, nǐ shǒuxiān yīnggāi yǒu yī gè hǎo shēntǐ","Dù sau này làm công việc gì, bạn trước hết nên có một sức khỏe tốt."]],{"py": "shǒuxiān … qícì …","use": "Thường đi trước 然后, 最后 để kết thúc chuỗi.","note": "Dùng để liệt kê ý chứ không phải trình tự hành động theo thời gian (dùng 先……再…… cho hành động).","src": "file"}],["并 (nhấn mạnh phủ định)","并 + 不 / 没(有) + động từ","并 đặt trước phủ định để nhấn mạnh sự thật không như người ta tưởng.",[["我以为做生意很简单，后来才发现其实并不容易","Wǒ yǐwéi zuò shēngyi hěn jiǎndān, hòulái cái fāxiàn qíshí bìng bù róngyì","Tôi tưởng kinh doanh rất đơn giản, sau này mới phát hiện ra thực ra hoàn toàn không dễ dàng."]],{"py": "bìng","use": "Đứng trước 不, 没, 非, hoặc dùng nối hành động (văn viết).","note": "Chỉ dùng cùng phủ định để bác bỏ điều người khác nghĩ. Không dùng 并 với khẳng định thông thường.","src": "file"}],["按照 (theo, dựa theo)","按照 + quy định / yêu cầu + động từ","按照 nói làm theo một quy tắc, tiêu chuẩn hoặc kế hoạch.",[["按照经验，这个问题应该很快解决，请大家放心","Ànzhào jīngyàn, zhège wèntí yīnggāi hěn kuài jiějué, qǐng dàjiā fàngxīn","Theo kinh nghiệm, vấn đề này nên sớm được giải quyết, mọi người yên tâm."]],{"py": "ànzhào","use": "Đứng đầu câu hoặc trước động từ; thường kèm 的 + danh từ.","note": "Sau 按照 thường là danh từ trừu tượng (规定, 要求, 计划), không dùng với người cụ thể.","src": "file"}],["确实 / 肯定 (quả thật / chắc chắn)","确实 + động từ / tính từ ; 肯定 + động từ","确实 xác nhận điều là sự thật; 肯定 nói chắc chắn hoặc khẳng định.",[["你放心吧，我肯定按时到。","Nǐ fàngxīn ba, wǒ kěndìng ànshí dào","Bạn yên tâm đi, tôi nhất định sẽ đến đúng giờ."],["请给我一个肯定的答复，是“去”还是“不去","Qǐng gěi wǒ yī gè kěndìng de dáfù, shì “qù” háishì “bù qù”","Hãy cho tôi một câu trả lời dứt khoát rõ ràng, là \"đi\" hay \"không đi\"?"]],{"py": "quèshí / kěndìng","use": "Đứng trước vị ngữ; 肯定 còn dùng làm động từ (肯定了成绩).","note": "确实 nhấn sự thật khách quan; 肯定 nhấn mức tin chắc của người nói.","src": "file"}],["实际上 (trên thực tế)","实际上 + sự thật","实际上 nêu sự thật khác với vẻ ngoài hoặc điều người ta nghĩ.",[["理论要结合实际。","Lǐlùn yào jiéhé shíjì","Lý thuyết phải kết hợp với thực tế."],["请告诉我你的实际年龄。","Qǐng gàosu wǒ nǐ de shíjì niánlíng","Hãy cho tôi biết tuổi thật của bạn."],["他说自己很忙，实际上他只是在玩游戏。","Tā shuō zìjǐ hěn máng, shíjìshang tā zhǐshì zài wán yóuxì","Anh ấy nói mình rất bận, nhưng thực ra thực tế anh ấy chỉ đang chơi game."]],{"py": "shíjì shang","use": "Đứng đầu vế hoặc trước vị ngữ.","note": "Thường đi sau một nhận định trái ngược: 他看起来很年轻，实际上已经四十岁了.","src": "file"}],["尤其 (đặc biệt là)","……，尤其 + phần đặc biệt","尤其 nhấn mạnh một trường hợp nổi bật nhất trong tổng thể.",[["你女儿真可爱，长得真像你，尤其是眼睛","Nǐ nǚ'ér zhēn kě'ài, zhǎng de zhēn xiàng nǐ, yóuqí shì yǎnjīng","Con gái bạn thật đáng yêu, lớn lên rất giống bạn, đặc biệt là đôi mắt."]],{"py": "yóuqí","use": "Đứng trước phần cần nhấn: danh từ, động từ hoặc cụm từ.","note": "Phải có phạm vi chung đã nêu trước. Không dùng 尤其 ở đầu câu độc lập.","src": "file"}],["倍 (gấp … lần)","A 是 B 的 + số + 倍 ; A 比 B 多 + số + 倍","倍 nói bội số: gấp mấy lần.",[["我的工资比五年前高了五倍。","Wǒ de gōngzī bǐ wǔ nián qián gāo le wǔ bèi","Lương của tôi cao gấp năm lần (so với) năm năm trước."]],{"py": "bèi","use": "Dùng số + 倍; 是 + 的 + số + 倍 nghĩa là 'gấp … lần'.","note": "Phân biệt: 是 B 的三倍 (gấp ba) với 比 B 多两倍 (nhiều hơn hai lần, tức gấp ba). Không dùng 倍 cho phân số.","src": "file"}],["估计 (ước chừng)","估计 + phán đoán","估计 nói dự đoán dựa trên kinh nghiệm hoặc thông tin có sẵn.",[["你估计这个项目多久能完成？","Nǐ gūjì zhège xiàngmù duōjiǔ néng wánchéng","Bạn ước tính dự án này bao lâu thì hoàn thành?"],["根据市场估计，这款产品的需求量很大。","Gēnjù shìchǎng gūjì, zhè kuǎn chǎnpǐn de xūqiú liàng hěn dà","Theo ước tính của thị trường, nhu cầu cho sản phẩm này rất lớn."]],{"py": "gūjì","use": "Đứng đầu câu hoặc trước vị ngữ; có thể làm động từ có tân ngữ.","note": "Khác 大概 (đại khái, chỉ ước lượng) ở chỗ 估计 dựa trên suy luận.","src": "file"}],["来不及 / 来得及 (kịp / không kịp)","来不及 / 来得及 + động từ","Nói còn đủ thời gian (来得及) hay không đủ thời gian (来不及) để làm gì.",[["事情发生得太突然，我来不及通知你。","Shìqing fāshēng de tài tūrán, wǒ láibují tōngzhī nǐ","Sự việc xảy ra quá đột ngột, tôi không kịp báo cho bạn."]],{"py": "láibují / láidejí","use": "Đứng trước động từ hoặc dùng độc lập: 来得及吗？","note": "Khác 赶不上 (không đuổi kịp một thứ cụ thể như xe). 来不及 nhấn thiếu thời gian.","src": "file"}],["Động từ li hợp lặp (散散步)","AAB → ABB : 散步 → 散散步","Động từ li hợp lặp phần động từ để nhẹ nhàng: 见面 → 见见面, 洗澡 → 洗洗澡.",[["学习累了，我们出去散散步吧。","Xuéxí lèi le, wǒmen chūqù sàn san bù ba","Học mệt rồi, chúng ta ra ngoài đi dạo một chút đi."]],{"py": "líhécí chóngdié","use": "Chỉ lặp chữ đầu (động từ), giữ nguyên chữ sau (tân ngữ).","note": "Không lặp cả từ: nói 散散步, không nói 散步散步. Khác lặp động từ thường (看看).","src": "file"}],["既……又…… (vừa … vừa …)","既 + A + 又 / 也 / 还 + B","Nêu hai đặc điểm cùng tồn tại, trang trọng hơn 又……又……",[["她既聪明又漂亮。","Tā jì cōngmíng yòu piàoliang","Cô ấy vừa thông minh vừa xinh đẹp."]],{"py": "jì … yòu …","use": "Hai vế nên cùng loại: cùng tích cực hoặc cùng tiêu cực.","note": "既 chỉ đứng trước vế đầu. Không dùng 既 với hai hành động đối lập.","src": "file"}],["可不是 (chứ còn gì nữa)","可不是 (+ lặp lại ý đối phương)","可不是 là lời đáp đồng tình mạnh, nghĩa 'đúng vậy, chứ còn gì'.",[["这个电影可不是很好看吗？我都看了三遍了。","Zhège diànyǐng kě bú shì hěn hǎokàn ma? Wǒ dōu kànle sān biàn le","Chẳng phải là bộ phim này rất hay sao? Tôi xem đến ba lần rồi."]],{"py": "kě bú shì","use": "Dùng khẩu ngữ trong hội thoại để đồng ý.","note": "Không dùng trong văn viết trang trọng. Không phải câu hỏi.","src": "file"}],["往往 (thường thường)","往往 + động từ","往往 nói quy luật thường gặp trong quá khứ hoặc thực tế đã quan sát.",[["他往往工作到深夜。","Tā wǎngwǎng gōngzuò dào shēnyè","Anh ấy thường làm việc đến tận khuya."]],{"py": "wǎngwǎng","use": "Đứng trước động từ; nói về xu hướng chung.","note": "Không dùng với tương lai và không dùng với câu mệnh lệnh. Khác 常常: 往往 nhấn quy luật.","src": "file"}],["在……看来 (theo … thì)","在 + người + 看来，……","Nêu quan điểm hoặc đánh giá của một người hay nhóm.",[["在很多人看来，听流行音乐是年轻人的爱好.","Zài hěn duō rén kànlái, tīng liúxíng yīnyuè shì niánqīng rén de àihǎo","Theo quan điểm của nhiều người, nghe nhạc pop là sở thích của người trẻ."]],{"py": "zài … kànlái","use": "Đứng đầu câu.","note": "Người đứng giữa 在 và 看来 là chủ thể có quan điểm; không đặt sự vật. Gần với 对……来说 nhưng nhấn quan điểm cá nhân.","src": "file"}],["否则 (nếu không thì)","……，否则 + hậu quả","否则 nêu hậu quả xảy ra nếu điều kiện vừa nói không được thực hiện.",[["看来要考好，要认真复习...否则会做的题也没时间做了.","Kàn lái yào kǎo hǎo, yào rènzhēn fùxí... fǒuzé huì zuò de tí yě méi shíjiān zuò le","Xem ra muốn thi tốt, phải ôn tập nghiêm túc... nếu không thì đề đã làm được cũng không kịp thời gian."]],{"py": "fǒuzé","use": "Đứng đầu vế sau, thường theo sau lời khuyên hoặc yêu cầu.","note": "Văn viết hơn 要不然. Dùng sau câu khẳng định điều cần làm: 快走，否则来不及了.","src": "file"}],["然而 (tuy nhiên)","……，然而 + ý đối lập","然而 là từ chuyển ý trang trọng, tương đương 但是.",[["他虽然失败了很多次，然而一直没有放弃.","Tā suīrán shībài le hěnduō cì, rán'ér yīzhí méi yǒu fàngqì","Mặc dù anh ấy thất bại nhiều lần, nhưng vẫn không từ bỏ."]],{"py": "rán'ér","use": "Đứng đầu vế sau, thường trong văn viết.","note": "Không dùng 然而 cùng 但是 trong một vế. Ít dùng trong khẩu ngữ.","src": "file"}],["同时 (đồng thời)","同时 + câu ; A 的同时，B","同时 nói hai việc xảy ra cùng lúc, hoặc bổ sung thêm điều gì đó.",[["我们要发展经济，同时也必须保护环境。","Wǒmen yào fāzhǎn jīngjì, tóngshí yě bìxū bǎohù huánjìng","Chúng ta cần phát triển kinh tế, đồng thời cũng phải bảo vệ môi trường."]],{"py": "tóngshí","use": "Đứng đầu vế hoặc sau một cụm danh từ/động từ.","note": "Khi là liên từ nghĩa 'hơn nữa' thì đi trước 还, 也. Không dùng cho việc xảy ra ở hai thời điểm khác nhau.","src": "file"}],["并且 (và còn)","A，并且 B","并且 nối hai hành động hoặc đặc điểm cùng tồn tại, mang nghĩa tăng thêm.",[["这房子家具全...并且价格也便宜，真的恨值得考虑.","Zhè fángzi jiājù quán... bìngqiě jiàgé yě piányi, zhēn de hěn zhíde kǎolǜ","Căn nhà này đầy đủ nội thất... hơn nữa giá cả cũng rẻ, thực sự đáng để cân nhắc."]],{"py": "bìngqiě","use": "Đứng đầu vế sau; tương đương 而且 nhưng trang trọng hơn.","note": "Không nối danh từ thông thường (dùng 和). Hai vế thường có cùng chủ ngữ.","src": "file"}],["再……也…… (dù … đến đâu cũng …)","再 + tính từ / động từ + 也 + kết quả","Nhấn mạnh dù mức độ cao đến đâu thì kết quả vẫn không đổi.",[["事情已经发生了，你再后悔也无法改变，别伤心了.","Shìqing yǐjīng fāshēng le, nǐ zài hòuhuǐ yě wúfǎ gǎibiàn, bié shāngxīn le","Chuyện đã xảy ra rồi, bạn có hối hận nữa cũng không thể thay đổi, đừng buồn nữa."]],{"py": "zài … yě …","use": "再 đứng trước tính từ, 也 trước vế kết quả.","note": "Khác 再 chỉ lặp lại. Vế sau thường phủ định hoặc nêu quyết tâm.","src": "file"}],["对于 (đối với)","对于 + đối tượng，……","对于 nêu đối tượng hoặc chủ đề được bàn đến, trang trọng hơn 对.",[["对于这件事，我跟大家的看法不同.","Duìyú zhè jiàn shì, wǒ gēn dàjiā de kànfǎ bù tóng","Đối với việc này, quan điểm của tôi khác với mọi người"]],{"py": "duìyú","use": "Đứng đầu câu hoặc trước chủ ngữ.","note": "对于 dùng cho chủ đề hoặc sự việc; 对 còn dùng cho người (对我很好). 对于 không đứng trước tính từ tình cảm.","src": "file"}],["Lượng từ lặp (个个, 家家)","lượng từ lặp + 都 + vị ngữ","Lượng từ lặp lại nghĩa 'mỗi, từng, tất cả'.",[["人人都会使用语言，但是怎么用语言把话说好却是一门艺术.","Rénrén dōu huì shǐyòng yǔyán, dànshì zěnme yòng yǔyán bǎ huà shuō hǎo què shì yī mén yìshù","Mỗi người đều biết dùng ngôn ngữ, nhưng làm thế nào để nói hay lại là một nghệ thuật."]],{"py": "liàngcí chóngdié","use": "Đi cùng 都 ở vế sau.","note": "Không thêm 每 trước lượng từ lặp (không nói 每个个). Không dùng cho số lượng cụ thể.","src": "file"}],["相反 (ngược lại)","A 不…，相反，B …","相反 nói điều hoàn toàn đối lập với điều vừa nói.",[["这场危机不但没有削弱团队，相反，让大家更加团结了。","Zhè chǎng wēijī bùdàn méiyǒu xuēruò tuánduì, xiāngfǎn, ràng dàjiā gèngjiā tuánjié le","Cuộc khủng hoảng này không những không làm suy yếu đội ngũ, mà ngược lại, còn khiến mọi người thêm đoàn kết."],["我们的观点完全相反。","Wǒmen de guāndiǎn wánquán xiāngfǎn","Quan điểm của chúng tôi hoàn toàn trái ngược."]],{"py": "xiāngfǎn","use": "Dùng như liên từ ở đầu vế hoặc tính từ (正相反).","note": "Không nhầm với 反而: 相反 nói đối lập hoàn toàn, 反而 nói kết quả trái dự đoán.","src": "file"}],["大概 (đại khái, khoảng)","大概 + (số lượng / phán đoán)","大概 nói ước lượng hoặc phỏng đoán chưa chắc chắn.",[["从这儿到机场，大概需要一个小时。","Cóng zhèr dào jīchǎng, dàgài xūyào yī gè xiǎoshí","Khoảng một tiếng đồng hồ là từ đây đến sân bay."]],{"py": "dàgài","use": "Đứng trước số lượng, thời điểm hoặc vị ngữ.","note": "Không dùng cho điều đã chắc chắn. Có thể là tính từ (大概的意思).","src": "file"}],["偶尔 (thỉnh thoảng)","偶尔 + động từ","偶尔 nói việc xảy ra rất ít, không đều đặn.",[["他平时很忙，只是偶尔来看看父母。","Tā píngshí hěn máng, zhǐshì ǒu'ěr lái kànkan fùmǔ","Anh ấy bình thường rất bận, chỉ thỉnh thoảng mới về thăm bố mẹ."]],{"py": "ǒu'ěr","use": "Đứng trước động từ.","note": "Khác 经常 (thường). Khác 偶然 (tình cờ, không dự tính).","src": "file"}],["由 (do, bởi)","A 由 B + động từ","由 chỉ người hoặc bộ phận đảm nhiệm, hoặc xuất xứ, thành phần.",[["按照规定，这件事应该由王夫夫负责.","Ànzhào guīdìng, zhè jiàn shì yīnggāi yóu Wáng fūfū fùzé","Theo quy định, việc này nên do ông Vương phụ trách"]],{"py": "yóu","use": "Đặt 由 + người đảm nhiệm trước động từ.","note": "Khác 被 (bị động). 由 không có nghĩa bị tác động, mà nhấn ai phụ trách.","src": "file"}],["以 (dùng, lấy, để)","以 + A + 为 B ; 以 + phương tiện + động từ","以 là giới từ văn viết: dùng, lấy, căn cứ vào; còn có nghĩa 'để' ở vế sau.",[["我们应以事实为根据，不要轻信谣言。","Wǒmen yīng yǐ shìshí wéi gēnjù, bú yào qīngxìn yáoyán","Chúng ta nên lấy sự thật làm căn cứ, đừng dễ tin lời đồn."]],{"py": "yǐ","use": "Hay gặp trong 以……为…… (lấy … làm …).","note": "Không dùng 以 thay 用 trong khẩu ngữ. Cấu trúc 以……为…… là cố định.","src": "file"}],["想起来 (nhớ ra)","động từ + 起来 (nhớ ra)","想起来 nói đột nhiên nhớ lại điều đã quên. Cũng gặp 想不起来.",[["听到这个声音，我一下子想不起来是谁了.","Tīng dào zhège shēngyīn, wǒ yī xiàzi xiǎng bù qǐlái shì shuí le","Nghe giọng này, tôi nhất thời không nhớ ra là ai."]],{"py": "xiǎng qǐlái","use": "Có thể có tân ngữ giữa: 想起他的名字来.","note": "Không dùng 想起来 để nói 'nghĩ tới điều mới'. Phủ định là 想不起来.","src": "file"}],["拿……来说 (lấy … mà nói)","拿 + ví dụ + 来说，……","Dùng để nêu ví dụ minh họa cho điều vừa nói.",[["学习语言需要耐心。拿学汉语来说，每天坚持练习才能进步。","Xuéxí yǔyán xūyào nàixīn. Ná xué hànyǔ láishuō, měitiān jiānchí liànxí cáinéng jìnbù","Học ngôn ngữ cần sự kiên nhẫn. Lấy việc học tiếng Trung mà nói, phải kiên trì luyện tập hàng ngày mới tiến bộ được."]],{"py": "ná … lái shuō","use": "Đứng đầu vế, giới thiệu ví dụ.","note": "Nhớ có 来说 ở cuối. Ví dụ phải minh họa cho nhận định chung ở trước.","src": "file"}],["敢 (dám)","chủ ngữ + 敢 + động từ","敢 nói có can đảm làm việc gì.",[["我们应该把那些敢说真话的人当镜子.","Wǒmen yīnggāi bǎ nà xiē gǎn shuō zhēnhuà de rén dāng jìngzi","Chúng ta nên coi những người dám nói sự thật như một tấm gương."]],{"py": "gǎn","use": "Đặt trước động từ. Phủ định: 不敢. Hỏi: 敢不敢?","note": "Không dùng 很 trước 敢 ở nghĩa 'dám'. 不敢 đôi khi là cách nói khiêm tốn.","src": "file"}],["趟 (chuyến, lượt)","động từ + 一趟 ; 一趟 + danh từ","趟 là lượng từ cho chuyến đi lại hoặc chuyến tàu, xe.",[["上个月我去了趟北京动物园.","Shàng gè yuè wǒ qù le yī tàng Běijīng dòngwùyuán","Tháng trước tôi đã đi một chuyến đến Vườn thú Bắc Kinh."]],{"py": "tàng","use": "Đứng sau động từ chỉ di chuyển: 去一趟, 跑一趟.","note": "Khác 次 (lần, chung). 趟 chỉ dùng với hành động đi qua lại.","src": "file"}],["为了……而…… (vì … mà …)","为了 + mục đích + 而 + hành động","Nêu mục đích và hành động cụ thể để đạt mục đích đó.",[["我们不应该为了钱而工作.","Wǒmen bù yīnggāi wèile qián ér gōngzuò","Chúng ta không nên vì tiền mà làm việc."]],{"py": "wèile … ér …","use": "Hay gặp trong văn viết, 而 nối mục đích và hành động.","note": "Không bỏ 而 khi muốn câu trang trọng. Khác 为了 đơn: có thể rút gọn.","src": "file"}],["仍然 (vẫn)","仍然 + động từ / tính từ","仍然 nói trạng thái không thay đổi dù điều kiện có thay đổi.",[["这件衣服好看倒好看，就是太贵了。","Zhè jiàn yīfu hǎokàn dào hǎokàn, jiùshì tài guì le","Bộ quần áo này đẹp thì đẹp thật, chỉ có điều quá đắt."]],{"py": "réngrán","use": "Đứng trước động từ hoặc tính từ, văn viết hơn 还.","note": "Gần 还是/仍旧. Không dùng với tình huống thay đổi.","src": "file"}],["……不了 / 受不了","động từ + 不了 ; 受不了","不了 nói không thể thực hiện hoặc không chịu nổi; 受不了 là 'không chịu nổi'.",[["不过天天对着电脑，眼睛实在受不了.","Búguò tiāntiān duì zhe diànnǎo, yǎnjīng shízài shòu bù liǎo","Nhưng ngày nào cũng đối diện với máy tính, mắt thực sự không chịu nổi nữa."]],{"py": "bu liǎo / shòu bu liǎo","use": "受不了 thường dùng với 热, 累, 吵...","note": "Cấu trúc bổ ngữ khả năng; đừng nhầm 了 (liǎo) với 了 (le).","src": "file"}],["接着 (tiếp theo)","接着 + động từ / câu","接着 nói việc xảy ra liền sau việc vừa nói.",[["他吃完晚饭，接着又开始工作了。","Tā chī wán wǎnfàn, jiēzhe yòu kāishǐ gōngzuò le","Anh ấy ăn tối xong, tiếp theo lại bắt đầu làm việc."]],{"py": "jiēzhe","use": "Đứng đầu vế hoặc trước động từ.","note": "Khác 然后 (rồi): 接着 nhấn sự nối tiếp ngay lập tức. 接着 còn là động từ (接着说).","src": "file"}],["除此以外 (ngoài ra)","除此以外，……","除此以外 chỉ phạm vi vừa nêu rồi bổ sung điều khác.",[["他和我弟弟一天出生...除此以外几乎再找不到其他共同点.","Tā hé wǒ dìdi yī tiān chūshēng... chú cǐ yǐwài jīhū zài zhǎo bù dào qítā gòngtóng diǎn","Tôi và em trai sinh cùng ngày... ngoài điều đó ra thì hầu như không tìm thấy điểm chung nào khác."]],{"py": "chú cǐ yǐwài","use": "Đứng đầu vế sau.","note": "Khác 除了……以外 (HSK4) ở chỗ 此 thay thế cho nội dung đã nêu trước.","src": "file"}],["把……叫做…… (gọi … là …)","把 + A + 叫做 / 称为 + B","Dùng để định nghĩa hoặc đặt tên gọi cho một sự vật.",[["在中国，我们把父亲的爸爸叫做“爷爷”。","Zài zhōngguó, wǒmen bǎ fùqīn de bàba jiàozuò “yéye”","Ở Trung Quốc, chúng tôi gọi bố của bố là \"ông nội\"."]],{"py": "bǎ … jiàozuò …","use": "Dùng trong giải thích khái niệm.","note": "叫做 có thể thay bằng 称为 (trang trọng). Không dùng với tân ngữ chưa xác định.","src": "file"}],["总的来说 (nói chung)","总的来说，……","总的来说 dùng để tóm tắt hoặc đưa nhận xét tổng quát.",[["我对这个方案的看法，总的来说，是支持的，不过还有一些细节需要完善。","Wǒ duì zhège fāng'àn de kànfǎ, zǒngde láishuō, shì zhīchí de, búguò hái yǒu yīxiē xìjié xūyào wánshàn","Ý kiến của tôi về phương án này, nhìn chung, là ủng hộ, tuy nhiên vẫn còn một số chi tiết cần hoàn thiện."]],{"py": "zǒng de lái shuō","use": "Đứng đầu câu để kết luận.","note": "Dùng ở phần tổng kết, không dùng đầu đoạn mở đầu. Có thể thay bằng 总之.","src": "file"}],["在于 (nằm ở)","A 的关键 / 目的 + 在于 + B","在于 nói cốt lõi, nguyên nhân hoặc mục đích nằm ở đâu.",[["选择职业的关键在于兴趣.","Xuǎnzé zhíyè de guānjiàn zàiyú xìngqù","Điều cốt lõi khi chọn nghề nằm ở sở thích"]],{"py": "zàiyú","use": "Văn viết, nêu điểm mấu chốt.","note": "Không dùng cho vị trí vật lý. Khác 在 (ở).","src": "file"}],["Động từ 1 + 着 + Động từ 2","động từ 1 + 着 + động từ 2","动词1+着 nói cách thức hoặc trạng thái khi thực hiện động từ 2.",[["他笑着说没关系。","Tā xiào zhe shuō méi guānxi.","Anh ấy cười nói không sao."],["孩子们坐着听老师讲故事。","Háizimen zuò zhe tīng lǎoshī jiǎng gùshi.","Bọn trẻ ngồi nghe thầy kể chuyện."]],{"py": "dòngcí 1 + zhe + dòngcí 2","use": "Động từ 1 đứng trước, bổ nghĩa cho động từ 2.","note": "Khác 一边……一边: ở đây động từ 1 là cách thức/tư thế, không phải hành động thứ hai riêng biệt."}],["忽然 (đột nhiên)","忽然 + động từ / câu","忽然 nói việc xảy ra bất ngờ và nhanh.",[["天忽然黑了下来。","Tiān hūrán hēi le xiàlái.","Trời đột nhiên tối sầm lại."],["他忽然想起了一件事。","Tā hūrán xiǎng qǐ le yí jiàn shì.","Anh ấy chợt nhớ ra một việc."]],{"py": "hūrán","use": "Đứng đầu vế hoặc trước động từ.","note": "Khác 突然 (tính từ, có thể làm vị ngữ). 忽然 chỉ làm trạng ngữ."}],["刚gāng","刚gāng","Phó từ 刚 chỉ hành động xảy ra cách đây không lâu; 刚才 là danh từ chỉ thời gian ngắn trong quá khứ, có thể đứng trước chủ ngữ hoặc sau chủ ngữ và trước động từ,.",[["我刚才去洗手间了，你给我打电话了","Wǒ gāngcái qù xǐshǒujiān le, nǐ gěi wǒ dǎ diànhuà le","Tôi vừa mới đi vệ sinh, bạn đã gọi điện cho tôi sao"],["他刚来一会儿.","Tā gāng lái yīhuìr","Anh ấy vừa mới đến một lát."]],{"py": "gāng","use": "","note": "","src": "file"}],["即使……也……","即使 A，也 B","Nhượng bộ giả định: dù A (có thể chưa xảy ra) thì B vẫn không đổi.",[["即使明天下雨，我们也要去爬山。","Jíshǐ míngtiān xià yǔ, wǒmen yě yào qù páshān","Cho dù ngày mai trời mưa, chúng tôi vẫn sẽ đi leo núi."]],{"py": "jíshǐ … yě …","use": "Nhượng bộ giả định: cho dù ... cũng ... (điều kiện có thể chưa xảy ra).","note": "Dùng cho tình huống giả định; còn 虽然 dùng cho sự thật đã xảy ra. Không thêm 但是 ở vế sau.","src": "file"}],["尽管……但是 / 可是……","尽管 A，但是 / 可是 / 还是 B","Nhượng bộ với sự thật đã xảy ra: mặc dù A (có thật) nhưng vẫn B. Khác 即使 ở chỗ A là sự thật.",[["尽管这是一场误会，他仍然不开心","Jǐnguǎn zhè shì yī chǎng wùhuì, tā réngráng bù kāixīn","Mặc dù đây là một sự hiểu lầm, anh ấy vẫn không vui."]],{"py": "jǐnguǎn … dànshì / kěshì …","use": "Nhượng bộ về sự thật: mặc dù … nhưng …, văn phong trang trọng hơn 虽然.","note": "Vế sau thường có 但是/可是/还是. Không dùng 尽管 cho tình huống giả định (dùng 即使).","src": "file"}],["原来","原来","thể hiện sự phát hiện, nhận ra sự thật (với ngữ khí ngạc nhiên) hoặc chỉ trạng thái ban đầu, nguyên gốc của sự vật. Có thể dùng như phó từ hoặc hình dung từ (tính từ).",[["原来是你！我还以为是小王呢。","Yuánlái shì nǐ! Wǒ hái yǐwéi shì Xiǎo Wáng ne","Thì ra là bạn! Tôi cứ tưởng là Tiểu Vương."],["我们还是按原来的计划进行吧。","Wǒmen háishì àn yuánlái de jìhuà jìnxíng ba","Chúng ta vẫn cứ theo kế hoạch ban đầu mà tiến hành đi."]],{"py": "yuánlái","use": "","note": "","src": "file"}],["再说","再说","Động từ: Gác lại Liên từ (biểu thị bổ sung thêm sự việc).",[["这个问题再说吧，我们先讨论紧急的。","Zhège wèntí xiān zàishuō ba, wǒmen xiān tǎo lùn jǐn jí de","Vấn đề này gác lại đã, chúng ta hãy thảo luận việc khẩn cấp trước."],["现在下着大雨，再说你又没带伞，就别出去了。","Xiànzài xià zhe dàyǔ, zàishuō nǐ yòu méi dài sǎn, jiù bié chū qù le","Bây giờ trời đang mưa to, hơn nữa bạn lại không mang ô, đừng đi ra ngoài nữa."]],{"py": "zàishuō","use": "","note": "","src": "file"}],["对……而言 / 对……来说","对 + đối tượng + 而言 / 来说，……","Nêu góc nhìn của một đối tượng: 'đối với … mà nói'.",[["对一个女人来说，漂亮、聪明都很重要，但其实更重要的是快乐.","Duì yī gè nǚrén láishuō, piàoliang, cōngmíng dōu hěn zhòngyào, dàn qíshí gèng zhòngyào de shì kuàilè","Đối với một người phụ nữ mà nói, xinh đẹp, thông minh đều quan trọng, nhưng thực ra quan trọng hơn là niềm vui."]],{"py": "duì … éryán","use": "Đứng đầu câu.","note": "而言 trang trọng hơn 来说. Đối tượng thường là người hoặc nhóm.","src": "file"}],["(在)…下 ((zài)… xià)","(在)…下 ((zài)… xià)","Cấu trúc giới từ/danh từ, biểu thị điều kiện, tình huống cho một sự việc xảy ra.",[["在老师和同学们的帮助下，他的汉语提高得非常快","Zài lǎoshī hé tóngxuémen de bāngzhù xià, tā de Hànyǔ tígāo de fēicháng kuài","Dưới sự giúp đỡ của thầy cô và các bạn, tiếng Hán của anh ấy tiến bộ rất nhanh"]],{"py": "","use": "","note": "","src": "file"}],["要是","要是","Liên từ dùng để giả định một điều kiện. Cấu trúc cơ bản: “要是” + [tình huống giả định] ，就 + [kết quả/hành động sẽ xảy ra].",[["要是明天下雨，我们就不去公园了。","Yàoshi míngtiān xià yǔ, wǒmen jiù bù qù gōngyuán le","Nếu ngày mai trời mưa, thì chúng tôi sẽ không đi công viên nữa."]],{"py": "yàoshi","use": "","note": "","src": "file"}],["使","使","Động từ cầu khiến, làm cho / khiến cho một ai/cái gì thay đổi trạng thái hoặc thực hiện một hành động. Cấu trúc phổ biến: A + 使 + B + [hành động/thay đổi]",[["这个消息使大家很高兴。","Zhège xiāoxi shǐ dàjiā hěn gāoxìng","Tin tức này khiến mọi người rất vui."]],{"py": "shǐ","use": "","note": "","src": "file"}],["难道……吗？","难道 + câu + 吗？","Câu hỏi tu từ, nhấn mạnh sự ngạc nhiên hoặc không đồng tình: \"chẳng lẽ... sao?\".",[["请在提交文件前再次核对信息，以免因疏漏而影响审批进度.","Qǐng zài tí jiāo wén jiàn qián zài cì hé duì xìn xī, yǐ miǎn yīn shū lòu ér yǐng xiǎng shěn pī jìn dù","Vui lòng kiểm tra lại thông tin trước khi nộp tài liệu, để tránh việc bỏ sót làm ảnh hưởng đến tiến độ phê duyệt."]],{"py": "nándào … ma?","use": "Câu hỏi tu từ biểu thị sự nghi ngờ hoặc phản bác: chẳng lẽ … sao?","note": "Thường kèm 吗 cuối câu. Không dùng để hỏi thông tin thật sự; mang sắc thái ngạc nhiên hoặc trách móc.","src": "file"}],["确实","确实","Phó từ, biểu thị khách quan và khẳng định (quả thực, thật sự).",[["确实，这个方案更节省成本。","Quèshí, zhège fāng'àn gèng jiéshěng chéngběn","Quả thực, phương án này tiết kiệm chi phí hơn."]],{"py": "quèshí","use": "","note": "","src": "file"}],["由于","由于","Liên từ/Giới từ, biểu thị nguyên nhân, bởi vì,.",[["由于各种原因，我们不得不改变原来的计划.","Yóuyú gèzhǒng yuányīn, wǒmen bù dé bù gǎibiàn yuánlái de jìhuà","Do nhiều nguyên nhân khác nhau, chúng tôi buộc phải thay đổi kế hoạch ban đầu."]],{"py": "yóuyú","use": "","note": "","src": "file"}],["无论……都……","无论 + từ nghi vấn / A 还是 B，都 + ...","Trong mọi điều kiện, kết quả không đổi. Sau 无论 thường có từ nghi vấn (什么, 谁, 怎么) hoặc cặp lựa chọn.",[["无论你去不去，都请通知我一声。","Wúlùn nǐ qù bu qù, dōu qǐng tōngzhī wǒ yīshēng","Bất kể bạn có đi hay không, cũng hãy thông báo cho tôi một tiếng."]],{"py": "wúlùn … dōu …","use": "Dù trong điều kiện nào kết quả vẫn không đổi: dù thế nào cũng …","note": "Sau 无论 là từ nghi vấn hoặc cặp lựa chọn (A 还是 B, 去不去). Vế sau phải có 都/也.","src": "file"}],["既然……就……","既然 A，就 B","Dựa trên một sự thật đã biết (A), rút ra kết luận hay đề nghị (B): \"đã... thì...\".",[["既然大家都同意这个方案，我们就马上开始吧。","Jìrán dàjiā dōu tóngyì zhège fāng'àn, wǒmen jiù mǎshàng kāishǐ ba","Vì mọi người đều đồng ý với phương án này rồi, chúng ta hãy bắt đầu ngay đi."]],{"py": "jìrán … jiù …","use": "Từ sự thật đã biết suy ra kết luận: đã … thì …","note": "Vế sau thường là đề nghị, quyết định, câu hỏi. Khác 如果: 既然 dựa trên sự thật đã xảy ra.","src": "file"}],["倒","倒","Phó từ, biểu thị trái ngược hoặc ngoài ý muốn.",[["你说他笨？我倒觉得他很聪明。","Nǐ shuō tā bèn? Wǒ dào juéde tā hěn cōngmíng","Bạn nói anh ấy ngốc? Tôi lại thấy anh ấy rất thông minh đấy."]],{"py": "dào","use": "","note": "","src": "file"}],["是否 (có … hay không)","是否 + động từ / tính từ","是否 là cách nói trang trọng của 是不是 hoặc 有没有.",[["虽然遇到了困难，但他仍然非常乐观。","Suīrán yù dào le kùnnán, dàn tā réngrán fēicháng lèguān","Tuy gặp khó khăn, nhưng anh ấy vẫn rất lạc quan."]],{"py": "shìfǒu","use": "Đứng trước động từ hoặc tính từ trong câu hỏi gián tiếp.","note": "Thường không dùng trong khẩu ngữ. Không thêm 吗 vào cuối.","src": "file"}],["Cấu trúc: Động từ 1 + 着 + Động từ 1 + 着 + (，就 忽然…) + Hành động","Cấu trúc: Động từ 1 + 着 + Động từ 1 + 着 + (，就 忽然…) + Hành động","Cấu trúc này mô tả một hành động đang kéo dài thì đột nhiên hoặc tự nhiên dẫn đến một kết quả, thay đổi hoặc một hành động khác.",[["她看着看着书，就睡着了。","Tā kànzhe kànzhe shū, jiù shuì zháo le.","Cô ấy đang xem sách, thì ngủ gật mất rồi."]],{"py": "Trạng thái mới","use": "","note": "","src": "file"}],["究竟","究竟","Phó từ, dùng trong câu hỏi nghi vấn/có đại từ nghi vấn, nhấn mạnh ngữ khí truy vấn (rốt cuộc), thường dùng trong văn viết.",[["究竟哪个季节去丽江旅游比较好.","Jiūjìng nǎ ge jìjié qù Lìjiāng lǚyóu bǐjiào hǎo","Rốt cuộc đi du lịch Lệ Giang vào mùa nào là tốt nhất?"]],{"py": "jiūjìng","use": "","note": "","src": "file"}],["Cấu trúc: 动词+ 起","Cấu trúc: 动词+ 起","Cấu trúc này nhấn mạnh sự khởi điểm của hành động hướng vào một đối tượng cụ thể. Tân ngữ thường là nội dung của cuộc nói chuyện, câu hỏi, hoặc đối tượng của ký ức, cảm xúc.",[["他偶然说起了学生时代的往事。","Tā ǒurán shuō qǐ le xuéshēng shídài de wǎngshì","Anh ấy tình cờ nhắc đến chuyện cũ thời học sinh."]],{"py": "","use": "","note": "","src": "file"}]],"5": [["与其……不如……","与其 A，不如 B","So sánh hai lựa chọn: thay vì A, chi bằng B (B được ưu tiên hơn).",[["与其在这儿干着急，不如我们主动打电话去问问情况。","Yǔqí zài zhèr gān zháojí, bùrú wǒmen zhǔdòng dǎ diànhuà qù wèn wen qíngkuàng","Thà rằng cứ ngồi đây lo sốt vó, chi bằng chúng ta chủ động gọi điện hỏi tình hình."]],{"py": "yǔqí … bùrú …","use": "So sánh hai lựa chọn: thà chọn B hơn là A.","note": "Đặt phương án không nên chọn sau 与其, phương án nên chọn sau 不如. 不如 còn dùng để nói 'không bằng'.","src": "file"}],["……得不得了 / ……得很","tính từ / động từ tâm lý + 得不得了 / 得很","Bổ ngữ mức độ nhấn rất cao: 'vô cùng, hết sức'.",[["我今天忙了一整天，现在累得不行。","Wǒ jīntiān máng le yī zhěng tiān, xiànzài lèi de bùxíng","Hôm nay tôi bận cả ngày, giờ mệt không chịu nổi"]],{"py": "de bùdéliǎo / de hěn","use": "Đứng sau tính từ hoặc động từ tâm lý (高兴, 累, 担心).","note": "Không dùng với phủ định. 得很 nhẹ hơn 得不得了. Không thêm 很 trước tính từ.","src": "file"}],["毕竟 (dù sao thì, rốt cuộc)","……，毕竟 + lý do cơ bản","毕竟 nhấn một sự thật căn bản cần chú ý, dùng để giải thích hay bao dung.",[["虽然我们遇到了很多困难，但毕竟完成了任务。","Suīrán wǒmen yù dàole hěn duō kùnnan, dàn bìjìng wánchéngle rènwù.","Mặc dù chúng ta đã gặp rất nhiều khó khăn, nhưng rốt cuộc cũng đã hoàn thành nhiệm vụ."]],{"py": "bìjìng","use": "Đặt trước vị ngữ hoặc đầu vế sau.","note": "Dùng để biện hộ hoặc lý giải; khác 到底 (rốt cuộc, trong câu hỏi).","src": "file"}],["反正 (dù sao)","反正 + kết luận","反正 nói kết quả không thay đổi dù điều kiện thế nào.",[["不管你们谁去，反正我不会去。","Bùguǎn nǐmen shuí qù, fǎnzhèng wǒ bú huì qù","Bất kể ai trong các cậu đi, dù sao thì tôi cũng sẽ không đi."],["你别再说了，反正我是会考虑的。","Nǐ bié zài shuōle, fǎnzhèng wǒ shì huì kǎolǜ de.","Cậu đừng nói nữa, dù sao thì tôi cũng sẽ xem xét."]],{"py": "fǎnzhèng","use": "Đứng đầu vế sau hoặc sau chủ ngữ.","note": "Nhiều khi đi sau từ nghi vấn hoặc 不管. Mang sắc thái bất cần, không dùng trong văn trang trọng.","src": "file"}],["尽量 (cố hết sức, tối đa)","尽量 + động từ","尽量 nói cố gắng làm đến mức tối đa có thể.",[["老年人要尽量少吃油炸食品。","Lǎonián rén yào jǐnliàng shǎo chī yóu zhá shí pǐn","Người già cần cố gắng hạn chế ăn đồ chiên rán."]],{"py": "jǐnliàng","use": "Đứng trước động từ.","note": "Không dùng 很 trước 尽量. Dùng 尽量 + 少/多 cho 'ít/nhiều nhất có thể'.","src": "file"}],["互相 (lẫn nhau)","互相 + động từ","互相 nói hành động diễn ra giữa hai hoặc nhiều bên.",[["朋友之间应该互相帮助。","Péngyou zhī jiān yīnggāi hùxiāng bāngzhù.","Bạn bè nên giúp đỡ lẫn nhau."],["我们互相学习，互相进步。","Wǒmen hùxiāng xuéxí, hùxiāng jìnbù.","Chúng tôi học hỏi và tiến bộ cùng nhau."]],{"py": "hùxiāng","use": "Đặt trước động từ, tân ngữ thường không cần.","note": "Không thêm tân ngữ sau động từ khi dùng 互相 (nói 我们互相帮助, không nói 我们互相帮助他们)."}],["不得不 (buộc phải)","不得不 + động từ","不得不 nói bị hoàn cảnh ép phải làm, không còn lựa chọn.",[["下雨了，我们不得不取消比赛。","Xià yǔ le, wǒmen bùdébù qǔxiāo bǐsài.","Trời mưa, chúng tôi buộc phải hủy trận đấu."],["钱不够，他不得不借钱。","Qián bú gòu, tā bùdébù jiè qián.","Không đủ tiền, anh ấy buộc phải đi vay."]],{"py": "bùdébù","use": "Đặt trước động từ, thường có 只好 tương tự.","note": "Mang sắc thái miễn cưỡng, khác 必须 (phải, chủ động hơn)."}],["干脆 (dứt khoát, thà rằng)","干脆 + động từ","干脆 nói quyết định dứt khoát, làm luôn cho xong.",[["我求他帮忙，他答应得很干脆。","Wǒ qiú tā bāngmáng, tā dāyìng de hěn gāncuì","Tôi nhờ anh ấy giúp đỡ, anh ấy đồng ý rất dứt khoát."],["我看我干脆放弃好了。","Wǒ kàn wǒ gāncuì fàngqì hǎo le.","Tôi nghĩ tôi cứ từ bỏ đi thôi."]],{"py": "gāncuì","use": "Đứng trước động từ, thường sau một tình huống khó giải quyết.","note": "Dùng cho quyết định tự chọn. Không dùng 干脆 cho hành động bị ép buộc.","src": "file"}],["简直 (quả là, hầu như)","简直 + câu nhấn mạnh","简直 nhấn mạnh mức độ cực đoan, gần như đúng như vậy.",[["与从前相比，简直像换了个人。","Yǔ cóngqián xiāng bǐ, jiǎnzhí xiàng huànle gè rén","So với trước đây, (cô ấy) quả là như đã thay đổi thành một người khác."]],{"py": "jiǎnzhí","use": "Đặt trước động từ hoặc tính từ.","note": "Thường dùng với cách nói cường điệu. Không dùng trong văn phong khách quan.","src": "file"}],["曾经 (từng)","曾经 + động từ + 过 / 了","曾经 nói điều đã từng xảy ra trong quá khứ, thường đi với 过.",[["我曾经去过北京两次。","Wǒ céngjīng qù guò Běijīng liǎng cì","Tôi đã từng đi Bắc Kinh hai lần."],["他曾经是一名老师，后来转行做了记者。","Tā céngjīng shì yī míng lǎoshī, hòulái zhuǎnháng zuò le jìzhě","Anh ấy từng là một giáo viên, sau đó chuyển ngành làm phóng viên."]],{"py": "céngjīng","use": "Đứng trước động từ.","note": "Phủ định dùng 没(有)……过, không dùng 不曾经. 曾经 thường kèm 过.","src": "file"}],["一再 (hết lần này đến lần khác)","一再 + động từ","一再 nói hành động lặp đi lặp lại nhiều lần.",[["老师一再提醒我们要认真复习。","Lǎoshī yízài tíxǐng wǒmen yào rènzhēn fùxí.","Thầy giáo nhắc đi nhắc lại chúng tôi phải ôn bài nghiêm túc."],["他一再道歉，我也就原谅他了。","Tā yízài dàoqiàn, wǒ yě jiù yuánliàng tā le.","Anh ấy xin lỗi hết lần này đến lần khác, tôi cũng tha thứ."]],{"py": "yízài","use": "Đứng trước động từ, thường đi với 强调, 表示, 说.","note": "Dùng cho việc đã lặp lại nhiều lần; không dùng cho một lần duy nhất."}],["一向 (xưa nay, từ trước đến giờ)","一向 + động từ / tính từ","一向 nói thói quen hay trạng thái duy trì từ trước đến giờ.",[["他一向很守时。","Tā yíxiàng hěn shǒushí.","Anh ấy xưa nay luôn đúng giờ."],["我一向不喜欢吃辣的。","Wǒ yíxiàng bù xǐhuan chī là de.","Từ trước đến nay tôi không thích ăn cay."]],{"py": "yíxiàng","use": "Đứng trước động từ hoặc tính từ.","note": "Khác 从来 (phủ định nhiều hơn). 一向 trung tính, dùng cả khẳng định."}],["白 (uổng công)","白 + động từ","白 nói làm việc mà không đạt kết quả, hoặc làm không công.",[["我白跑了一趟，他不在家。","Wǒ bái pǎo le yí tàng, tā bú zài jiā.","Tôi chạy uổng một chuyến, anh ấy không ở nhà."],["你的努力不会白费的。","Nǐ de nǔlì bú huì báifèi de.","Sự nỗ lực của bạn sẽ không uổng phí."]],{"py": "bái","use": "Đứng trước động từ.","note": "Chỉ dùng cho việc làm không có kết quả hoặc không được đền đáp. Khác nghĩa 'màu trắng'."}],["顺便 (nhân tiện)","顺便 + động từ","顺便 nói làm thêm một việc nhân dịp làm việc khác.",[["你去超市，顺便帮我买点儿水果。","Nǐ qù chāoshì, shùnbiàn bāng wǒ mǎi diǎnr shuǐguǒ.","Bạn đi siêu thị, tiện thể mua giúp tôi ít trái cây."],["我去邮局，顺便给你寄信。","Wǒ qù yóujú, shùnbiàn gěi nǐ jì xìn.","Tôi đi bưu điện, tiện thể gửi thư cho bạn."]],{"py": "shùnbiàn","use": "Đứng trước động từ, thường đi với 去, 买, 看.","note": "Việc phụ phải tiện cho việc chính. Không dùng khi việc là chính."}],["难免 (khó tránh khỏi)","难免 + (会) + động từ","难免 nói điều khó tránh được trong hoàn cảnh nào đó.",[["朋友间难免会发生矛盾、误会甚至是伤害。","Péngyǒu jiān nánmiǎn huì fāshēng máodùn, wùhuì shènzhì shì shānghài","Giữa bạn bè khó tránh khỏi việc xảy ra mâu thuẫn, hiểu lầm thậm chí là tổn thương."]],{"py": "nánmiǎn","use": "Đứng trước động từ, có thể kèm 会.","note": "Thường là điều không như ý. Không dùng cho điều hoàn toàn có thể tránh.","src": "file"}],["自从 / ……以来","自从 + mốc thời gian，…… ; …… + 以来","Nói một khoảng thời gian kéo dài từ một mốc trong quá khứ đến hiện tại.",[["改革开放以来，中国发生了巨大的变化。","Gǎigé kāifàng yǐlái, Zhōngguó fāshēngle jùdà de biànhuà","Từ khi cải cách mở cửa đến nay, Trung Quốc đã có những thay đổi to lớn."]],{"py": "zìcóng / yǐlái","use": "自从 đặt đầu; 以来 đặt sau mốc.","note": "Chỉ dùng cho quá khứ đến hiện tại. Không dùng với tương lai.","src": "file"}],["凭 (dựa vào)","凭 + căn cứ + động từ","凭 nêu căn cứ hoặc dựa vào điều gì để làm.",[["干工作不能光凭经验，还要有创新。","Gàn gōngzuò bù néng guāng píng jīngyàn, hái yào yǒu chuàngxīn","Làm việc không thể chỉ dựa vào kinh nghiệm, còn phải có sự đổi mới."],["请旅客们准备好车票，凭票进站。","Qǐng lǚkèmen zhǔnbèi hǎo chēpiào, píng piào jìn zhàn","Xin hành khách hãy chuẩn bị sẵn vé tàu, dựa vào vé để vào ga."]],{"py": "píng","use": "Đứng trước động từ; dùng trong câu hỏi 凭什么 để chất vấn.","note": "凭什么 mang ý phản đối hoặc bất bình. 凭 + 证件 nghĩa 'dựa vào giấy tờ'.","src": "file"}],["至于 (còn về)","至于 + chủ đề mới，……","至于 chuyển sang bàn một chủ đề khác có liên quan.",[["我只是和你开个玩笑，你至于生那么大的气吗？","Wǒ zhǐshì hé nǐ kāi gè wánxiào, nǐ zhìyú shēng nàme dà de qì ma","Tôi chỉ đùa với cậu thôi, cậu đến mức phải tức giận lớn như vậy sao?"],["我只知道他是六班的学生，至于住在哪儿，我就不清楚了。","Wǒ zhǐ zhīdào tā shì liù bān de xuésheng, zhìyú zhù zài nǎ'er, wǒ jiù bù qīngchǔle","Tôi chỉ biết anh ấy là học sinh lớp 6, còn về việc anh ấy sống ở đâu, thì tôi không rõ."]],{"py": "zhìyú","use": "Đứng đầu vế sau để giới thiệu chủ đề mới.","note": "Không dùng 至于 cho chủ đề đã nói. 至于 còn nghĩa 'đến mức' trong câu phủ định (不至于).","src": "file"}],["趁 (nhân lúc)","趁 + thời cơ + động từ","趁 nói tận dụng cơ hội để làm việc gì.",[["萝卜饼要趁热吃。","Luóbo bǐng yào chèn rè chī","Bánh củ cải phải ăn lúc còn nóng."]],{"py": "chèn","use": "Đứng trước thời cơ, sau đó nêu việc làm.","note": "Thời cơ phải là điều kiện thuận lợi. Không dùng 趁 + hành động tiêu cực.","src": "file"}],["要不是 / 多亏","要不是 + giả thiết，(就) + kết quả ; 多亏 + người / việc","要不是 nói 'nếu không phải … thì …'; 多亏 nói 'nhờ có'.",[["今天搬家多亏有你在，你可帮我太忙了。","Jīntiān bānjiā duōkuī yǒu nǐ zài, nǐ kě bāng wǒ tài máng le","Hôm nay chuyển nhà may nhờ có cậu ở đây, cậu đã giúp tôi quá nhiều rồi."]],{"py": "yàobushì / duōkuī","use": "Hai cấu trúc dùng khi cảm ơn hoặc hối tiếc.","note": "多亏 luôn hướng đến kết quả tốt. 要不是 có thể hướng đến kết quả xấu.","src": "file"}],["算 (coi như, xem là)","A 算 + B ; 算是 + …","算 dùng để nhận định coi một điều là thuộc loại nào đó, thường là đánh giá tương đối.",[["这钱就算我借给你的，将来你有了的时候再还我。","Zhè qián jiù suàn wǒ jiè gěi nǐ de, jiānglái nǐ yǒule de shíhou zài hái wǒ","Số tiền này cứ coi như tôi cho cậu mượn, sau này khi cậu có thì trả lại tôi."],["算了吧，你跑得再快，也追不上会飞的鸟啊。","Suànle ba, nǐ pǎo dé zài kuài, yě zhuī bù shàng huì fēi de niǎo a","Thôi đi, cậu chạy nhanh đến mấy cũng không đuổi kịp con chim biết bay đâu."]],{"py": "suàn","use": "Đứng trước danh từ hoặc tính từ.","note": "Nghĩa 'tính toán' khác; ở đây là 'coi như'. 算 thường kèm 是 hoặc 不上.","src": "file"}],["将 (sẽ)","chủ ngữ + 将 + động từ","将 là cách nói trang trọng của 要 hoặc 会, nói việc sắp xảy ra.",[["明天将有大雨。","Míngtiān jiāng yǒu dàyǔ.","Ngày mai sẽ có mưa lớn."],["会议将于下周举行。","Huìyì jiāng yú xià zhōu jǔxíng.","Cuộc họp sẽ được tổ chức vào tuần sau."]],{"py": "jiāng","use": "Dùng trong văn viết, tin tức, thông báo.","note": "Không dùng trong khẩu ngữ thân mật. 将 còn là giới từ như 把 (将书放好)."}],["一旦……就……","一旦 + điều kiện，就 + kết quả","Một khi điều kiện xảy ra thì có kết quả quan trọng.",[["一旦有人闯入这个空间，我们就会感觉不舒服、不自在。","Yīdàn yǒu rén chuǎng rù zhège kōngjiān, wǒmen jiù huì gǎnjué bù shūfú, bù zìzài","Một khi có người đột nhập vào không gian này, chúng ta sẽ cảm thấy không thoải mái, không tự nhiên."]],{"py": "yídàn … jiù …","use": "Dùng cho kết quả nghiêm trọng hoặc rõ rệt.","note": "一旦 nhấn giả định 'một khi điều đó xảy ra', thường dẫn tới kết quả đáng chú ý.","src": "file"}],["就算 / 哪怕 / 就是 (dù cho)","就算 / 哪怕 + giả thiết，也 / 还是 + kết quả","Các cách nói giống 即使, thêm sắc thái nhấn mạnh.",[["哪怕再忙，我也要锻炼。","Nǎpà zài máng, wǒ yě yào duànliàn.","Dù bận đến mấy, tôi cũng phải tập thể dục."],["就算下雨，我们也会去。","Jiùsuàn xià yǔ, wǒmen yě huì qù.","Dù trời mưa, chúng tôi cũng sẽ đi."]],{"py": "jiùsuàn / nǎpà / jiùshì","use": "哪怕 và 就算 thân mật hơn 即使.","note": "Phải có 也 hoặc 还是 ở vế sau. Không dùng 但是 vế sau."}],["万一 (lỡ, nhỡ)","万一 + tình huống xấu，(就 / 要) + …","万一 nói khả năng rất nhỏ nhưng nếu xảy ra thì hậu quả nghiêm trọng.",[["你带上伞吧，万一回来的时候下雨呢。","Nǐ dài shàng sǎn ba, wànyī huílái de shíhòu xià yǔ ne","Cậu mang theo ô đi, nhỡ đâu lúc về trời mưa thì sao."],["我们考虑了所有可能性，连最坏的万一也都想到了。","Wǒmen kǎolǜ le suǒyǒu kěnéngxìng, lián zuì huài de wànyī yě dōu xiǎngdào le","Chúng tôi đã cân nhắc mọi khả năng, ngay cả trường hợp xấu nhất cũng đã nghĩ tới."]],{"py": "wànyī","use": "Đứng đầu vế điều kiện, thường để cảnh báo.","note": "Chỉ dùng cho khả năng thấp. Không dùng cho tình huống thường xảy ra.","src": "file"}],["宁可……也不…… (thà … còn hơn …)","宁可 + A，也不 + B","宁可 chọn A để tránh B, A là phương án ít tệ hơn.",[["作为母亲，她宁可自己累一点儿，也不想委屈了孩子。","Zuòwéi mǔqīn, tā nìngkě zìjǐ lèi yīdiǎn er, yě bù xiǎng wěiqu le háizi","Với tư cách là một người mẹ, cô ấy thà rằng mình mệt một chút, cũng không muốn làm con cái phải chịu thiệt thòi"]],{"py": "nìngkě … yě bù …","use": "宁可 có thể thay bằng 宁愿, 宁肯.","note": "Phương án chọn nằm sau 宁可, phương án bị bác nằm sau 也不. Khác 与其……不如: ở đây đã chọn.","src": "file"}],["难怪 (thảo nào)","难怪 + kết quả，原来 + nguyên nhân","难怪 nói ra điều vỡ lẽ: hiểu vì sao có kết quả đó.",[["这也难怪","Zhè yě nánguài","Điều này cũng không trách được."],["你的抽屉真乱，难怪总是找不到东西。","Nǐ de chōuti zhēn luàn, nánguài zǒng shì zhǎo bù dào dōngxi","Ngăn kéo của cậu thật bừa bộn, thảo nào luôn không tìm thấy đồ."]],{"py": "nánguài","use": "Thường đi cùng 原来 hoặc 因为.","note": "Dùng khi đã biết nguyên nhân. Không dùng cho đoán mò.","src": "file"}],["不仅 (không những)","不仅 + A，而且 / 还 / 也 + B","Nói không chỉ A mà còn B, văn viết hơn 不但.",[["他不仅会说汉语，而且会说日语。","Tā bùjǐn huì shuō Hànyǔ, érqiě huì shuō Rìyǔ.","Anh ấy không chỉ nói được tiếng Trung mà còn nói được tiếng Nhật."],["这家店不仅便宜，还很干净。","Zhè jiā diàn bùjǐn piányi, hái hěn gānjìng.","Quán này không những rẻ mà còn sạch sẽ."]],{"py": "bùjǐn","use": "Đứng đầu vế đầu, vế sau thêm 而且/还/也.","note": "不仅 có thể đứng đầu câu hoặc sau chủ ngữ. Cũng có thể dùng đơn lẻ."}],["比起 / 不如 (so với / không bằng)","比起 + B，A + …… ; A + 不如 + B","比起 mở đầu so sánh; 不如 nói A không bằng B.",[["三家的营业额加起来还不如他一家高。","Sān jiā de yíngyè'é jiā qǐlái hái bù rú tā yī jiā gāo","Doanh thu của ba cửa hàng cộng lại còn không cao bằng doanh thu của một mình cửa hàng anh ấy."]],{"py": "bǐqǐ / bùrú","use": "比起 đứng đầu vế; 不如 đứng giữa A và B.","note": "不如 nghĩa 'không bằng'; khác 与其……不如 (thà … còn hơn).","src": "file"}],["受 (bị, được, chịu)","受 + danh từ / động từ hai âm tiết","受 là động từ chỉ trạng thái bị hoặc nhận ảnh hưởng, như bị động trang trọng.",[["这本书很受年轻人欢迎。","Zhè běn shū hěn shòu niánqīngrén huānyíng.","Cuốn sách này rất được giới trẻ yêu thích."],["他受了很大的影响。","Tā shòu le hěn dà de yǐngxiǎng.","Anh ấy chịu ảnh hưởng rất lớn."]],{"py": "shòu","use": "Dùng với 欢迎, 影响, 批评, 伤, 欺负...","note": "受 thường theo sau là danh từ hoặc động từ hai âm tiết. Không dùng với động từ đơn âm tiết."}],["以便 / 好 (để có thể)","hành động 1，以便 / 好 + hành động 2","Nêu mục đích tạo thuận lợi cho việc tiếp theo.",[["请留下电话，以便我们联系你。","Qǐng liúxià diànhuà, yǐbiàn wǒmen liánxì nǐ.","Xin để lại số điện thoại để chúng tôi liên lạc với bạn."],["我早点儿睡，明天好早起。","Wǒ zǎodiǎnr shuì, míngtiān hǎo zǎo qǐ.","Tôi đi ngủ sớm để ngày mai dậy sớm."]],{"py": "yǐbiàn / hǎo","use": "Đứng đầu vế sau.","note": "Dùng cho mục đích tích cực. Không đổi vị trí hai vế."}],["一面……一面……","一面 + động từ 1，一面 + động từ 2","Giống 一边……一边……, hai hành động diễn ra đồng thời.",[["他一面吃饭，一面看书。","Tā yímiàn chī fàn, yímiàn kàn shū.","Anh ấy vừa ăn cơm vừa đọc sách."],["她一面哭，一面说着自己的故事。","Tā yímiàn kū, yímiàn shuō zhe zìjǐ de gùshi.","Cô ấy vừa khóc vừa kể chuyện của mình."]],{"py": "yímiàn … yímiàn …","use": "Dùng trong văn viết hơn 一边.","note": "Chủ ngữ phải giống nhau. Hai hành động phải đồng thời."}],["别说 / 何况 (huống hồ)","别说 + A，就是 / 连 + B + 也 / 都……","Nói điều nhẹ hơn còn không làm được, huống hồ điều nặng hơn.",[["连运动员都不满意，更何况看比赛的球迷呢。","Lián yùndòngyuán dōu bù mǎnyì, gèng hékuàng kàn bǐsài de qiúmí ne.","Ngay cả vận động viên cũng không hài lòng, huống hồ là người hâm mộ xem trận đấu."]],{"py": "biéshuō / hékuàng","use": "何况 nêu thêm lý do làm nặng thêm.","note": "Phải có hai mức độ so sánh. 别说 thân mật hơn 何况.","src": "file"}],["Hậu tố 化 (hóa)","danh từ / tính từ + 化","化 tạo động từ nghĩa 'trở nên, hóa': 现代化, 绿化.",[["城市正在不断现代化。","Chéngshì zhèngzài búduàn xiàndàihuà.","Thành phố đang không ngừng hiện đại hóa."],["我们要把工作简单化。","Wǒmen yào bǎ gōngzuò jiǎndānhuà.","Chúng ta phải đơn giản hóa công việc."]],{"py": "huà","use": "Dùng trong văn viết, nói về xu hướng.","note": "化 là hậu tố tạo động từ, thường nằm trong từ ghép sẵn (现代化, 绿化) hoặc đi với 把/使, không gắn tùy tiện vào mọi từ."}],["Bổ ngữ kết quả 着 (zháo)","động từ + 着 (zháo)","着 (zháo) đứng sau động từ để nói hành động đã đạt mục đích.",[["昨晚我一直睡不着。","Zuówǎn wǒ yìzhí shuì bu zháo.","Tối qua tôi mãi không ngủ được."],["我终于找着钥匙了。","Wǒ zhōngyú zhǎozháo yàoshi le.","Cuối cùng tôi cũng tìm thấy chìa khóa."]],{"py": "zháo","use": "Thường dùng với 睡, 找, 买, 看, 猜.","note": "Đọc zháo, không phải zhe. Phủ định dùng 没 hoặc 不: 睡不着 (không ngủ được)."}],["都 (cách dùng mở rộng)","都 + (了) ; 连……都……","都 còn có nghĩa 'đã … rồi' (để nhấn thời gian) hoặc 'ngay cả'.",[["都十二点了，你怎么还不睡？","Dōu shí'èr diǎn le, nǐ zěnme hái bú shuì?","Đã mười hai giờ rồi, sao bạn vẫn chưa ngủ?"],["他都七十岁了，还在工作。","Tā dōu qīshí suì le, hái zài gōngzuò.","Ông ấy đã bảy mươi tuổi rồi mà vẫn đi làm."]],{"py": "dōu (kuòzhǎn)","use": "Đặt sau chủ ngữ; 都……了 nhấn việc đã đến mức nào đó.","note": "Không phải lúc nào 都 cũng là 'tất cả'. Dựa vào ngữ cảnh để xác định."}],["如何 (như thế nào)","如何 + động từ ; 不知如何……","如何 là cách nói văn viết của 怎么样 / 怎么, hỏi cách thức hoặc tình trạng.",[["我们明天举行会议，讨论这个问题该如何解决。","Wǒmen míngtiān jǔxíng huìyì, tǎolùn zhè ge wèntí gāi rúhé jiějué.","Chúng ta ngày mai tổ chức cuộc họp, thảo luận vấn đề này nên giải quyết thế nào 80"],["后”们月收入情况如何？","Bālíng hòu men yuè shōurù qíngkuàng rúhé?","Tình hình thu nhập hàng tháng của thế hệ “8x” như thế nào?"]],{"py": "rúhé","use": "Đứng trước động từ hoặc làm vị ngữ: 结果如何？","note": "Trang trọng hơn 怎么. Không dùng 如何 để hỏi nguyên nhân (dùng 为什么).","src": "file"}],["居然 (không ngờ lại)","居然 + động từ / tính từ","居然 diễn tả kết quả bất ngờ, trái dự đoán, thường mang chút ngạc nhiên.",[["这么简单的题，你居然也不会做？上课时都干什么去了？","Zhème jiǎndān de tí, nǐ jūrán yě bú huì zuò? Shàngkè shí dōu gàn shénme qùle","Bài tập đơn giản thế này mà cậu lại cũng không biết làm? Lúc lên lớp đã làm gì vậy?"]],{"py": "jūrán","use": "Đứng trước vị ngữ.","note": "Giống 竟然 (đã có ở HSK4). Chỉ dùng cho sự việc đã xảy ra, không dùng cho dự đoán tương lai.","src": "file"}],["临…… (sắp, đến lúc …)","临 + động từ + 的时候 / 前","临 nói thời điểm sắp xảy ra điều gì, 'sắp, trước khi'.",[["临江新修了一条路，晚饭后很多人都去那儿散步。","Lín jiāng xīn xiūle yī tiáo lù, wǎnfàn hòu hěn duō rén dōu qù nà'er sànbù","Gần bờ sông mới xây một con đường, sau bữa tối rất nhiều người đi dạo ở đó."],["临走那天，父亲从老家赶来送我们。","Lín zǒu nèitiān, fùqin cóng lǎojiā gǎn lái sòng wǒmen","Ngày sắp đi, bố tôi từ quê nhà đến tiễn chúng tôi."]],{"py": "lín …","use": "Đứng đầu câu: 临走前, 临睡觉.","note": "Phong cách văn viết. Thường đi với 前 hoặc 的时候.","src": "file"}],["立刻 / 马上 (lập tức)","立刻 + động từ","立刻 nói hành động xảy ra ngay sau đó, không chậm trễ.",[["实验数据一出来，研究员们立刻展开了激烈的讨论。","Shíyàn shùjù yī chūlái, yánjiūyuán men lìkè zhǎnkāi le jīliè de tǎolùn","Ngay khi dữ liệu thí nghiệm vừa được công bố, các nhà nghiên cứu lập tức triển khai một cuộc thảo luận sôi nổi."]],{"py": "lìkè / mǎshàng","use": "Đứng trước động từ. 马上 khẩu ngữ hơn.","note": "Không dùng cho thói quen lặp lại. Khác 一下子 (đột ngột).","src": "file"}],["各自 (mỗi người / bên)","主语 + 各自 + 动词","各自 nói từng người hoặc từng bên làm việc riêng của mình.",[["学生们都有各自的理想。","Xuéshēngmen dōu yǒu gèzì de lǐxiǎng","Các học sinh đều có những lý tưởng riêng."]],{"py": "gèzì","use": "Chủ ngữ ở số nhiều, 各自 đứng trước động từ.","note": "Chủ ngữ phải có từ hai người trở lên. Khác 自己 (bản thân).","src": "file"}],["包括 (bao gồm)","A 包括 B、C 和 D","包括 liệt kê các thành phần nằm trong tổng thể.",[["汉语技能教学包括听、说、读、写四个方面","Hànyǔ jìnéng jiàoxué bāokuò tīng, shuō, dú, xiě sì gè fāngmiàn","Giảng dạy kỹ năng tiếng Hán bao gồm bốn khía cạnh: nghe, nói, đọc, viết."],["我们班所有人，包括最不爱运动的刘方也都参加了这次运动会。","Wǒmen bān suǒyǒu rén, bāokuò zuì bù ài yùndòng de Liú Fāng yě dōu cānjiāle zhè cì yùndònghuì.","Tất cả mọi người trong lớp chúng tôi, bao gồm cả Lưu Phương, người ít yêu thích thể thao nhất, cũng đã tham gia hội thao lần này."]],{"py": "bāokuò","use": "Dùng làm động từ; 包括……在内 nhấn mạnh đã tính cả.","note": "Khác 包含 (hàm chứa ý nghĩa, nội dung). 包括 thường đi với liệt kê cụ thể.","src": "file"}],["至今 (cho đến nay)","至今 + (还 / 仍然) + động từ","至今 nói tình trạng kéo dài từ quá khứ đến hiện tại.",[["那件事的真相至今仍是一个谜。","Nà jiàn shì de zhēnxiàng zhìjīn réng shì yī gè mí","Sự thật về vụ việc đó đến nay vẫn là một bí ẩn."]],{"py": "zhìjīn","use": "Đứng trước động từ, thường kèm 还, 仍然, 没有.","note": "Văn viết. Không dùng cho hành động đã chấm dứt.","src": "file"}],["从而 (do đó, nhờ vậy)","A，从而 + B","从而 nối nguyên nhân với kết quả hoặc mục đích, văn viết.",[["比赛前做好思想准备可以减少运动员的压力，从而取得比赛的成功。","Bǐsài qián zuò hǎo sīxiǎng zhǔnbèi kěyǐ jiǎnshǎo yùndòngyuán de yālì, cóng'ér qǔdé bǐsài de chénggōng.","Chuẩn bị tư tưởng tốt trước trận đấu có thể giảm áp lực cho vận động viên, từ đó đạt được thành công trong trận đấu."]],{"py": "cóng'ér","use": "Đứng đầu vế sau; chủ ngữ thường dùng chung với vế trước.","note": "Không dùng như 所以 trong khẩu ngữ. Thường thể hiện kết quả tích cực.","src": "file"}],["替 (thay, giúp)","替 + người + động từ","替 nghĩa 'thay cho, giúp' ai làm việc gì.",[["刘老师今天有点儿事来不了，你能替他吗？","Liú lǎoshī jīntiān yǒudiǎn er shì lái bù liǎo, nǐ néng tì tì tā ma","Thầy Lưu hôm nay có chút việc không đến được, cậu có thể thay thầy ấy được không?"],["李阳要去留学了，我们都替他高兴。","Lǐ Yáng yào qù liúxué le, wǒmen dōu tì tā gāoxìng","Lý Dương sắp đi du học rồi, chúng tôi đều mừng cho cậu ấy."]],{"py": "tì","use": "Đứng trước động từ, sau chủ ngữ.","note": "Khác 给 (đưa/cho) và 为 (vì). 替 nhấn làm thay.","src": "file"}],["说不定 (biết đâu)","说不定 + động từ / câu","说不定 nói khả năng có thể xảy ra nhưng chưa chắc.",[["这事儿经理已经同意了，只是出发的时间还说不定。","Zhè shì'er jīnglǐ yǐjīng tóngyìle, zhǐshì chūfā de shíjiān hái shuōbudìng","Việc này giám đốc đã đồng ý rồi, chỉ là thời gian xuất phát thì vẫn chưa thể nói rõ."],["别随随便便就说放弃，说不定下次会成功了。","Bié suí suí biàn biàn jiù shuō fàngqì, shuōbudìng xià cì huì chénggōngle","Đừng tùy tiện nói từ bỏ, biết đâu lần sau sẽ thành công."]],{"py": "shuōbudìng","use": "Đứng đầu câu hoặc trước vị ngữ.","note": "Không dùng cho điều chắc chắn. Gần 也许, 可能 nhưng khẩu ngữ hơn.","src": "file"}],["似的 (giống như)","A 像 / 好像 B 似的","似的 đặt sau từ hoặc cụm từ để so sánh: 'giống như…'.",[["大雨过后，湖面平静得镜子似的，倒映着整个天空。","Dà yǔ guò hòu, húmiàn píngjìng de jìngzi shìde, dàoyìng zhe zhěnggè tiānkōng","Sau cơn mưa lớn, mặt hồ phẳng lặng như tấm gương vậy, in bóng cả bầu trời."],["听说偶像要来，她激动得什么似的，一整晚都没睡好。","Tīng shuō ǒuxiàng yào lái, tā jīdòng de shénme shìde, yī zhěng wǎn dōu méi shuì hǎo","Nghe tin thần tượng sắp đến, cô ấy hào hứng đến mức không tả xiết, cả đêm không sao ngủ được."]],{"py": "shìde","use": "Thường dùng sau 像, 好像; đứng cuối cụm.","note": "Chữ 的 đọc thanh nhẹ. Không dùng trực tiếp sau tính từ mà không có hình ảnh so sánh.","src": "file"}],["纷纷 (lần lượt, dồn dập)","主语（多人）+ 纷纷 + 动词","纷纷 nói nhiều người hoặc nhiều vật cùng làm việc một cách liên tiếp.",[["秋风刮起，落叶纷纷。","Qiūfēng guā qǐ, luòyè fēnfēn","Gió thu thổi lên, lá rụng xôn xao"],["要下雨了，路上的人纷纷往家里跑。","Yào xià yǔ le, lùshàng de rén fēnfēn wǎng jiā lǐ pǎo","Sắp mưa rồi, người đi đường dồn dập chạy về nhà."]],{"py": "fēnfēn","use": "Chủ ngữ phải là số nhiều; 纷纷 đứng trước động từ.","note": "Không dùng với một người. Khác 陆续 (lần lượt theo thứ tự).","src": "file"}],["来……去…… (qua lại, lặp đi lặp lại)","动词1 + 来 + 动词1 + 去","Lặp lại một động từ để nhấn hành động diễn ra nhiều lần, qua lại.",[["小狗追着自己的尾巴，在草地上跑来跑去。","Xiǎo gǒu zhuīzhe zìjǐ de wěibā, zài cǎodì shang pǎo lái pǎo qù","Chú chó nhỏ đuổi theo cái đuôi của mình, chạy đi chạy lại trên bãi cỏ."],["他们研究来讨论去，还是没找出原因。","Tāmen yánjiū lái tǎolùn qù, háishì méi zhǎo chū yuányīn.","Bọn họ nghiên cứu tới thảo luận lui, vẫn không tìm ra nguyên nhân."]],{"py": "lái … qù …","use": "Dùng cho động từ như 想, 看, 走, 说.","note": "Nghĩa thường là 'mãi, đi đi lại lại' và thường theo sau là kết luận.","src": "file"}],["要不 / 要不然 (nếu không thì)","……，要不然 + hậu quả ; 要不 + đề nghị","要不然 nêu hậu quả nếu không làm; 要不 trong khẩu ngữ còn dùng để đề nghị phương án khác.",[["还好碰见你了，要不然我今天肯定会迟到了。","Hái hǎo pèngjiàn nǐ le, yàoburán wǒ jīntiān kěndìng huì chídàole","May mà gặp được cậu, nếu không thì hôm nay tôi chắc chắn sẽ bị trễ rồi."],["今天太晚了，要不你明天再走吧。","Jīntiān tài wǎnle, yàobù nǐ míngtiān zài zǒu ba","Hôm nay muộn quá rồi, hay là cậu ngày mai hãy đi."]],{"py": "yàobù / yàobùrán","use": "Đứng đầu vế sau.","note": "Khẩu ngữ hơn 否则. 要不 + đề nghị: 要不我们坐地铁吧。","src": "file"}],["作为 (với tư cách là)","作为 + danh từ，……","作为 nêu thân phận, vai trò của chủ thể.",[["北海公园离家最近，所以我把那儿作为每晚散步的去处。","Běihǎi Gōngyuán lí jiā zuì jìn, suǒyǐ wǒ bǎ nà'er zuòwéi měi wǎn sànbù de qùchù","Công viên Bắc Hải gần nhà nhất, nên tôi coi đó là nơi đi dạo mỗi tối."],["作为大作家、大学问家，鲁迅对吃很讲究。","Zuòwéi dà zuòjiā, dà xuéwènjiā, Lǔ Xùn duì chī hěn jiǎngjiu.","Với tư cách là một đại văn hào, học giả lớn, Lỗ Tấn rất kỹ tính trong việc ăn uống."]],{"py": "zuòwéi","use": "Đứng đầu câu hoặc trước động từ.","note": "Phải đi cùng danh từ chỉ vai trò. Khác 当作 (xem như).","src": "file"}],["逐渐 / 逐步 (dần dần)","逐渐 + động từ / tính từ","逐渐 nói thay đổi từ từ theo thời gian, không đột ngột.",[["天色逐渐暗了下来，夜晚即将来临。","Tiānsè zhújiàn àn le xiàlái, yèwǎn jíjiāng láilín","Màu trời dần dần tối đi, đêm sắp đến."],["进入秋季，气温逐渐降低，树叶也开始变黄。","Jìnrù qiūjì, qìwēn zhújiàn jiàngdī, shùyè yě kāishǐ biàn huáng","Bước vào mùa thu, nhiệt độ dần hạ thấp, lá cây cũng bắt đầu chuyển vàng."]],{"py": "zhújiàn / zhúbù","use": "Đứng trước động từ hoặc tính từ chỉ biến đổi.","note": "Chỉ dùng với sự thay đổi, không dùng cho trạng thái cố định.","src": "file"}],["或许 (có lẽ)","或许 + động từ / câu","或许 nói phán đoán không chắc chắn, văn viết.",[["虽然以前她不支持你，但或许这次会有变化。","Suīrán yǐqián tā bù zhīchí nǐ, dàn huòxǔ zhè cì huì yǒu biànhuà","Mặc dù trước đây cô ấy không ủng hộ bạn, nhưng có lẽ lần này sẽ có thay đổi."],["或许正是因为这一点一滴的努力，你就会走在别人的前面。","Huòxǔ zhèng shì yīnwèi zhè yī diǎn yī dī de nǔlì, nǐ jiù huì zǒu zài biérén de qiánmiàn.","Có lẽ chính vì chút nỗ lực nhỏ nhoi này, bạn sẽ đi trước người khác."]],{"py": "huòxǔ","use": "Đứng trước vị ngữ hoặc đầu câu.","note": "Gần 也许, 可能; trang trọng hơn. Không dùng cùng 一定.","src": "file"}],["所 (cấu trúc 所 + động từ)","所 + động từ + 的 + danh từ","所 đứng trước động từ để biến cụm thành danh từ chỉ đối tượng của hành động.",[["这就是我所知道的全部情况。","Zhè jiùshì wǒ suǒ zhīdào de quánbù qíngkuàng","Đây chính là toàn bộ tình hình mà tôi biết."],["这所房子","zhè suǒ fángzi","Căn nhà này."]],{"py": "suǒ","use": "Văn viết: 所见所闻, 所学的知识.","note": "Không dùng cho động từ không có tân ngữ. 所 thường đi với 的.","src": "file"}],["相当 (khá, tương đối)","相当 + tính từ / động từ","相当 chỉ mức độ cao khá rõ, mạnh hơn 比较 nhưng nhẹ hơn 非常.",[["这种鸟一天所食的害虫相当于自己的体重。","Zhè zhǒng niǎo yī tiān suǒ shí de hàichóng xiāngdāng yú zìjǐ de tǐzhòng.","Loài chim này ăn số lượng côn trùng gây hại trong một ngày tương đương với trọng lượng cơ thể của nó."],["菜的味道好极了，服务也挺周到，我相当满意。","Cài de wèidào hǎo jíle, fúwù yě tǐng zhōudao, wǒ xiāngdāng mǎnyì","Món ăn ngon tuyệt vời, phục vụ cũng rất chu đáo, tôi khá hài lòng."]],{"py": "xiāngdāng","use": "Đứng trước tính từ hoặc động từ tâm lý.","note": "Có thể làm động từ nghĩa 'tương đương' (相当于).","src": "file"}],["所谓 (cái gọi là)","所谓 + khái niệm + 就是 / 是 ……","所谓 dùng để giải thích khái niệm hoặc mỉa mai, 'cái gọi là'.",[["他所谓的“新闻“，其实我们早就知道了。","Tā suǒwèi de “xīnwén“, qíshí wǒmen zǎo jiù zhīdàole.","Cái gọi là “tin tức” của anh ấy, thực ra chúng tôi đã biết từ lâu rồi."]],{"py": "suǒwèi","use": "Đứng đầu vế để định nghĩa.","note": "Khi dùng nghĩa định nghĩa thì vế sau thường là 就是 / 是.","src": "file"}],["迟早 (sớm muộn)","迟早 + 会 / 要 + động từ","迟早 nói việc chắc chắn sẽ xảy ra, chỉ là thời gian.",[["随着网络技术的发展，这些问题迟早都会得到解决。","Suízhe wǎngluò jìshù de fāzhǎn, zhèxiē wèntí chízǎo dōu huì dédào jiějué","Cùng với sự phát triển của công nghệ mạng, những vấn đề này sớm muộn gì cũng sẽ được giải quyết."]],{"py": "chízǎo","use": "Đứng trước 会, 要 hoặc động từ.","note": "Hay dùng cho dự đoán chắc chắn. Không dùng cho việc đã xảy ra.","src": "file"}],["再三 (nhiều lần)","再三 + 动词","再三 nhấn việc lặp lại nhiều lần, thường là cân nhắc, dặn dò, yêu cầu.",[["他考虑再三，最后还是客气地拒绝了。","Tā kǎolǜ zàisān, zuìhòu háishì kèqi de jùjuéle","Anh ấy suy nghĩ hết lần này đến lần khác, cuối cùng vẫn lịch sự từ chối."]],{"py": "zàisān","use": "Dùng trước động từ như 考虑, 强调, 要求, 劝.","note": "Cụm cố định, ít dùng với động từ khác. Không dùng cho việc lặp lại bình thường (dùng 又, 再).","src": "file"}],["极其 (vô cùng)","极其 + tính từ / động từ","极其 nhấn mức độ cực cao, trang trọng hơn 非常.",[["在中国，餐桌上放一把刀是极其少见的现象。","Zài Zhōngguó, cānzhuō shang fàng yī bǎ dāo shì jíqí shǎojiàn de xiànxiàng","Ở Trung Quốc, việc đặt dao trên bàn ăn là một hiện tượng cực kỳ hiếm thấy."]],{"py": "jíqí","use": "Đứng trước tính từ hoặc động từ.","note": "Văn viết, ít dùng trong hội thoại. Không dùng với 很 trước nó.","src": "file"}],["可见 (có thể thấy)","……，可见 + kết luận","可见 dùng để rút ra kết luận từ sự việc vừa nói.",[["他已经住院好几天了，一直诊断不出是什么问题，可见情况不太好。","Tā yǐjīng zhùyuàn hǎo jǐ tiānle, yīzhí zhěnduàn bù chū shì shénme wèntí, kějiàn qíngkuàng bú tài hǎo","Anh ấy đã nhập viện mấy ngày rồi, vẫn không chẩn đoán ra vấn đề gì, có thể thấy tình hình không được tốt lắm."]],{"py": "kějiàn","use": "Đứng đầu vế sau.","note": "Phải có căn cứ ở vế trước. Không dùng cho phỏng đoán không có cơ sở.","src": "file"}],["Bổ ngữ khả năng với 起 (V得起 / V不起)","động từ + 得起 / 不起","Nói có đủ khả năng (tiền, điều kiện) để làm việc gì hay không.",[["只有经得起困难和时间考验的朋友才算是真正的朋友。","Zhǐyǒu jīng de qǐ kùnnan hé shíjiān kǎoyàn de péngyǒu cái suàn shì zhēnzhèng de péngyǒu","Chỉ những người bạn vượt qua được thử thách của khó khăn và thời gian mới được coi là bạn bè thực sự."]],{"py": "V de qǐ / V bu qǐ","use": "Dùng với 买, 吃, 住, 看, 对不起.","note": "起 ở đây chỉ khả năng chi trả hoặc chịu được; không phải xu hướng 起来.","src": "file"}],["偶然 (tình cờ)","偶然 + động từ ; 很偶然","偶然 nói việc xảy ra tình cờ, không dự tính.",[["这次相遇完全是一个偶然的事件，谁也没有料到。","Zhè cì xiāngyù wánquán shì yī gè ǒurán de shìjiàn, shéi yě méiyǒu liàodào","Lần gặp gỡ này hoàn toàn là một sự kiện ngẫu nhiên, không ai ngờ tới cả."],["我昨天在超市偶然遇见了十年没见的老同学。","Wǒ zuótiān zài chāoshì ǒurán yùjiàn le shí nián méi jiàn de lǎo tóngxué","Hôm qua tôi tình cờ gặp một người bạn cũ đã mười năm không gặp ở siêu thị."]],{"py": "ǒurán","use": "Làm trạng ngữ hoặc tính từ (偶然的机会).","note": "Khác 偶尔 (thỉnh thoảng, HSK4). Không dùng cho việc lặp lại.","src": "file"}],["尽快 (càng sớm càng tốt)","尽快 + động từ","尽快 nói cố gắng làm trong thời gian sớm nhất.",[["我要抓紧时间尽快把《说文解字》电脑化。","Wǒ yào zhuājǐn shíjiān jǐnkuài bǎ 《Shuōwén Jiězì》 diànnǎo huà.","Tôi phải tranh thủ thời gian nhanh chóng máy tính hóa cuốn \"Thuyết văn giải tự\"."],["趁这两天天气好，您尽快把过季的衣服洗一洗，收起来。","Chèn zhè liǎng tiān tiānqì hǎo, nín jǐnkuài bǎ guò jì de yīfu xǐ yī xǐ, shōu qǐlái.","Tranh thủ hai hôm thời tiết đẹp này, bạn nhanh chóng giặt giũ và cất quần áo trái mùa đi."]],{"py": "jǐnkuài","use": "Đứng trước động từ, hay dùng trong yêu cầu.","note": "Không dùng cho hành động đã xảy ra. Có thể kèm 地.","src": "file"}],["某 (nào đó)","某 + (lượng từ) + danh từ","某 chỉ người hoặc sự vật không nêu rõ hoặc không cần nêu tên.",[["某些干部的工作作风存在问题。","Mǒu xiē gànbù de gōngzuò zuòfēng cúnzài wèntí","Tác phong làm việc của một số cán bộ nào đó tồn tại vấn đề."],["在某种程度上，我同意你的观点。","Zài mǒu zhǒng chéngdù shàng, wǒ tóngyì nǐ de guāndiǎn","Ở một mức độ nào đó, tôi đồng ý với quan điểm của bạn."]],{"py": "mǒu","use": "Đứng trước danh từ: 某人, 某天, 某个地方.","note": "Văn viết. Khác 有的 (một số). 某 chỉ một đối tượng.","src": "file"}],["幸亏 (may mà)","幸亏 + điều may mắn，不然 / 否则 + hậu quả","幸亏 nói may mắn nhờ điều kiện mà tránh được hậu quả xấu.",[["幸亏你提醒了我，我今天就去报名。","Xìngkuī nǐ tíxǐngle wǒ, wǒ jīntiān jiù qù bàomíng","May mà cậu nhắc tôi, hôm nay tôi sẽ đi đăng ký."]],{"py": "xìngkuī","use": "Đứng đầu vế đầu hoặc trước vị ngữ.","note": "Khác 多亏 (nhờ ơn ai). Hậu quả xấu ở vế sau thường đi với 不然, 否则.","src": "file"}],["朝 (hướng về)","朝 + hướng / người + động từ","朝 là giới từ chỉ hướng của hành động hoặc đối tượng hướng tới.",[["我们学校的正门坐西朝东。","Wǒmen xuéxiào de zhèng mén zuò xī cháo dōng","Cổng chính của trường chúng tôi tọa lạc phía Tây, hướng về phía Đông."],["使劲儿朝里面放水。","Shǐ jìnr cháo lǐmiàn fàng shuǐ","Dốc sức đổ nước vào bên trong."]],{"py": "cháo","use": "Đứng trước động từ, thường với 着, 向.","note": "Khác 往 (chỉ hướng di chuyển). 朝 còn dùng cho hướng mặt: 朝南.","src": "file"}],["总算 (rốt cuộc cũng)","总算 + động từ + (了)","总算 nói sau thời gian chờ đợi hoặc khó khăn, cuối cùng đã đạt được.",[["经过沟通，大导演总算搞明白了。","Jīngguò gōutōng, dà dǎoyǎn zǒngsuàn gǎo míngbáile","Sau khi trao đổi, đạo diễn lớn cuối cùng cũng đã hiểu ra."],["虽然我对这家宾馆不太满意，但总算有个睡觉的地方了。","Suīrán wǒ duì zhè jiā bīngguǎn bú tài mǎnyì, dàn zǒngsuàn yǒu gè shuìjiào de dìfāngle","Mặc dù tôi không hài lòng lắm với khách sạn này, nhưng dù sao cũng có chỗ để ngủ rồi."]],{"py": "zǒngsuàn","use": "Đứng trước động từ; thường có 了 ở cuối.","note": "Khác 终于 ở sắc thái nhẹ nhõm. Không dùng với kết quả xấu.","src": "file"}],["从此 (từ đó)","从此 + động từ / câu","从此 nói từ thời điểm ấy trở đi.",[["因为那场严重的误会，他们大吵了一架，从此两人的关系就疏远了。","Yīnwèi nà chǎng yánzhòng de wùhuì, tāmen dà chǎo le yī jià, cóngcǐ liǎng rén de guānxì jiù shūyuǎn le","Vì sự hiểu lầm nghiêm trọng đó, họ đã cãi nhau to, kể từ đó mối quan hệ của hai người trở nên xa cách."]],{"py": "cóngcǐ","use": "Đứng đầu vế sau hoặc trước vị ngữ.","note": "Chỉ dùng cho việc đã xảy ra trong quá khứ, hoặc truyện kể.","src": "file"}],["假设 / 假如 (giả sử)","假设 / 假如 + điều kiện，那么 / 就 + kết quả","Đặt một giả thiết rồi nêu kết quả.",[["假设我要从国贸到鼓楼大街，该怎么乘车？","Jiǎshè wǒ yào cóng Guómào dào Gǔlóu Dàjiē, gāi zěnme chéngchē?","Giả sử tôi muốn đi từ Quốc Mậu đến phố Cổ Lâu, nên đi xe như thế nào?"],["你当年的假设已经被证明是对的。","Nǐ dāngnián de jiǎshè yǐjīng bèi zhèngmíng shì duì de","Giả thiết năm đó của bạn đã được chứng minh là đúng."]],{"py": "jiǎshè / jiǎrú","use": "Đứng đầu vế điều kiện.","note": "Gần 如果 nhưng trang trọng hơn. Vế sau thường có 就 hoặc 那么.","src": "file"}],["的确 (quả thật)","的确 + 动词 / 形容词","的确 xác nhận sự thật, đồng tình hoặc nhấn mạnh điều đúng.",[["他的确我所教过的学生中最聪明的。","Tā díquè wǒ suǒ jiāoguò de xuésheng zhōng zuì cōngming de","Anh ấy quả thực là người thông minh nhất trong số những học sinh mà tôi từng dạy."]],{"py": "díquè","use": "Đứng trước vị ngữ.","note": "Gần 确实 (HSK4); 的确 trang trọng hơn một chút.","src": "file"}],["根本 (hoàn toàn, vốn dĩ)","根本 + 不 / 没 + động từ","根本 dùng trong phủ định, nhấn mạnh 'hoàn toàn không, chẳng hề'.",[["想学好汉语，单词是根本。","Xiǎng xué hǎo Hànyǔ, dāncí shì gēnběn","Muốn học tốt tiếng Hán, từ vựng là gốc rễ nền tảng."],["我们的根本目的是帮助大家学好中文。","Wǒmen de gēnběn mùdì shì bāngzhù dàjiā xué hǎo Zhōngwén","Mục đích cốt lõi chính của chúng tôi là giúp mọi người học tốt tiếng Trung."],["他根本没听你说话。","Tā gēnběn méi tīng nǐ shuōhuà","Anh ta hoàn toàn không nghe bạn nói."]],{"py": "gēnběn","use": "Đứng trước 不 / 没.","note": "Chỉ dùng với phủ định. Còn là tính từ: 根本问题 (vấn đề gốc rễ).","src": "file"}],["Bổ ngữ xu hướng 下来 / 下去","động từ + 下来 / 下去","下来 nói hành động tiến tới trạng thái ổn định hoặc từ trên xuống; 下去 nói tiếp tục.",[["你的论文大概什么时候发表？定下来了吗？","Nǐ de lùnwén dàgài shénme shíhou fābiǎo? Dìng xiàláile ma?","Luận văn của bạn khoảng khi nào công bố? Đã định xong chưa?"]],{"py": "xiàlái / xiàqù","use": "Dùng với 坐, 停, 安静, 说, 做.","note": "下来: tới trạng thái dừng/giữ lại. 下去: tiếp tục từ nay về sau.","src": "file"}],["靠 (dựa vào)","靠 + người / cách + động từ","靠 làm giới từ hoặc động từ, nói dựa vào ai hoặc điều gì để đạt kết quả; còn nghĩa tựa, sát.",[["王老师喜欢靠这桌子讲课。","Wáng lǎoshī xǐhuān kào zhè zhuōzi jiǎngkè.","Thầy Vương thích dựa vào bàn để giảng bài."],["在家靠父母，出门靠朋友。","Zài jiā kào fùmǔ, chūmén kào péngyǒu","Ở nhà dựa vào cha mẹ, ra ngoài dựa vào bạn bè."]],{"py": "kào","use": "Đứng trước động từ: 靠自己, 靠努力.","note": "Khác 依靠 (trang trọng hơn). Với nghĩa 'tựa vào' thì có tân ngữ chỉ vị trí.","src": "file"}],["勿 (đừng, chớ)","勿 + động từ","勿 là phủ định mệnh lệnh trong văn viết, biển báo, nghĩa 'đừng, cấm'.",[["非工作人员，请勿入内。","Fēi gōngzuò rényuán, qǐng wù rù nèi","Người không phận sự, xin đừng vào trong."],["网上购票者须注意网站的安全性，切勿上当受骗。","Wǎngshàng gòupiào zhě xū zhùyì wǎngzhàn de ānquán xìng, qiè wù shàngdàng shòupiàn","Người mua vé trực tuyến cần chú ý tính an toàn của trang web, chớ để bị lừa gạt."]],{"py": "wù","use": "Đứng trước động từ: 请勿吸烟, 切勿.","note": "Chỉ thấy trong thông báo, văn viết. Khẩu ngữ dùng 别, 不要.","src": "file"}],["分别 (lần lượt, riêng từng)","主语 + 分别 + 动词 + 宾语","分别 nói từng người hoặc từng bên làm việc khác nhau, tương ứng.",[["从毕业到现在我们已经分别 20 年了，一直都没有联系。","Cóng bìyè dào xiànzài wǒmen yǐjīng fēnbié èrshí nián le, yīzhí dōu méiyǒu liánxì","Từ khi tốt nghiệp đến nay chúng tôi đã chia tay 20 năm rồi, vẫn luôn không liên lạc."],["老师分别找我们谈了话，了解了每个人的想法。","Lǎoshī fēnbié zhǎo wǒmen tán le huà, liǎojiě le měi gè rén de xiǎngfǎ","Giáo viên đã lần lượt gặp riêng chúng tôi nói chuyện, để hiểu suy nghĩ của từng người."],["对消费者来说，这两个品牌的产品质量几乎没有什么分别。","Duì xiāofèizhě lái shuō, zhè liǎng gè pǐnpái de chǎnpǐn zhìliàng jīhū méiyǒu shénme fēnbié","Đối với người tiêu dùng, chất lượng sản phẩm của hai thương hiệu này hầu như không có sự khác biệt nào."]],{"py": "fēnbié","use": "Đứng trước động từ; chủ ngữ phải số nhiều.","note": "Còn là động từ 'chia tay'. Khác 各自: 分别 nhấn sự tương ứng từng cái một.","src": "file"}],["般 (như, giống như)","像 + A + 一般 / 似的","般 đứng cuối cụm để so sánh, nghĩa 'như, tựa như', văn viết.",[["望着爸爸远去的背景，我的眼泪雨点般不停地往下掉。","Wàngzhe bàba yuǎn qù de bèijǐng, wǒ de yǎnlèi yǔdiǎn bān bù tíng de wǎng xià diào","Nhìn bóng lưng bố đi xa, nước mắt tôi rơi xuống không ngừng như mưa."]],{"py": "bān","use": "Hay dùng 像……一般, 如……般.","note": "Phong cách văn chương, gần 似的 nhưng trang trọng hơn.","src": "file"}],["舍不得 (không nỡ)","舍不得 + động từ","舍不得 nói luyến tiếc, không nỡ rời xa hoặc chi tiêu.",[["把你最喜欢的玩具送给小朋友，你舍得吗？","Bǎ nǐ zuì xǐhuān de wánjù sòng gěi xiǎopéngyǒu, nǐ shědé ma?","Tặng món đồ chơi yêu thích nhất của bạn cho em bé, bạn có nỡ không?"]],{"py": "shěbude","use": "Đứng trước động từ: 舍不得走, 舍不得花钱.","note": "Đối lập với 舍得. Chữ 得 thanh nhẹ. Không dùng như 不能.","src": "file"}],["瞎 (bừa, vô ích)","瞎 + động từ","瞎 làm trạng ngữ nghĩa 'làm bừa, làm lung tung, không có căn cứ'.",[["你一定知道马的那只眼睛是瞎的。","Nǐ yīdìng zhīdào mǎ de nà zhǐ yǎnjīng shì xiā de.","Bạn nhất định biết con mắt nào của con ngựa đó bị mù."],["别听他瞎说！不用害怕，我们不会这么倒霉的。","Bié tīng tā xiāshuō! Bú yòng hàipà, wǒmen bú huì zhème dǎoméi de","Đừng nghe anh ta nói bừa! Không cần sợ hãi, chúng ta sẽ không xui xẻo như thế đâu."]],{"py": "xiā","use": "Đứng trước động từ: 瞎说, 瞎想, 瞎忙.","note": "Khẩu ngữ, mang sắc thái chê. Không dùng trong văn trang trọng.","src": "file"}],["时刻","时刻","Danh từ: Biểu thị ở một vài thời điểm hoặc một đoạn thời gian. Phó từ: Biểu thị ý nghĩa mỗi thời mỗi khắc, thường xuyên (có thể lặp lại là “时时刻刻”).",[["在最后时刻，他为本队踢进了赢得比赛的关键一球。","Zài zuìhòu shíkè, tā wèi běn duì tī jìnle yíngdé bǐsài de guānjiàn yī qiú","Vào thời khắc cuối cùng, anh ấy đã sút vào một quả bóng quan trọng giúp đội mình thắng trận."],["只要你愿意，公司的大门时刻都为你开着。","Zhǐyào nǐ yuànyì, gōngsī de dàmén shíkè dōu wèi nǐ kāizhe","Chỉ cần bạn đồng ý, cánh cửa công ty luôn luôn mở vì bạn."]],{"py": "Shíkè","use": "Loại từ: Danh từ/Phó từ","note": "","src": "file"}],["顶","顶","Danh từ: Chỉ bộ phận cao nhất của con người hoặc vật thể. Động từ: Biểu thị động tác của đầu, hoặc đón lấy, chống lại (áp lực). Lượng từ: Dùng cho mũ, ô hơi lớn, hoặc đồ vật có hình cái ô.",[["我们终于爬上了山顶，看到了美丽的日出。","Wǒmen zhōngyú pá shàng le shāndǐng, kàn dào le měilì de rìchū","Cuối cùng chúng tôi cũng leo lên được đỉnh núi, ngắm nhìn bình minh tuyệt đẹp."],["这根柱子顶着房梁。","Zhè gēn zhùzi dǐng zhe fángliáng","Cây cột này chống đỡ xà nhà."],["他戴着一顶红色的棒球帽。","Tā dài zhe yī dǐng hóngsè de bàngqiú mào","Anh ấy đội một cái mũ bóng chày màu đỏ."]],{"py": "Dǐng","use": "Loại từ: Danh từ/Động từ/Lượng từ","note": "","src": "file"}],["反而","A，B 反而 + ...","Kết quả trái với dự đoán thông thường: \"ngược lại, lại còn...\".",[["他平时话不多，但在辩论赛上反而成了最活跃的人。","Tā píngshí huà bù duō, dàn zài biànlùn sài shàng fǎn'ér chéng le zuì huóyuè de rén","Bình thường anh ấy ít nói, nhưng trong cuộc thi tranh luận lại trở thành người hoạt bát nhất."]],{"py": "fǎn'ér","use": "Kết quả trái với dự đoán thông thường: ngược lại, trái lại.","note": "Dùng sau một sự việc trái kỳ vọng. Không nhầm với 但是: 反而 nhấn kết quả trái ngược chứ không chỉ chuyển ý.","src": "file"}],["于 (HSK5)","于","Tương đương với “在、从、 对、向、比” (ở, từ, đối với, hướng về, so với).",[["这家公司成立于 1997 年。","Zhè jiā gōngsī chénglì yú yījiǔjiǔqī nián","Công ty này được thành lập từ năm 1997."],["这种药主要用于感冒的治疗。","Zhè zhǒng yào zhǔyào yòng yú gǎnmào de zhìliáo","Loại thuốc này chủ yếu dùng trong việc điều trị cảm cúm"]],{"py": "Yú","use": "Loại từ: Giới từ","note": "","src": "file"}],["为","为","Có nghĩa là “成、成为” (thành, trở thành) Có nghĩa là “作为、算作” (làm, coi như).",[["压力也可以变为动力。","Yālì yě kěyǐ biàn wéi dònglì.","Áp lực cũng có thể trở thành động lực"],["找工作时，很多人会以收入多少为第一标准。","Zhǎo gōngzuò shí, hěn duō rén huì yǐ shōurù duōshǎo wéi dì yī biāozhǔn","Khi tìm việc, nhiều người lấy mức thu nhập làm tiêu chuẩn đầu tiên."]],{"py": "Wéi","use": "Loại từ: Động từ","note": "","src": "file"}],["起来","起来","Dùng sau động từ: Biểu thị từ phân tán đến tập trung lại Biểu thị từ lộ rõ đến ẩn nấp, ẩn náu.",[["他把散落一地的玩具都捡起来放回了箱子里。","Tā bǎ sànluò yī dì de wánjù dōu jiǎn qǐlái fàng huí le xiāngzi lǐ","Cậu bé nhặt tất cả đồ chơi rơi vãi dưới đất lên và cất lại vào trong hộp."],["他把散落一地的玩具都捡起来放回了箱子里。","Tā bǎ sànluò yī dì de wánjù dōu jiǎn qǐlái fàng huí le xiāngzi lǐ","Cậu bé nhặt tất cả đồ chơi rơi vãi dưới đất lên và cất lại vào trong hộp."]],{"py": "Qǐlái","use": "Loại từ: Động từ xu hướng","note": "","src": "file"}],["根","根","Danh từ: Chỉ bộ phận của thực vật sinh trưởng dưới lòng đất, hoặc nền móng, cơ sở, gốc rễ của sự vật. Lượng từ: Thường dùng cho vật dài và nhỏ.",[["这件事还是得从根上解决，只理解表面问题是不行的。","Zhè jiàn shì háishì děi cóng gēn shang jiějué, zhǐ lǐjiě biǎomiàn wèntí shì bùxíng de","Việc này vẫn phải giải quyết từ gốc rễ, chỉ hiểu vấn đề bề mặt là không được."],["摸到尾巴的盲人说大相像一根绳子。","Mō dào wěibā de mángrén shuō dàxiàng xiàng yī gēn shéngzi.","Người mù sờ thấy cái đuôi nói con voi giống như một sợi dây."]],{"py": "Gēn","use": "Loại từ: Danh từ/Lượng từ","note": "","src": "file"}],["便","便","Nghĩa là 就 (“thì, là, đã”), thường dùng trong văn viết.",[["仅仅是换一种心情，换一个角度，便可以从困境中走出来。","Jǐnjǐn shì huàn yī zhǒng xīnqíng, huàn yīgè jiǎodù, biàn kěyǐ cóng kùnjìng zhōng zǒu chūlái","Chỉ cần thay đổi một chút tâm trạng, thay đổi một góc độ, là có thể bước ra khỏi hoàn cảnh khó khăn."]],{"py": "Biàn","use": "Loại từ: Phó từ","note": "","src": "file"}],["倒 (nghịch ý, nâng cao)","chủ ngữ + 倒 + tính từ / động từ","倒 biểu thị điều trái với dự kiến hoặc nhượng bộ nhẹ: lại, ngược lại, thế mà.",[["怎么勇敢反倒成为缺点了？","Shàonián bù jiě de wèn: “Zěnme yǒnggǎn fǎn dào chéngwéi quēdiǎnle","Tại sao dũng cảm ngược lại lại trở thành khuyết điểm?"],["小刘租的房子虽然很小，不过收拾得倒还干净。","Xiǎo Liú zū de fángzi suīrán hěn xiǎo, búguò shōushi dé dào hái gānjìng.","Căn nhà Tiểu Lưu thuê tuy rất nhỏ, nhưng dọn dẹp ngược lại vẫn còn sạch sẽ."]],{"py": "dào","use": "Đứng trước động từ hoặc tính từ trong vế sau.","note": "Không lẫn với 到 (dào, tới). 倒 mang sắc thái nhẹ nhàng, không như 却.","src": "file"}],["来Lái","来Lái","Dùng sau động từ (ví dụ: \"醒 \") biểu thị chuyển tiếp từ lúc ngủ đến lúc tỉnh, hoặc quay về trạng thái lúc ban đầu/bình thường. Có thể dùng trong cấu trúc phủ định (动词 + 得/不 + 过 来).",[["早晨醒来，我发现窗外正下着大雪。","Zǎochén xǐng lái, wǒ fāxiàn chuāng wài zhèng xiàzhe dà xuě","Buổi sáng thức dậy, tôi phát hiện bên ngoài cửa sổ đang tuyết rơi dày."],["脑子才清醒过来。","Nǎozi cái qīngxǐng guòlái.","Đầu óc mới tỉnh táo trở lại."]],{"py": "Lái","use": "Loại từ: Động từ xu hướng","note": "","src": "file"}],["数Shù","数Shù","Động từ (shǔ): Biểu thị tra, đếm (số lượng). Dùng trong cấu trúc “数······（最）······” hoặc “（最）······的（要/就）数 ······” biểu thị so sánh (nhất). Số từ (shù): Có nghĩa là “几/ 几个” (vài, mấy), thường dùng trong văn viết.",[["先生，这是找您的钱 58 块 6，您数数。","Xiānsheng, zhè shì zhǎo nín de qián wǔshíbā kuài liù, nín shǔ shǔ.","Thưa ngài, đây là tiền thối lại cho ngài 58 tệ 6, ngài đếm thử xem."],["要数我们班跑得最快的，那就数李阳了。","Yào shuō wǒmen bān pǎo de zuì kuài de, nà jiù shǔ Lǐ Yáng le","Nếu nói về người chạy nhanh nhất lớp chúng ta, thì phải kể đến Lý Dương."]],{"py": "Shǔ","use": "Loại từ: Động từ/Số từ","note": "","src": "file"}],["以及 (và, cũng như)","A、B 以及 C","以及 nối các thành phần danh từ, trang trọng hơn 和.",[["鉴于他在公司的突出贡献，董事会决定给予他丰厚的奖励.","Jiàn yú tā zài gōng sī de tū chū gòng xiàn, dǒng shì huì jué dìng gěi yǔ tā fēng hòu de jiǎng lì","Căn cứ vào những đóng góp nổi bật của anh ấy cho công ty, hội đồng quản trị quyết định trao cho anh ấy phần thưởng hậu hĩnh."]],{"py": "yǐjí","use": "Đứng trước thành phần cuối trong danh sách, hoặc nối hai nhóm.","note": "Chỉ nối danh từ hoặc cụm danh từ, không nối vế câu độc lập.","src": "file"}],["程度","程度","Chỉ trình độ, mức độ hoặc cấp độ mà ở một vài phương diện đã đạt được.",[["问题已经发展到了十分严重的程度。","Wèntí yǐjīng fāzhǎn dào le shífēn yánzhòng de chéngdù.","Vấn đề đã phát triển đến mức độ vô cùng nghiêm trọng."],["在很大程度上，一个人的未来取决于他所受的教育。","Zài hěn dà chéngdù shang, yīgè rén de wèilái qǔjué yú tā suǒ shòu de jiàoyù.","Ở mức độ rất lớn, tương lai của một người phụ thuộc vào nền giáo dục mà anh ta nhận được."]],{"py": "Chéngdù","use": "Loại từ: Danh từ","note": "","src": "file"}],["何必 (cần gì phải)","何必 + động từ","何必 là câu hỏi tu từ khuyên đừng làm điều không cần thiết.",[["你何必亲自送一趟呢？叫个快递不就行了？","Nǐ hébì qīnzì sòng yī tàng ne? Jiào gè kuàidì bú jiù xíngle","Cậu cần gì phải tự mình đi một chuyến? Gọi một người chuyển phát nhanh chẳng phải là được rồi sao?."]],{"py": "hébì","use": "Đứng trước động từ, thường kèm 呢 hoặc 呢.","note": "Mang sắc thái khuyên can hoặc trách nhẹ. Không dùng 何必 để hỏi thông tin.","src": "file"}],["则 (thì, còn)","A 则 B","则 dùng trong văn viết để nối hai vế đối lập hoặc điều kiện - kết quả.",[["一则新闻","yī zé xīnwén","Một mẩu tin (trên báo đài)."],["北方气候干燥，而南方则潮湿多雨。","Běifāng qìhòu gānzào, ér nánfāng zé cháoshī duō yǔ","Khí hậu miền Bắc khô ráo, còn miền Nam thì ẩm ướt mưa nhiều."],["物体受热，则体积膨胀。","Wùtǐ shòu rè, zé tǐjī péngzhàng","Vật thể khi nhận nhiệt, thì thể tích sẽ nở ra."]],{"py": "zé","use": "Đặt trước vế sau.","note": "Dùng trong văn viết trang trọng, ít dùng trong khẩu ngữ. Có thể thay bằng 就 hoặc 而.","src": "file"}],["为······所 ·····","为······所 ·····","Kết cấu cố định, thường dùng trong văn viết, trong đó “为” biểu thị ý nghĩa là “被” (bị/được).",[["大自然就可以更好地为人所用。","Dà zìrán jiù kěyǐ gèng hǎo de wéi rén suǒ yòng","Thiên nhiên có thể được con người sử dụng tốt hơn."]],{"py": "Wéi... Suǒ..","use": "Loại từ: Kết cấu cố định","note": "","src": "file"}],["起","起","Động từ (làm bổ ngữ), biểu thị sự liên tiếp, kết hợp và cố định.",[["最重要的是建立起一套行之有效的制度。","Zuì zhòngyào de shì jiànlì qǐ yī tào xíngzhīyǒuxiào de zhìdù","Điều quan trọng nhất là thiết lập một bộ chế độ có hiệu quả thực thi."]],{"py": "Qǐ","use": "Loại từ: Động từ","note": "","src": "file"}],["动词 + 过","动词 + 过","Dùng với cách thức “động từ + 得/不 + 过” làm bổ ngữ, biểu thị ý nghĩa là quá, vượt qua, hơn (thường dùng trong so sánh năng lực, trình độ).",[["跟别人谈论起军事来，没有人说得过他。","Gēn biérén tánlùn qǐ jūngshì lái, méiyǒu rén shuō de guò tā.","Khi bàn luận về quân sự với người khác, không ai nói hơn được anh ấy."],["产品在价格上肯定竞争不过他们。","Chǎnpǐn zài jiàgé shang kěndìng jìngzhēng bú guò tāmen.","Sản phẩm chắc chắn không thể cạnh tranh lại họ về giá cả."]],{"py": "Guò","use": "Loại từ: Động từ xu hướng","note": "","src": "file"}],["即","即","Động từ: Dùng trong văn viết, nghĩa là “就是” (tức là). Phó từ: Có nghĩa là “就” “便” (thì, ngay).",[["“旦”是象形字，即太阳从地平线上升起。","“Dàn” shì xiàngxíngzì, jí tàiyáng cóng dìpíngxiàn shang shēng qǐ","Chữ “旦” là chữ tượng hình, tức là mặt trời mọc từ đường chân trời."],["不懂即问是他最大的优点。","Bù dǒng jí wèn shì tā zuì dà de yōudiǎn","Không hiểu thì hỏi ngay là ưu điểm lớn nhất của anh ấy."]],{"py": "Jí","use": "Loại từ: Động từ/Phó từ","note": "","src": "file"}],["个别","个别","Có nghĩa là “单个，各个” (từng cái, mỗi cái). Biểu thị cực kỳ ít, hiếm có.",[["大部分同学都按时完成了作业，只有个别同学还需要一点时间。","Dà bùfèn tóngxué dōu ànshí wánchéng le zuòyè, zhǐyǒu gèbié tóngxué hái xūyào yīdiǎn shíjiān","Đa số các bạn học sinh đều hoàn thành bài tập đúng hạn, chỉ có một vài bạn cá biệt cần thêm chút thời gian."]],{"py": "Gèbié","use": "Loại từ: Tính từ","note": "","src": "file"}],["非……不可 (nhất định phải)","非 + động từ + 不可","非……不可 nhấn mạnh điều bắt buộc hoặc quyết tâm.",[["非机动车","Fēi jīdòngchē","Phi cơ giới Xe không có động cơ"],["此物非彼物，不可混淆。","Cǐ wù fēi bǐ wù, bùkě hùnxiáo","Vật này không phải vật kia, không thể lẫn lộn."],["他下定决心，非要考上那所名牌大学不可。","Tā xià dìng juéxīn, fēi yào kǎo shàng nà suǒ míngpái dàxué bùkě","Anh ấy quyết tâm, nhất định phải thi đỗ vào ngôi trường đại học danh tiếng đó mới thôi."]],{"py": "fēi … bùkě","use": "Có thể rút gọn 非得……不可 hoặc 非……不行.","note": "Không phủ định hai lần như tiếng Việt. Cũng dùng với 非得 nhấn mạnh.","src": "file"}],["以","以","Giới từ: Có nghĩa là “用、拿、 凭借” (dùng, lấy, dựa vào, nhờ vào). Liên từ: Biểu thị mục đích (\"để\").",[["我们应以客观的态度看待这个问题。","Wǒmen yīng yǐ kèguān de tàidù kàndài zhège wèntí","Chúng ta nên dùng lấy thái độ khách quan để nhìn nhận vấn đề này."],["公司决定扩大生产规模，以满足日益增长的市场需求。","Gōngsī juédìng kuòdà shēngchǎn guīmó, yǐ mǎnzú rìyì zēngzhǎng de shìchǎng xūqiú","Công ty quyết định mở rộng quy mô sản xuất, để đáp ứng nhu cầu thị trường ngày càng tăng."]],{"py": "Yǐ","use": "Loại từ: Giới từ/Liên từ","note": "","src": "file"}],["平常","平常","Tính từ: Biểu thị phổ thông, bình thường, không có gì đặc biệt Danh từ: Ý nghĩa là “平时” (ngày thường, lúc thường).",[["对小王来说，今天是一个不平常的日子。","Duì Xiǎo Wáng lái shuō, jīntiān shì yīgè bù píngcháng de rìzi","Đối với Tiểu Vương, hôm nay là một ngày không bình thường."],["他平常总是来得很早，今天却迟到了。","Tā píngcháng zǒng shì lái de hěn zǎo, jīntiān què chídàole","Anh ấy ngày thường luôn đến rất sớm, nhưng hôm nay lại đến muộn."]],{"py": "Píngcháng","use": "Loại từ: Tính từ/Danh từ","note": "","src": "file"}],["其余","其余","Biểu thị phần còn lại, bộ phận khác.",[["怎么只有你们两个人？其余的同学呢？","Zěnme zhǐyǒu nǐmen liǎng gè rén? Qíyú de tóngxué ne?","Sao chỉ có hai người các cậu? Những học sinh còn lại đâu?"]],{"py": "Qíyú","use": "Loại từ: Đại từ","note": "","src": "file"}],["闻","闻","Ngữ tố: Có nghĩa là \"nghe thấy hoặc tin tức, sự việc được nghe thấy\"/ Động từ: Biểu thị dùng mũi để cảm nhận, nhận biết mùi vị.",[["老话说：百闻不如一见。","Lǎo huà shuō: Bǎi wén bù rú yī jiàn.","Lời cổ nói: Trăm nghe không bằng một thấy."],["等能闻到香味时，便可开锅了。","Wén dào xiāngwèi shí, biàn kě kāi guō le.","Khi ngửi thấy mùi thơm, thì có thể mở nồi."]],{"py": "Wén","use": "Loại từ: Ngữ tố/Động từ","note": "","src": "file"}],["支","支","Động từ: Biểu thị dùng đồ vật chống cho vật thể không bị đổ xuống Lượng từ: Dùng trong tác phẩm âm nhạc, đội ngũ, hoặc đồ vật có hình cán (cây, bản).",[["他的两只手放在桌上，支着脑袋，正在想事情。","Tā de liǎng zhī shǒu fàng zài zhuō shang, zhīzhe nǎodai, zhèngzài xiǎng shìqíng","Hai tay anh ấy đặt trên bàn, chống cằm, đang suy nghĩ việc gì đó."],["他弹第二支曲子时引起了牛的注意。","Tā tán dì èr zhī qǔzi shí yǐnqǐle niú de zhùyì","Khi anh ấy chơi bản nhạc thứ hai đã thu hút sự chú ý của con bò."]],{"py": "Zhī","use": "Loại từ: Động từ/Lượng từ","note": "","src": "file"}],["硬","硬","Biểu thị kiên quyết hoặc cố chấp làm một việc gì đó. Biểu thị không đủ năng lực nhưng vẫn tiếp tục tận lực để làm một việc gì đó (\"cố gắng, cố chấp\").",[["医生让他休息，他硬要回去上班。","Yīshēng ràng tā xiūxi, tā yìng yào huíqù shàngbān","Bác sĩ bảo anh ấy nghỉ ngơi, anh ấy cứ đòi về đi làm."],["为了治病，他还是硬把它喝下去了。","Wèile zhì bìng, tā háishì yìng bǎ tā hē xiàqùle.","Mặc dù thuốc bắc hơi đắng, nhưng vì chữa bệnh, anh ấy vẫn cố gắng uống hết."]],{"py": "Yìng","use": "Loại từ: Phó từ","note": "","src": "file"}],["自从","自从","Biểu thị bắt đầu từ mốc thời gian nào đó trong quá khứ (\"kể từ khi\").",[["自从有了长大后成为作家这个理想之后，他每天都坚持写作。","Zìcóng yǒule zhǎng dà hòu chéngwéi zuòjiā zhège lǐxiǎng zhīhòu, tā měitiān dōu jiānchí xiězuò","Kể từ khi có lý tưởng lớn lên trở thành nhà văn, anh ấy mỗi ngày đều kiên trì viết lách."]],{"py": "Zìcóng","use": "Loại từ: Giới từ","note": "","src": "file"}],["一致","一致","Tính từ: Biểu thị không có sự chia rẽ, bất đồng. Phó từ: Biểu thị cùng nhau, đồng lòng.",[["文文跟他们的意见不一致。","Wénwén gēn tāmen de yìjiàn bù yīzhì","Ý kiến của Văn Văn không thống nhất với họ."],["双方一致表示将进一步发展友好合作关系。","Shuāngfāng yīzhì biǎoshì jiāng jìnyībù fāzhǎn yǒuhǎo hézuò guānxì","Hai bên nhất trí bày tỏ sẽ tiếp tục phát triển mối quan hệ hợp tác hữu nghị."]],{"py": "Yīzhì","use": "Loại từ: Tính từ/Phó từ","note": "","src": "file"}],["行动","行动","Động từ: Biểu thị đi lại, hoạt động cơ thể. Cũng có thể biểu thị tiến hành hành động nào đó vì mục đích nào đó. Danh từ: Biểu thị hoạt động, hành vi.",[["他运动时受伤了，行动不便。","Tā yùndòng shí shòushāngle, xíngdòng bú biàn","Anh ấy bị thương khi tập thể thao, đi lại bất tiện."],["我们应该勇敢面对困难，迅速采取行动。","Wǒmen yīnggāi yǒnggǎn miànduì kùnnan, xùnsù cǎiqǔ xíngdòng.","Chúng ta nên dũng cảm đối mặt với khó khăn, nhanh chóng hành động."]],{"py": "Xíngdòng","use": "Loại từ: Động từ/Danh từ","note": "","src": "file"}],["义务","义务","Danh từ: Biểu thị trách nhiệm về mặt pháp luật, đạo đức nên gánh vác, đảm nhiệm (\"nghĩa vụ\"). Tính từ: Biểu thị không nhận thù lao (mang tính nghĩa vụ).",[["中国有关于九年制义务教育的法律。","Zhōngguó yǒu guānyú jiǔ nián zhì yìwù jiàoyù de fǎlǜ","Trung Quốc có luật về giáo dục bắt buộc 9 năm"],["参与社会事务和促进社会进步是每个人的权利，也是每个人的义务和责任。","Cānyù shèhuì shìwù hé cùjìn shèhuì jìnbù shì měi gèrén de quánlì, yě shì měi gèrén de yìwù hé zérèn","Tham gia công việc xã hội và thúc đẩy tiến bộ xã hội là quyền lợi của mỗi người, cũng là nghĩa vụ và trách nhiệm của mỗi người."]],{"py": "Yìwù","use": "Loại từ: Danh từ/Tính từ","note": "","src": "file"}],["来","来","Đứng sau các từ chỉ số “十、 百、千”... hoặc từ chỉ số lượng, biểu thị ước lượng (\"khoảng hơn\"). Dùng sau các từ chỉ số như “一、二、三” tạo thành kết cấu “一来······，二来······” biểu thị liệt kê lí do (\"một là... hai là...\").",[["他雇了 20 来个当地人为他带路和搬运行李。","Tā gùle èrshí lái gè dāngdì rén wèi tā dàilù hé bānyùn xíngli.","Anh ấy đã thuê khoảng hơn 20 người địa phương dẫn đường và khuân vác hành lý cho anh ấy."],["一来是给大家送水果，二来是看看大家过节还有什么难处。","Yī lái shì gěi dàjiā sòng shuǐguǒ, èr lái shì kàn kàn dàjiā guòjié hái yǒu shénme nán chu","Một là để mang trái cây đến cho mọi người, hai là để xem mọi người đón lễ còn khó khăn gì không."]],{"py": "Lái","use": "Loại từ: Trợ từ","note": "","src": "file"}],["堆","堆","Lượng từ: Dùng cho đám người hoặc đống đồ vật. Động từ: Biểu thị dùng tay hoặc dụng cụ để xếp, chất lên nhau. Danh từ: Biểu thị đồ vật xếp cùng nhau.",[["门口放着好几堆刚送来的货物，还没整理。","Ménkǒu fàng zhe hǎo jǐ duī gāng sòng lái de huòwù, hái méi zhěnglǐ.","Ở cửa đặt mấy đống hàng hóa vừa mới gửi đến, vẫn chưa được sắp xếp."],["快把房间里的玩具堆到一起，太乱了。","Kuài bǎ fángjiān lǐ de wánjù duī dào yīqǐ, tài luàn le","Mau chất xếp đồ chơi trong phòng lại thành một đống đi, bừa bộn quá."],["墙角有一堆废弃的纸箱。","Qiángjiǎo yǒu yī duī fèiqì de zhǐxiāng","Ở góc tường có một đống thùng carton bỏ đi."]],{"py": "Duī","use": "Loại từ: Lượng từ/Động từ/Danh từ","note": "","src": "file"}],["无意","无意","Động từ: Có nghĩa là không muốn, không có ý định..",[["我无意打扰您，不过我可以跟您谈一会儿吗？","Wǒ wúyì dǎrǎo nín, búguò wǒ kěyǐ gēn nín tán yīhuǐ'er ma?","Tôi không có ý định làm phiền ngài, nhưng tôi có thể nói chuyện với ngài một lát được không?."]],{"py": "Wúyì","use": "Loại từ: Động từ","note": "","src": "file"}],["有利","有利","Có nghĩa là có lợi, có ích (thường dùng “有利于” để biểu thị có lợi cho người hoặc vật nào đó).",[["高高的个子，漂亮的外表，都是他的有利条件。","Gāo gāo de gèzi, piàoliang de wàibiǎo, dōu shì tā de yǒulì tiáojiàn.","Chiều cao nổi bật, vẻ ngoài xinh đẹp, đều là những điều kiện có lợi của anh ấy."]],{"py": "Yǒulì","use": "Loại từ: Tính từ","note": "","src": "file"}],["嗯 (Ńg","嗯 (Ńg","Biểu thị nghi vấn. Biểu thị đáp ứng hoặc chấp thuận.",[["嗯？不是 28 号，难道是我记错了？","Ńg? Bú shì èrshíbā hào, nándào shì wǒ jì cuòle?","Hả? Không phải ngày 28, chẳng lẽ tôi nhớ nhầm rồi?."],["嗯，如果您心情好，我就说件事。","Ǹg, rúguǒ nín xīnqíng hǎo, wǒ jiù shuō jiàn shì","Ừm, nếu ngài đang có tâm trạng tốt, tôi sẽ nói một việc."]],{"py": "Ǹg)","use": "Loại từ: Thán từ","note": "","src": "file"}],["轻易","轻易","Tính từ: đơn giản, dễ dàng Phó từ: Biểu thị thái độ khi xử lí công việc không cẩn thận, rất tùy tiện. Thường dùng trong câu phủ định (“轻 易不·····” nghĩa là “rất ít làm”).",[["假，就这样轻易地请好了。","Jiǎ, jiù zhèyàng qīngyì de qǐng hǎole.","Xin nghỉ phép cứ thế dễ dàng được chấp thuận"],["他为人好强，轻易不求人。","Tā wéirén hàoqiáng, qīngyì bù qiú rén","Anh ấy là người tự cường, không dễ dàng nhờ vả người khác."]],{"py": "Qīngyì","use": "Loại từ: Tính từ/Phó từ","note": "","src": "file"}],["密切","密切","Tính từ: Biểu thị quan hệ gần gũi, mật thiết. Động từ: Có nghĩa làm cho quan hệ trở nên gần gũi mật thiết hơn.",[["多年来，两国一直保持着密切的友好关系。","Duō nián lái, liǎng guó yīzhí bǎochí zhe mìqiè de yǒuhǎo guānxì","Trong nhiều năm qua, hai nước vẫn luôn duy trì mối quan hệ hữu nghị mật thiết."],["双方领导人同意密切各领域的合作。","Shuāngfāng lǐngdǎo rén tóngyì mìqiè gè lǐngyù de hézuò","Lãnh đạo hai bên đồng ý tăng cường thắt chặt hợp tác trên các lĩnh vực."]],{"py": "Mìqiè","use": "Loại từ: Tính từ/Động từ","note": "","src": "file"}],["逐步","逐步","Biểu thị từng bước từng bước một (thường dùng trong những tình huống do con người làm ra).",[["调整能源消费结构，逐步向可再生能源转变。","Tiáozhěng néngyuán xiāofèi jiégòu, zhúbù xiàng kě zàishēng néngyuán zhuǎnbiàn.","Điều chỉnh cơ cấu tiêu thụ năng lượng, từng bước chuyển đổi sang năng lượng tái tạo."]],{"py": "Zhúbù","use": "Loại từ: Phó từ","note": "","src": "file"}],["照常","照常","Động từ: Có nghĩa là giống như bình thường Phó từ: Biểu thị tình huống tiếp tục không thay đổi (\"như thường lệ\").",[["这里的日常生活，一切照常。","Zhèlǐ de rìcháng shēnghuó, yīqiè zhàocháng","Cuộc sống hàng ngày ở đây, mọi thứ vẫn như thường lệ."],["在东方广场的迎新活动照常举行。","Zài Dōngfāng Guǎngchǎng de yíngxīn huódòng zhàocháng jǔxíng","Hoạt động đón năm mới tại quảng trường Đông Phương vẫn được tổ chức như thường lệ."]],{"py": "Zhàochán g","use": "Loại từ: Động từ/Phó từ","note": "","src": "file"}],["过","过","Biểu thị người hoặc vật thể thông qua động tác để thay đổi phương hướng hoặc di chuyển vị trí.",[["他转过身，一句话也不说。","Tā zhuǎn guò shēn, yī jù huà yě bù shuō","Anh ấy quay người lại, không nói một lời nào."]],{"py": "Guò","use": "Loại từ: Bổ ngữ xu hướng","note": "","src": "file"}],["开","开","Biểu thị mở ra, giãn ra.",[["请你让开一下，我要过去。","Qǐng nǐ ràng kāi yīxià, wǒ yào guòqù","Làm ơn tránh tránh ra một chút, tôi cần đi qua."]],{"py": "Kāi","use": "Loại từ: Bổ ngữ xu hướng","note": "","src": "file"}],["赶快","赶快","Ý nghĩa là bắt kịp thời gian, gia tăng tốc độ).",[["我下个月要搬家，得赶快找房子。","Wǒ xià gè yuè yào bānjiā, děi gǎnkuài zhǎo fángzi","Tháng sau tôi phải chuyển nhà, phải nhanh chóng tìm nhà."]],{"py": "Gǎnkuài","use": "Loại từ: Phó từ","note": "","src": "file"}],["片","片","Danh từ: Đồ vật có bề mặt phẳng, mỏng, thường không quá lớn Lượng từ: Dùng để chỉ những đồ vật thành phiến, cũng có thể dùng với âm thanh, cảnh sắc.",[["瓶子里装着满满的石头、玻璃碎片和沙子。","Píngzi lǐ zhuāngzhe mǎnmǎn de shítou, bōli suìpiàn hé shāzi","Trong chai đựng đầy đá, mảnh thủy tinh và cát."],["同学们听了，发出一片热烈的欢呼声。","Tóngxuémen tīngle, fā chū yī piàn rèliè de huānhū shēng","Các bạn học sinh nghe xong, phát ra một tràng tiếng reo hò nhiệt liệt."]],{"py": "Piàn","use": "Loại từ: Danh từ/Lượng từ","note": "","src": "file"}],["除非 (trừ phi)","除非 + điều kiện，否则 / 才 + kết quả","除非 nêu điều kiện duy nhất để một việc xảy ra; 否则 nêu hậu quả nếu không có điều kiện đó.",[["除非明天下大雨，否则比赛照常进行。","Chúfēi míngtiān xià dàyǔ, fǒuzé bǐsài zhàocháng jìnxíng","Trừ phi ngày mai trời mưa to, nếu không thì trận đấu vẫn diễn ra như thường lệ."],["这种机器，除非李阳，没人修得好。","Zhè zhǒng jīqì, chúfēi Lǐ Yáng, méi rén xiū de hǎo","Loại máy này, trừ Lý Dương ra, không ai sửa được."]],{"py": "chúfēi","use": "Hay đi với 才 hoặc 否则/不然.","note": "Không dùng 就 trong cấu trúc này. 除非 và 才 cùng dùng thì nhấn điều kiện duy nhất.","src": "file"}],["直","直","Dùng để diễn tả hành động diễn ra liên tục, không bị gián đoạn, thường đứng trước động từ đơn âm tiết. Nhấn mạnh một hành động kéo dài, lặp đi lặp lại hoặc làm hoài không nghỉ.",[["这趟车可以直达北京，非常方便。","Zhè tàng chē kěyǐ zhídá Běijīng, fēicháng fāngbiàn","Chuyến xe này có thể đi thẳng đến Bắc Kinh, rất tiện lợi."]],{"py": "Zhí","use": "Loại từ: Phó từ","note": "","src": "file"}]],"6": [["之所以……是因为……","之所以 A，是因为 B","Nhấn mạnh kết quả A trước, rồi giải thích nguyên nhân B: \"sở dĩ... là vì...\".",[["他之所以迟到，是因为路上堵车。","Tā zhī suǒyǐ chídào, shì yīnwèi lùshang dǔchē.","Sở dĩ anh ấy đến muộn là vì đường kẹt xe."],["我之所以选择这个专业，是因为我喜欢它。","Wǒ zhī suǒyǐ xuǎnzé zhège zhuānyè, shì yīnwèi wǒ xǐhuan tā.","Sở dĩ tôi chọn ngành này là vì tôi thích nó."]],{"py": "zhī suǒyǐ … shì yīnwèi …","use": "Nhấn mạnh kết quả trước, giải thích nguyên nhân sau: sở dĩ … là vì …","note": "Vế sau 是因为 là phần quan trọng. Không dùng 所以 trong cấu trúc này."}],["与其说……不如说……","与其说 A，不如说 B","Dùng để đính chính cách nhìn: nói là A thì chi bằng nói là B (chính xác hơn).",[["与其说他聪明，不如说他勤奋。","Yǔqí shuō tā cōngming, bùrú shuō tā qínfèn.","Nói anh ấy thông minh, chi bằng nói anh ấy chăm chỉ."],["与其说这是工作，不如说这是爱好。","Yǔqí shuō zhè shì gōngzuò, bùrú shuō zhè shì àihào.","Nói đây là công việc, chi bằng nói đây là sở thích."]],{"py": "yǔqí shuō … bùrú shuō …","use": "Đánh giá lại tính chất: nói A thà nói B còn chính xác hơn.","note": "Khác 与其……不如……: ở đây chỉ so sánh cách nói, không phải chọn lựa hành động."}],["以免","A，以免 B","Hành động A để tránh kết quả xấu B: \"để tránh, kẻo\".",[["他向来以严谨细致著称，在科研领域从不马虎.","Tā xiàng lái yǐ yán jǐn xì zhì zhù chēng, zài kē yán lǐng yù cóng bù mǎ hǔ","Anh ấy trước nay nổi tiếng là nghiêm túc và tỉ mỉ, không bao giờ qua loa trong lĩnh vực nghiên cứu khoa học."]],{"py": "yǐmiǎn","use": "Nêu mục đích tránh một điều không tốt: để khỏi, kẻo.","note": "Dùng đầu vế sau; vế trước là hành động phòng ngừa. Không dùng cho mục đích tích cực.","src": "file"}],["足足 (đủ, trọn)","足足 + số lượng","足足 nhấn mạnh số lượng hoặc thời gian đủ hoặc nhiều hơn mong đợi.",[["我足足等了他两个小时。","Wǒ zúzú děng le tā liǎng ge xiǎoshí.","Tôi đã đợi anh ấy trọn hai tiếng."],["这个箱子足足有二十公斤。","Zhège xiāngzi zúzú yǒu èrshí gōngjīn.","Cái thùng này nặng đủ hai mươi cân."]],{"py": "zúzú","use": "Đứng trước số lượng hoặc thời gian.","note": "Chỉ dùng với số lượng thực tế đạt tới. Không dùng với phủ định."}],["向来 (xưa nay)","向来 + động từ / tính từ","向来 nói tính chất hoặc thói quen kéo dài từ trước đến nay.",[["他做事向来认真。","Tā zuò shì xiànglái rènzhēn.","Anh ấy làm việc xưa nay luôn nghiêm túc."],["我们这里向来不下雪。","Wǒmen zhèlǐ xiànglái bú xià xuě.","Chỗ chúng tôi xưa nay không có tuyết."]],{"py": "xiànglái","use": "Dùng cả khẳng định lẫn phủ định.","note": "Gần 一向 nhưng trang trọng hơn. Không dùng với việc chỉ xảy ra một lần."}],["果然 (quả nhiên)","果然 + kết quả","果然 nói sự việc diễn ra đúng như dự đoán.",[["我说他会来，他果然来了。","Wǒ shuō tā huì lái, tā guǒrán lái le.","Tôi bảo anh ấy sẽ đến, quả nhiên anh ấy đến."],["天气预报说有雨，果然下雨了。","Tiānqì yùbào shuō yǒu yǔ, guǒrán xià yǔ le.","Dự báo bảo có mưa, quả nhiên trời mưa."]],{"py": "guǒrán","use": "Đứng trước vị ngữ hoặc đầu vế sau.","note": "Dùng cho việc đã xác nhận đúng dự đoán. Nếu sự việc ngoài dự đoán dùng 竟然."}],["似乎 (dường như)","似乎 + phán đoán","似乎 nêu phán đoán không chắc chắn, văn viết hơn 好像.",[["他似乎不太高兴。","Tā sìhū bú tài gāoxìng.","Anh ấy dường như không vui lắm."],["这件事似乎没那么简单。","Zhè jiàn shì sìhū méi nàme jiǎndān.","Việc này dường như không đơn giản như vậy."]],{"py": "sìhū","use": "Đứng trước động từ hoặc đầu câu.","note": "Không dùng cho điều đã rõ ràng. Có thể kèm 是 hoặc 有."}],["凡是……都…… (hễ là … đều …)","凡是 + phạm vi，都 + kết quả","Nói về quy tắc chung áp dụng cho mọi trường hợp trong phạm vi.",[["凡是来过的人，都说这里很美。","Fánshì lái guo de rén, dōu shuō zhèlǐ hěn měi.","Hễ là người đã đến, đều nói ở đây rất đẹp."],["凡是学生都可以免费参加。","Fánshì xuésheng dōu kěyǐ miǎnfèi cānjiā.","Hễ là học sinh đều có thể tham gia miễn phí."]],{"py": "fánshì … dōu …","use": "Vế sau bắt buộc có 都 hoặc 一律.","note": "Dùng cho quy định hoặc nhận xét chung. Không dùng cho trường hợp cá biệt."}],["偏偏 (cứ đúng lúc, nhất định)","偏偏 + động từ","偏偏 nói hành động trái ý hoặc xảy ra đúng lúc không thuận lợi.",[["我要出门，偏偏下起雨来了。","Wǒ yào chūmén, piānpiān xià qǐ yǔ lái le.","Tôi vừa định ra ngoài thì trời lại mưa."],["别人都同意，他偏偏不同意。","Biérén dōu tóngyì, tā piānpiān bù tóngyì.","Mọi người đều đồng ý, riêng anh ấy lại không."]],{"py": "piānpiān","use": "Đứng trước động từ.","note": "Mang sắc thái bực bội hoặc ngạc nhiên. Không dùng với kết quả thuận lợi."}],["一律 (nhất loạt)","一律 + động từ","一律 nói tất cả đều theo cùng một quy định, không ngoại lệ.",[["进入场馆的人一律要戴口罩。","Jìnrù chǎngguǎn de rén yílǜ yào dài kǒuzhào.","Tất cả mọi người vào địa điểm đều phải đeo khẩu trang."],["所有商品一律八折。","Suǒyǒu shāngpǐn yílǜ bā zhé.","Tất cả hàng hóa đều giảm hai mươi phần trăm."]],{"py": "yílǜ","use": "Đứng trước động từ, thường dùng trong quy định.","note": "Dùng cho quy tắc hoặc quy định chính thức, khác 都 (chỉ tổng thể)."}],["无非 (chẳng qua là)","无非 + 是 + …","无非 nói điều gì chẳng qua chỉ là như thế, không ngoài.",[["他这样做，无非是想引起注意。","Tā zhèyàng zuò, wúfēi shì xiǎng yǐnqǐ zhùyì.","Anh ấy làm vậy chẳng qua là muốn gây chú ý."],["他们吵架无非是为了一点儿小事。","Tāmen chǎo jià wúfēi shì wèile yìdiǎnr xiǎoshì.","Họ cãi nhau chẳng qua chỉ vì chuyện nhỏ."]],{"py": "wúfēi","use": "Đứng trước 是 hoặc động từ.","note": "Mang giọng xem nhẹ. Không dùng trong tình huống trang trọng đòi hỏi chính xác."}],["到时候 (đến lúc đó)","到时候 + câu","到时候 nói một thời điểm trong tương lai sẽ đến.",[["先别担心，到时候再说吧。","Xiān bié dānxīn, dào shíhou zài shuō ba.","Đừng lo trước, đến lúc đó rồi tính."],["你来的时候告诉我，到时候我去接你。","Nǐ lái de shíhou gàosu wǒ, dào shíhou wǒ qù jiē nǐ.","Khi nào bạn đến thì báo tôi, lúc đó tôi ra đón."]],{"py": "dào shíhou","use": "Đứng đầu vế sau.","note": "Chỉ dùng cho tương lai, thường đi với 再 hoặc 就 ở vế sau."}],["Hậu tố 性 (tính)","danh từ / tính từ / động từ + 性","性 tạo danh từ chỉ tính chất: 重要性, 积极性.",[["学习的积极性很重要。","Xuéxí de jījíxìng hěn zhòngyào.","Tính tích cực trong học tập rất quan trọng."],["这个计划有很强的可行性。","Zhège jìhuà yǒu hěn qiáng de kěxíngxìng.","Kế hoạch này có tính khả thi rất cao."]],{"py": "xìng","use": "Đứng sau từ gốc.","note": "Không dùng 性 sau mọi từ. Phải theo từ ghép cố định."}],["之 (của, trợ từ văn ngôn)","A 之 B","之 là trợ từ văn viết nối định ngữ với danh từ, tương đương 的.",[["他们之间有很深的感情。","Tāmen zhī jiān yǒu hěn shēn de gǎnqíng.","Giữa họ có tình cảm rất sâu đậm."],["两国之间的关系越来越好。","Liǎng guó zhī jiān de guānxì yuè lái yuè hǎo.","Quan hệ giữa hai nước ngày càng tốt đẹp."]],{"py": "zhī","use": "Thường gặp trong thành ngữ và từ ghép cố định.","note": "Không dùng 之 thay 的 trong khẩu ngữ. Gặp trong 之间, 之后, 之前."}],["嘛 (mà, rõ ràng)","câu + 嘛","嘛 cuối câu nhấn điều hiển nhiên hoặc nài nỉ nhẹ.",[["这么简单的事，你自己做嘛。","Zhème jiǎndān de shì, nǐ zìjǐ zuò ma.","Việc đơn giản thế này, bạn tự làm đi mà."],["我早就告诉你了嘛。","Wǒ zǎo jiù gàosu nǐ le ma.","Tôi đã bảo bạn từ lâu rồi mà."]],{"py": "ma","use": "Dùng khẩu ngữ, giọng thân mật.","note": "Không dùng 嘛 trong văn viết. Không nhầm với 吗 (câu hỏi)."}],["……与否 (có hay không)","A 与否","与否 đặt sau danh từ hoặc động từ để nói 'có hay không'.",[["成功与否，取决于你的努力。","Chénggōng yǔfǒu, qǔjué yú nǐ de nǔlì.","Thành công hay không tùy thuộc vào nỗ lực của bạn."],["参加与否，请尽快回复。","Cānjiā yǔfǒu, qǐng jǐnkuài huífù.","Tham gia hay không, xin trả lời sớm."]],{"py": "yǔfǒu","use": "Dùng trong văn viết, đứng cuối cụm.","note": "Không dùng trong khẩu ngữ thân mật. Thường đi sau từ như 成功, 参加."}],["鉴于 (xét thấy)","鉴于 + tình hình，……","鉴于 nêu căn cứ để đưa ra quyết định hoặc kết luận.",[["鉴于目前的情况，我们决定推迟会议。","Jiànyú mùqián de qíngkuàng, wǒmen juédìng tuīchí huìyì.","Xét tình hình hiện nay, chúng tôi quyết định hoãn cuộc họp."],["鉴于天气原因，航班取消了。","Jiànyú tiānqì yuányīn, hángbān qǔxiāo le.","Xét về nguyên nhân thời tiết, chuyến bay bị hủy."]],{"py": "jiànyú","use": "Đứng đầu câu, vế sau nêu kết luận.","note": "Văn viết trang trọng, không dùng trong khẩu ngữ."}],["岂不是 (chẳng phải là…)","岂不是 + khẳng định ?","岂不是 là câu hỏi tu từ nhấn mạnh khẳng định.",[["这样做，岂不是浪费时间吗？","Zhèyàng zuò, qǐ bú shì làngfèi shíjiān ma?","Làm như vậy chẳng phải là lãng phí thời gian sao?"],["你不去，岂不是错过机会了？","Nǐ bú qù, qǐ bú shì cuòguò jīhuì le?","Bạn không đi, chẳng phải là bỏ lỡ cơ hội sao?"]],{"py": "qǐ bú shì","use": "Đặt trước 是 hoặc động từ, cuối câu thường có 吗 / 呢.","note": "Chỉ dùng như câu hỏi tu từ. Không dùng để hỏi thông tin."}],["兼 (kiêm)","A 兼 B","兼 nói một người hoặc vật vừa đảm nhiệm A vừa B.",[["他是老师兼翻译。","Tā shì lǎoshī jiān fānyì.","Anh ấy vừa là giáo viên vừa là phiên dịch."],["这个房间是客厅兼书房。","Zhège fángjiān shì kètīng jiān shūfáng.","Căn phòng này vừa là phòng khách vừa là phòng sách."]],{"py": "jiān","use": "Đứng giữa hai chức năng hoặc vai trò.","note": "Văn viết, dùng với nghề nghiệp hoặc chức vụ."}],["由此 (từ đó)","由此 + động từ","由此 nói từ điều vừa nêu mà suy ra hoặc đạt được điều gì đó.",[["他每天坚持练习，由此可见他很努力。","Tā měitiān jiānchí liànxí, yóucǐ kějiàn tā hěn nǔlì.","Anh ấy kiên trì luyện tập mỗi ngày, từ đó thấy anh ấy rất cố gắng."],["由此我们可以得出一个结论。","Yóucǐ wǒmen kěyǐ déchū yí ge jiélùn.","Từ đó chúng ta có thể rút ra một kết luận."]],{"py": "yóucǐ","use": "Đứng đầu vế sau.","note": "Dùng trong văn viết. Thường theo sau là 可见, 看出, 得出."}],["莫过于 (không gì bằng)","最 + tính từ + 的 + 莫过于 + …","莫过于 nói điều gì đó là nhất, không gì sánh bằng.",[["人生最大的幸福莫过于家人平安。","Rénshēng zuì dà de xìngfú mòguòyú jiārén píng'ān.","Hạnh phúc lớn nhất trong đời không gì bằng người thân bình an."],["最痛苦的事莫过于失去亲人。","Zuì tòngkǔ de shì mòguòyú shīqù qīnrén.","Điều đau khổ nhất không gì bằng mất người thân."]],{"py": "mòguòyú","use": "Văn viết, dùng với 最.","note": "Không dùng trong khẩu ngữ. Cần đi cùng 最."}],["不愧 (xứng đáng)","不愧 + (是) + danh hiệu","不愧 nói khen ai xứng đáng với danh tiếng hoặc vai trò.",[["他不愧是个好老师。","Tā búkuì shì ge hǎo lǎoshī.","Anh ấy xứng đáng là một người thầy tốt."],["你真不愧是冠军！","Nǐ zhēn búkuì shì guànjūn!","Bạn đúng là xứng đáng làm nhà vô địch!"]],{"py": "búkuì","use": "Đứng trước 是 hoặc danh từ.","note": "Dùng để khen. Không dùng với nghĩa tiêu cực."}],["一来……二来……","一来 + lý do 1，二来 + lý do 2","Nêu hai lý do hoặc mục đích song song.",[["我去北京，一来看朋友，二来学汉语。","Wǒ qù Běijīng, yī lái kàn péngyou, èr lái xué Hànyǔ.","Tôi đi Bắc Kinh, một là thăm bạn, hai là học tiếng Trung."],["他不想去，一来太远，二来没有时间。","Tā bù xiǎng qù, yī lái tài yuǎn, èr lái méiyǒu shíjiān.","Anh ấy không muốn đi, một là quá xa, hai là không có thời gian."]],{"py": "yī lái … èr lái …","use": "Đứng đầu hai vế; vế sau thêm 还 để nhấn.","note": "Dùng cho lý do. Không đảo thứ tự một và hai."}],["巴不得","巴不得","Động từ biểu thị ý rất mong muốn hoặc cực kỳ hy vọng điều gì đó xảy ra, thường dùng trong khẩu ngữ.",[["在这种竞争激烈的环境中，他巴不得能找到一份安稳的工作，养家糊口.","Zài zhè zhǒng jìng zhēng jī liè de huán jìng zhōng, tā bā bù dé néng zhǎo dào yī fèn ān wěn de gōng zuò, yǎng jiā hú kǒu","Trong môi trường cạnh tranh khốc liệt này, anh ấy chỉ mong tìm được một công việc ổn định để nuôi sống gia đình."]],{"py": "bā bù dé","use": "","note": "","src": "file"}],["别提多……了","别提多……了","Cụm từ biểu thị mức độ rất cao của tính chất nào đó, thường mang sắc thái cường điệu hoặc phóng đại.",[["看到公司在国际市场上的影响力日益扩大，我们别提多高兴了.","Kàn dào gōng sī zài guó jì shì chǎng shàng de yǐng xiǎng lì rì yì kuò dà, wǒ men bié tí duō gāo xìng le","Thấy sức ảnh hưởng của công ty trên thị trường quốc tế ngày càng mở rộng, chúng tôi vui không thể tả."]],{"py": "bié tí duō...le","use": "","note": "","src": "file"}],["顿","顿","Phó từ biểu thị hành động xảy ra trong thời gian ngắn hoặc số lần lặp lại của hành động.",[["由于他在研发方面做出了突出贡献，公司决定给他的年终奖翻了顿.","Yóu yú tā zài yán fā fāng miàn zuò chū le tū chū gòng xiàn, gōng sī jué dìng gěi tā de nián zhōng jiǎng fān le dùn","Do anh ấy có đóng góp nổi bật, công ty quyết định tăng gấp đôi tiền thưởng cuối năm cho anh ấy."]],{"py": "dùn","use": "","note": "","src": "file"}],["过于","过于","Phó từ biểu thị vượt quá một mức độ nhất định hoặc quá mức, thường dùng để bổ nghĩa cho tính từ hoặc động từ/cụm động từ.",[["投资决策过于草率，最终给公司带来了不可挽回的损失.","Tóu zī jué cè guò yú cǎo shuài, zuì zhōng gěi gōng sī dài lái le bù kě wǎn huí de sǔn shī","Quyết định đầu tư quá hấp tấp, cuối cùng đã mang lại thiệt hại không thể cứu vãn cho công ty."]],{"py": "guò yú","use": "","note": "","src": "file"}],["着呢","着呢","Trợ từ ngữ khí, biểu thị mức độ sâu, mang sắc thái khoa trương/cường điệu.",[["别看这项技术看似简单，其实背后的理论知识复杂着呢.","Bié kàn zhè xiàng jì shù kàn sì jiǎn dān, qí shí bèi hòu de lǐ lùn zhī shí fù zá zhe ne","Đừng thấy kỹ thuật này tưởng chừng đơn giản, thực ra kiến thức lý luận đằng sau phức tạp lắm đấy."]],{"py": "zhe ne","use": "","note": "","src": "file"}],["说A就A","说A就A","Cấu trúc dùng trong khẩu ngữ, biểu thị hành động xảy ra hoặc tiến triển rất nhanh khi có sự việc phát sinh. \"A\" là động từ hoặc cụm động từ/tính từ ngắn.",[["市场竞争激烈，很多新兴企业说倒闭就倒闭，让人防不胜防.","Shì chǎng jìng zhēng jī liè, hěn duō xīn xīng qǐ yè shuō dǎo bì jiù dǎo bì, ràng rén fáng bù shèng fáng","Cạnh tranh thị trường khốc liệt, nhiều doanh nghiệp mới nói phá sản là phá sản, khiến người ta không kịp trở tay."]],{"py": "shuō A jiù A","use": "","note": "","src": "file"}],["形容词xíng róng cí","形容词xíng róng cí","Cấu trúc bổ ngữ mức độ, biểu thị mức độ đạt đến cực điểm hoặc rất cao.",[["公司的改革方案遭到了许多老员工的反对，让他们头疼得要命.","Gōng sī de gǎi gé fāng àn zāo dào le xǔ duō lǎo yuán gōng de fǎn duì, ràng tā men tóu téng de yào mìng","Kế hoạch cải cách của công ty bị nhiều nhân viên cũ phản đối, khiến họ đau đầu kinh khủng."]],{"py": "xíng róng cí","use": "","note": "","src": "file"}],["乘机","乘机","Động từ/Phó từ, nghĩa là tận dụng cơ hội để làm một việc gì đó.",[["他乘机向听众普及了相关的金融知识，赢得了大家的赞许.","Tā chéng jī xiàng tīng zhòng pǔ jí le xiāng guān de jīn róng zhī shí, yíng dé le dà jiā de zàn xǔ","Anh ấy nhân cơ hội phổ biến kiến thức tài chính liên quan cho khán giả, giành được sự tán dương của mọi người."]],{"py": "chéng jī","use": "","note": "","src": "file"}],["不料","不料","Liên từ, biểu thị bất ngờ, không ngờ đến, thường đi kèm với các phó từ như 却, 竟, 果然, 倒, 还.",[["我们为这次项目做了充分的准备，不料市场需求突然发生了巨大的变化.","Wǒ men wèi zhè cì xiàng mù zuò le chōng fèn de zhǔn bèi, bù liào shì chǎng xū qiú tū rán fā shēng le jù dà de biàn huà","Chúng tôi đã chuẩn bị đầy đủ cho dự án này, không ngờ nhu cầu thị trường lại đột ngột thay đổi lớn."]],{"py": "bù liào","use": "","note": "","src": "file"}],["未免","未免","Phó từ, biểu thị không tránh khỏi việc đạt đến một mức độ nào đó (thường là tiêu cực), nói rằng điều gì đó là không phù hợp hoặc quá mức.",[["他的言辞未免有些偏激，很容易引起听众的反感.","Tā de yán cí wèi miǎn yǒu xiē piān jī, hěn róng yì yǐn qǐ tīng zhòng de fǎn gǎn","Lời lẽ của anh ấy quả thực hơi cực đoan, rất dễ gây ác cảm cho người nghe."]],{"py": "wèi miǎn","use": "","note": "","src": "file"}],["……而已 (mà thôi)","……而已","而已 đặt cuối câu để giảm nhẹ: chỉ vậy thôi, thế thôi.",[["我们之所以能取得今天的成就，靠的不过是日复一日的坚持而已.","Wǒ men zhī suǒ yǐ néng qǔ dé jīn tiān de chéng jiù, kào de bú guò shi rì fù yī rì de jiān chí ér yǐ","Sở dĩ chúng ta đạt được thành tựu hôm nay, chẳng qua chỉ là nhờ sự kiên trì ngày qua ngày mà thôi."]],{"py": "éryǐ","use": "Đứng cuối câu, thường kèm 只, 不过, 仅仅.","note": "Mang giọng nói giảm, không dùng cho điều nghiêm trọng.","src": "file"}],["固然","固然","Liên từ, biểu thị thừa nhận một sự thật hoặc một khía cạnh, câu sau thường dùng 但是, 可是, 不过 để chuyển ý hoặc đưa ra ý kiến phản đối.",[["创新固然重要，但是我们必须在遵守法律法规的前提下进行.","Chuàng xīn gù rán zhòng yào, dàn shi wǒ men bì xū zài zūn shǒu fǎ lǜ fǎ guī de qián tí xià jìn xíng","Đổi mới tất nhiên quan trọng, nhưng chúng ta phải tiến hành trên cơ sở tuân thủ pháp luật."]],{"py": "gù rán","use": "","note": "","src": "file"}],["并非","并非","Phó từ/Động từ, biểu thị phủ định hoàn toàn, nghĩa là \"không phải\", thường dùng trong văn viết.",[["他的成功并非一蹴而就，而是经过了无数次失败和挫折.","Tā de chéng gōng bìng fēi yī cù ér jiù, ér shi jīng guò le wú shù cì shī bài hé cuò zhé","Thành công của anh ấy không hề đạt được một sớm một chiều, mà là qua vô số lần thất bại và vấp ngã."]],{"py": "bìng fēi","use": "","note": "","src": "file"}],["唯独","唯独","Phó từ, biểu thị chỉ một người/vật/sự việc là ngoại lệ, thường dùng để nhấn mạnh sự so sánh hoặc đối lập.",[["参加会议的成员都对提案表示赞同，唯独他提出了反对意见.","Cān jiā huì yì de chéng yuán dōu duì tí àn biǎo shì zàn tóng, wéi dú tā tí chū le fǎn duì yì jiàn","Các thành viên tham dự cuộc họp đều đồng ý với đề xuất, chỉ riêng anh ấy đưa ra ý kiến phản đối."]],{"py": "wéi dú","use": "","note": "","src": "file"}],["明明","明明","Phó từ, biểu thị rõ ràng là như vậy nhưng thực tế lại khác, thường dùng để nhấn mạnh sự nghi vấn, không hài lòng, hoặc kinh ngạc.",[["这项工程明明预算充足，怎么会出现资金短缺的问题呢.","Zhè xiàng gōng chéng míng míng yù suàn chōng zú, zěn me huì chū xiàn zī jīn duǎn quē de wèn tí ne","Dự án này rõ ràng có ngân sách đầy đủ, tại sao lại xuất hiện vấn đề thiếu vốn?"]],{"py": "míng míng","use": "","note": "","src": "file"}],["大不了","大不了","Phó từ, dùng trong khẩu ngữ, biểu thị điều tồi tệ nhất có thể xảy ra, thường mang sắc thái không quan trọng, hoặc thể hiện sự dứt khoát.",[["如果谈判无法达成一致，大不了我们放弃合作，寻找新的伙伴.","Rú guǒ tán pàn wú fǎ dá chéng yī zhì, dà bù liǎo wǒ men fàng qì hé zuò, xún zhǎo xīn de huǒ bàn","Nếu đàm phán không đạt được thỏa thuận, cùng lắm chúng ta từ bỏ hợp tác, tìm kiếm đối tác mới."]],{"py": "dà bù liǎo","use": "","note": "","src": "file"}],["对……而言","对……而言","Cấu trúc, biểu thị đối với ai đó/phương diện nào đó mà nói, dùng để xác định phạm vi hoặc góc độ nhận định.",[["对一个有着远大抱负的年轻人而言，稳定和安逸并非人生的终极目标.","Duì yī gè yǒu zhe yuǎn dà bào fù de nián qīng rén ér yán, wěn dìng hé ān yì bìng fēi rén shēng de zhōng jí mù biāo","Đối với một người trẻ có hoài bão lớn, ổn định và an nhàn không phải là mục tiêu cuối cùng của cuộc đời."]],{"py": "duì...ér yán","use": "","note": "","src": "file"}],["有关","有关","Động từ/Tính từ/Giới từ, biểu thị có liên quan.",[["我们正在收集所有有关这次事故的详细资料和证人证词.","Wǒ men zhèng zài shōu jí suǒ yǒu yǒu guān zhè cì shì gù de xiáng xì zī liào hé zhèng rén zhèng cí","Chúng tôi đang thu thập tất cả tài liệu chi tiết và lời khai nhân chứng liên quan đến vụ tai nạn này."]],{"py": "yǒu guān","use": "","note": "","src": "file"}],["不瞒你说","不瞒你说","Cụm từ dùng để mở đầu câu nói, biểu thị sự thật, chân thành (thường là một lời khuyên hoặc ý kiến chủ quan).",[["不瞒你说，我对他处理这件事的方式并不完全认同，认为过于冲动.","Bù mán nǐ shuō, wǒ duì tā chǔ lǐ zhè jiàn shì de fāng shì bìng bù wán quán rèn tóng, rèn wéi guò yú chōng dòng","Thật lòng mà nói, tôi không hoàn toàn đồng tình với cách anh ấy xử lý chuyện này, cho rằng quá bốc đồng."]],{"py": "bù mán nǐ shuō","use": "","note": "","src": "file"}],["于 (HSK6)","于","Giới từ, biểu thị thời điểm, nơi chốn, hoặc đối tượng/phương diện. Thường dùng trong văn viết.",[["他决定在工作了三年的公司离职，开始人生的新一页.","Tā jué dìng zài gōng zuò le sān nián de gōng sī lí zhí, kāi shǐ rén shēng de xīn yī yè","Anh ấy quyết định nghỉ việc ở công ty đã làm ba năm, bắt đầu một trang mới cho cuộc đời."]],{"py": "yú","use": "","note": "","src": "file"}],["致使","致使","Động từ, biểu thị gây ra một kết quả nào đó (thường là tiêu cực). Câu trước chỉ nguyên nhân, câu sau là kết quả.",[["管理层的重大失误直接致使公司陷入了前所未有的财务危机.","Guǎn lǐ céng de zhòng dà shī wù zhí jiē zhì shǐ gōng sī xiàn rù le qián suǒ wèi yǒu de cái wù wēi jī","Sai lầm lớn của ban quản lý đã trực tiếp gây ra cuộc khủng hoảng tài chính chưa từng có cho công ty."]],{"py": "zhì shǐ","use": "","note": "","src": "file"}],["日益 越来越","日益 越来越","Phó từ, 日益 biểu thị mức độ tăng lên theo thời gian (ngày càng), dùng để tu sức cho động từ hoặc tính từ/cụm động từ. 越来越 cũng biểu thị mức độ tăng dần.",[["随着技术的日益成熟，自动驾驶汽车将很快普及到日常生活中.","Suí zhe jì shù de rì yì chéng shú, zì dòng jià shǐ qì chē jiāng hěn kuài pǔ jí dào rì cháng shēng huó zhōng","Cùng với sự trưởng thành ngày càng cao của công nghệ, ô tô tự lái sẽ sớm phổ biến trong đời sống hàng ngày."],["国际贸易形势越来越复杂，企业必须积极调整策略才能应对挑战.","Guó jì mào yì xíng shì yuè lái yuè fù zá, qǐ yè bì xū jī jí tiáo zhěng cè lüè cái néng yìng duì tiǎo zhàn","Tình hình thương mại quốc tế ngày càng phức tạp, doanh nghiệp phải tích cực điều chỉnh chiến lược mới có thể ứng phó với thách thức."]],{"py": "rì yì","use": "","note": "","src": "file"}],["时而","时而","Phó từ, biểu thị lúc thì... lúc thì..., chỉ sự việc lặp lại không theo quy luật, thường đi kèm với nhau.",[["在高海拔地区，天气变化无常，时而艳阳高照，时而风雪交加.","Zài gāo hǎi bá dì qū, tiān qì biàn huà wú cháng, shí ér yàn yáng gāo zhào, shí ér fēng xuě jiāo jiā","Ở vùng cao, thời tiết thất thường, lúc trời nắng chang chang, lúc lại mưa tuyết xen kẽ."]],{"py": "shí ér","use": "","note": "","src": "file"}],["不禁","不禁","Phó từ, biểu thị không kìm được, không thể ngăn chặn (hành động hoặc cảm xúc).",[["面对如此精湛绝伦的艺术品，他不禁发出由衷的赞叹.","Miàn duì rú cǐ jīng zhàn jué lún de yì shù pǐn, tā bù jīn fā chū yóu zhōng de zàn tàn","Trước tác phẩm nghệ thuật tuyệt vời đến thế, anh ấy không kìm được mà thốt lên lời tán thưởng chân thành."]],{"py": "bù jīn","use": "","note": "","src": "file"}],["无不","无不","Phó từ, biểu thị không gì là không, tất cả đều (phủ định kép mang ý khẳng định tuyệt đối).",[["博物馆里展出的每一件文物，无不凝聚着古代劳动人民的智慧和心血.","Bó wù guǎn lǐ zhǎn chū de měi yī jiàn wén wù, wú bù níng jù zhe gǔ dài láo dòng rén mín de zhì huì hé xīn xuè.","Mỗi hiện vật được trưng bày trong bảo tàng đều cô đọng trí tuệ và tâm huyết của người lao động thời cổ đại."]],{"py": "wú bù","use": "","note": "","src": "file"}],["即便","即便","Liên từ, biểu thị dù cho, cho dù (nhượng bộ giả định), thường đi kèm với 也 hoặc 还 ở mệnh đề sau.",[["即便这项挑战难度极大，我们也要全力以赴，争取最好的结果.","Jí biàn zhè xiàng tiǎo zhàn nán dù jí dà, wǒ men yě yào quán lì yǐ fù, zhēng qǔ zuì hǎo de jié guǒ","Cho dù thử thách này cực kỳ khó khăn, chúng ta vẫn phải dốc toàn lực để đạt được kết quả tốt nhất."]],{"py": "jí biàn","use": "","note": "","src": "file"}],["统统","统统","Phó từ, biểu thị tất cả, hoàn toàn (không có ngoại lệ nào).",[["经过这次彻底的清查，公司内部的腐败分子被统统清除出局.","Jīng guò zhè cì chè dǐ de qīng chá, gōng sī nèi bù de fǔ bài fèn zi bèi tǒng tǒng qīng chú chū jú.","Sau đợt thanh tra triệt để này, những phần tử tham nhũng trong công ty tất cả đã bị loại bỏ."]],{"py": "tǒng tǒng","use": "","note": "","src": "file"}],["以……为……","以……为……","Cấu trúc giới từ, biểu thị lấy cái gì đó làm cái gì đó (làm căn cứ, mục tiêu, hoặc tiêu chuẩn).",[["这家企业一直以科技创新为核心竞争力，不断引领行业发展.","Zhè jiā qǐ yè yī zhí yǐ kē jì chuàng xīn wéi hé xīn jìng zhēng lì, bú duàn yǐn lǐng háng yè fā zhǎn","Doanh nghiệp này luôn lấy đổi mới công nghệ làm năng lực cạnh tranh cốt lõi, không ngừng dẫn dắt sự phát triển của ngành."]],{"py": "yǐ...wéi...","use": "","note": "","src": "file"}],["不妨","不妨","Phó từ, đưa ra lời khuyên hoặc đề nghị), thường có nghĩa nhẹ nhàng, hàm ý thử một lần.",[["如果你在研究过程中遇到瓶颈，不妨换个角度思考问题，也许会有新的发现.","Rú guǒ nǐ zài yán jiū guò chéng zhōng yù dào píng jǐng, bù fáng huàn gè jiǎo dù sī kǎo wèn tí, yě xǔ huì yǒu xīn de fā xiàn","Nếu bạn gặp bế tắc trong quá trình nghiên cứu, hãy thử thay đổi góc độ suy nghĩ, biết đâu sẽ có phát hiện mới."]],{"py": "bù fáng","use": "","note": "","src": "file"}],["务必","务必","Phó từ, biểu thị nhất định phải, cần phải (nhấn mạnh sự kiên quyết hoặc cần thiết).",[["既然要参加这次高规格的国际会议，代表团成员务必提前做好充分准备.","Jì rán yào cān jiā zhè cì gāo guī gé de guó jì huì yì, dài biǎo tuán chéng yuán wù bì tí qián zuò hǎo chōng fèn zhǔn bèi","Vì phải tham dự hội nghị quốc tế quy mô lớn này, các thành viên phái đoàn tuyệt đối phải chuẩn bị đầy đủ từ trước."]],{"py": "wù bì","use": "","note": "","src": "file"}],["不得已 不得不","不得已 不得不","Cặp phó từ. 不得已 biểu thị không còn cách nào khác. 不得不 biểu thị không thể không, nhấn mạnh sự bị động buộc phải làm điều gì đó.",[["由于资金链断裂，公司不得已采取裁员措施，以维持运营.","Yóu yú zī jīn liàn duàn liè, gōng sī bù dé yǐ cǎi qǔ cái yuán cuò shī, yǐ wéi chí yùn yíng","Do đứt gãy chuỗi vốn, công ty buộc lòng phải áp dụng biện pháp cắt giảm nhân sự để duy trì hoạt động."],["为了避免事态扩大，他不得不主动出面，向公众澄清事实.","Wèi le bì miǎn shì tài kuò dà, tā bù dé bù zhǔ dòng chū miàn, xiàng gōng zhòng chéng qīng shì shí","Để tránh tình hình mở rộng, anh ấy không thể không đứng ra chủ động làm rõ sự thật với công chúng."]],{"py": "bù dé yǐ","use": "","note": "","src": "file"}],["嫌","嫌","Động từ, biểu thị không thích, không vừa lòng, chê. Thường đi với 嫌 + Danh từ/Tính từ/Hình dung từ.",[["这家企业改革步伐缓慢，被许多年轻的求职者嫌弃，认为缺乏创新活力.","Zhè jiā qǐ yè gǎi gé bù fá huǎn màn, bèi xǔ duō nián qīng de qiú zhí zhě xián qì, rèn wéi quē fá chuàng xīn huó lì","Doanh nghiệp này cải cách chậm, bị nhiều người tìm việc trẻ tuổi chê bai vì thiếu sức sống đổi mới."]],{"py": "xián","use": "","note": "","src": "file"}],["动不动","动不动","Phó từ, biểu thị hành động xảy ra liên tục, thường xuyên mà không có lý do rõ ràng, mang sắc thái phê phán/không hài lòng.",[["这位经理处理问题非常情绪化，动不动就对下属发脾气，令人难以忍受.","Zhè wèi jīng lǐ chǔ lǐ wèn tí fēi cháng qíng xù huà, dòng bú dòng jiù duì xià shǔ fā pí qì, lìng rén nán yǐ rěn shòu","Vị quản lý này xử lý vấn đề rất cảm tính, hễ tí là nổi nóng với cấp dưới, khó mà chịu đựng được."]],{"py": "dòng bú dòng","use": "","note": "","src": "file"}],["甲乙丙丁……","甲乙丙丁……","Cấu trúc dùng để liệt kê, sắp xếp sự việc theo thứ tự hoặc phân chia nhóm, thường dùng trong văn viết/các bài tập mang tính chất liệt kê.",[["这份调研报告主要包括甲乙丙丁四个部分，详细分析了市场前景.","Zhè fèn diào yán bào gào zhǔ yào bāo kuò jiǎ yǐ bǐng dīng sì gè bù fèn, xiáng xì fēn xī le shì chǎng qián jǐng","Báo cáo khảo sát này chủ yếu bao gồm bốn phần A, B, C, D, phân tích chi tiết triển vọng thị trường."]],{"py": "jiǎ yǐ bǐng dīng...","use": "","note": "","src": "file"}],["加以","加以","Động từ, biểu thị thực hiện hoặc tiến hành một phương pháp/thái độ nào đó với sự vật/sự việc nêu ra ở câu trước. Sau 加以 là một động từ hai âm tiết.",[["针对报告中提出的问题，管理层表示将认真研究并加以改进.","Zhēn duì bào gào zhōng tí chū de wèn tí, guǎn lǐ céng biǎo shì jiāng rèn zhēn yán jiū bìng jiā yǐ gǎi jìn","Đối với các vấn đề được nêu trong báo cáo, ban quản lý cho biết sẽ nghiên cứu kỹ lưỡng và tiến hành cải tiến."]],{"py": "jiā yǐ","use": "","note": "","src": "file"}],["大大、远远","大大、远远","Phó từ, 大大 biểu thị mức độ rất sâu hoặc số lượng lớn. 远远 biểu thị rất xa hoặc rất nhiều (vượt xa mức dự tính).",[["新政策的实施大大提高了生产效率，为公司节省了大量的成本.","Xīn zhèng cè de shí shī dà dà tí gāo le shēng chǎn xiào lǜ, wèi gōng sī jié shěng le dà liàng de chéng běn","Việc thực hiện chính sách mới đã nâng cao đáng kể hiệu quả sản xuất, tiết kiệm rất nhiều chi phí cho công ty."],["事实证明，他的能力远远超出了我们的预期，足以胜任这项艰巨的任务.","Shì shí zhèng míng, tā de néng lì yuǎn yuǎn chāo chū le wǒ men de yù qī, zú yǐ shèng rèn zhè xiàng jiān jù de rèn wù","Sự thật chứng minh năng lực của anh ấy vượt xa kỳ vọng của chúng tôi, đủ sức đảm nhận nhiệm vụ khó khăn này."]],{"py": "","use": "","note": "","src": "file"}],["紧缩句","紧缩句","Biện pháp tu từ, là hình thức rút gọn nội dung của câu, làm cho câu trở nên ngắn gọn và súc tích hơn.",[["我宁愿失去一切，也不愿放弃原则.","Wǒ níng yuàn shī qù yī qiè, (yě) bú yuàn fàng qì yuán zé","Tôi thà mất tất cả, cũng không muốn từ bỏ nguyên tắc."]],{"py": "jǐn suō jù","use": "","note": "","src": "file"}],["特意","特意","Phó từ, biểu thị cố ý, chủ tâm làm một việc gì đó.",[["为了表达对这位专家的敬意，主办方特意为他准备了隆重的欢迎仪式.","Wèi le biǎo dá duì zhè wèi zhuān jiā de jìng yì, zhǔ bàn fāng tè yì wèi tā zhǔn bèi le lóng zhòng de huān yíng yí shì","Để bày tỏ sự tôn kính đối với chuyên gia này, ban tổ chức đã đặc biệt chuẩn bị một buổi lễ chào mừng long trọng cho ông."]],{"py": "tè yì","use": "","note": "","src": "file"}],["即将","即将","Phó từ, biểu thị điều gì đó ắp xảy ra. Thường dùng trong văn viết.",[["经过几个月的紧张筹备，这项大型国际项目即将进入实施阶段.","Jīng guò jǐ gè yuè de jǐn zhāng chóu bèi, zhè xiàng dà xíng guó jì xiàng mù jí jiāng jìn rù shí shī jiē duàn","Sau vài tháng chuẩn bị gấp rút, dự án quốc tế quy mô lớn này sắp sửa bước vào giai đoạn thực hiện."]],{"py": "jí jiāng","use": "","note": "","src": "file"}],["能A就A","能A就A","Cấu trúc dùng trong khẩu ngữ, biểu thị tận lực hoặc hết sức (A là động từ/tính từ).",[["既然领导给了我们充分的授权，我们就应该能解决就解决，不要事事都请示.","Jì rán lǐng dǎo gěi le wǒ men chōng fèn de shòu quán, wǒ men jiù yīng gāi néng jiě jué jiù jiě jué, bú yào shì shì dōu qǐng shì","Vì lãnh đạo đã ủy quyền đầy đủ, chúng ta giải quyết được thì cứ giải quyết, đừng việc gì cũng xin ý kiến."]],{"py": "néng A jiù A","use": "","note": "","src": "file"}],["别说","别说","Động từ, biểu thị nhường bộ, thường nhấn mạnh một người hoặc sự vật khác (thường là một điều ít quan trọng hơn) để làm nổi bật điều quan trọng hơn.",[["他这个人向来心胸宽广，别说是受到批评，就算是遇到更大的挫折也不会轻易放弃.","Tā zhè gè rén xiàng lái xīn xiōng kuān guǎng, bié shuō shi shòu dào pī píng, jiù suàn shi yù dào gèng dà de cuò zhé yě bú huì qīng yì fàng qì","Người anh ấy vốn rất rộng lượng, đừng nói là bị chỉ trích, ngay cả khi gặp thất bại lớn hơn cũng sẽ không dễ dàng bỏ cuộc."]],{"py": "bié shuō","use": "","note": "","src": "file"}],["来来回回","来来回回","Lặp lại động từ, biểu thị hành động lặp đi lặp lại (dạng AABB).",[["她为了研究这个复杂的图案，来来回回地翻阅了大量的古代文献资料.","Tā wèi le yán jiū zhè gè fù zá de tú àn, lái lái huí huí dì fān yuè le dà liàng de gǔ dài wén xiàn zī liào","Để nghiên cứu hoa văn phức tạp này, cô ấy đã lật đi lật lại rất nhiều tài liệu cổ."]],{"py": "","use": "","note": "","src": "file"}],["左……右……","左……右……","Cấu trúc dùng để nhấn mạnh một hành vi/tình huống lặp lại nhiều lần, A và B thường là động từ hoặc cụm động từ tương tự.",[["整个团队都围绕着这个方案左修改右调整，力求达到最完美的效果.","Zhěng gè tuán duì dōu wéi rào zhe zhè gè fāng àn zuǒ xiū gǎi yòu tiáo zhěng, lì qiú dá dào zuì wán měi de xiào guǒ","Cả đội hết chỉnh sửa lại điều chỉnh xoay quanh đề án này, nhằm đạt được hiệu quả hoàn hảo nhất."]],{"py": "zuǒ...yòu...","use": "","note": "","src": "file"}],["不成","不成","Trợ từ, dùng ở cuối câu, biểu thị suy đoán hoặc ngữ khí phản vấn (chẳng lẽ, không được sao). Phía trước câu thường có 难道 hoặc 莫非.",[["大家都认为这是一个可行的方案，难道只有你觉得有问题不成?","Dà jiā dōu rèn wéi zhè shi yī gè kě xíng de fāng àn, nán dào zhǐ yǒu nǐ jué de yǒu wèn tí bù chéng","Mọi người đều cho rằng đây là một phương án khả thi, chẳng lẽ chỉ có mình bạn thấy có vấn đề sao?"]],{"py": "bù chéng","use": "","note": "","src": "file"}],["Cấu trúc Động từTính từ có chứa 个","Cấu trúc Động từTính từ có chứa 个","Biểu thị hành động xảy ra nhanh chóng, đột ngột hoặc số lượng tăng lên.",[["听到这个突如其来的好消息，我心里咯噔了一个，久久不能平静.","Tīng dào zhè gè tū rú qí lái de hǎo xiāo xi, wǒ xīn lǐ gē dēng le yī gè, jiǔ jiǔ bù néng píng jìng","Nghe tin vui bất ngờ này, lòng tôi nảy lên một cái, mãi không thể bình tĩnh lại."]],{"py": "","use": "","note": "","src": "file"}],["预先","预先","Phó từ, biểu thị hành động hoặc sự việc xảy ra trước khi sự việc chính thức diễn ra",[["为了确保活动顺利进行，我们预先制定了多套应急预案.","Wèi le qùn bǎo huó dòng shùn lì jìn xíng, wǒ men yù xiān zhì dìng le duō tào yìng jí yù àn","Để đảm bảo hoạt động diễn ra suôn sẻ, chúng tôi đã chuẩn bị trước nhiều bộ kế hoạch khẩn cấp."]],{"py": "yù xiān","use": "","note": "","src": "file"}],["……也好, …… 也罢","……也好, …… 也罢","Cấu trúc liệt kê, biểu thị trong bất kỳ tình huống nào (dù A hay B), kết quả vẫn như vậy. Thường đi với 都/总 ở vế sau.",[["无论是经济发展也好，环境保护也罢，我们都应该坚持可持续发展的原则.","Wú lùn shi jīng jì fā zhǎn yě hǎo, huán jìng bǎo hù yě bà, wǒ men dōu yīng gāi jiān chí kě chí xù fā zhǎn de yuán zé","Bất kể là phát triển kinh tế hay bảo vệ môi trường, chúng ta đều phải tuân thủ nguyên tắc phát triển bền vững."]],{"py": "","use": "","note": "","src": "file"}],["不时","不时","Phó từ, biểu thị sự thỉnh thoảng (không cố định).",[["尽管已经离开了家乡多年，但她不时会想起童年的美好回忆.","Jǐn guǎn yǐ jīng lí kāi le jiā xiāng duō nián, dàn tā bù shí huì xiǎng qǐ tóng nián de měi hǎo huí yì","Mặc dù đã rời xa quê hương nhiều năm, nhưng cô ấy thỉnh thoảng vẫn nhớ lại những ký ức tuổi thơ tươi đẹp."]],{"py": "bù shí","use": "","note": "","src": "file"}],["多多少少","多多少少","Phó từ/Tính từ lặp lại, biểu thị ít nhiều, ở một mức độ nào đó.",[["经过这次挫折，他对自己的能力多多少少产生了一些怀疑.","Jīng guò zhè cì cuò zhé, tā duì zì jǐ de néng lì duō duō shǎo shǎo chǎn shēng le yī xiē huái yí","Sau thất bại lần này, anh ấy ít nhiều đã nảy sinh nghi ngờ về năng lực của bản thân."]],{"py": "duō duō shǎo shǎo","use": "","note": "","src": "file"}],["逐","逐","Giới từ/Phó từ, biểu thị sự lần lượt, từng bước.",[["随着全球经济一体化进程加快，各国之间的贸易壁垒正被逐渐打破.","Suí zhe quán qiú jīng jì yī tǐ huà jìn chéng jiā kuài, gè guó zhī jiān de mào yì bì lěi zhèng bèi zhú jiàn dǎ pò","Cùng với quá trình toàn cầu hóa kinh tế tăng tốc, rào cản thương mại giữa các quốc gia đang dần dần bị phá vỡ."]],{"py": "zhú","use": "","note": "","src": "file"}],["归根到底","归根到底","Nói tóm lại, chung quy lại (đi đến bản chất vấn đề).",[["无论这项技术如何先进，归根到底，它只是人类实现目标的工具.","Wú lùn zhè xiàng jì shù rú hé xiān jìn, guī gēn dào dǐ, tā zhǐ shi rén lèi shí xiàn mù biāo de gōng jù","Bất kể công nghệ này tiên tiến đến đâu, chung quy lại, nó chỉ là công cụ để con người đạt được mục tiêu."]],{"py": "guī gēn dào dǐ","use": "","note": "","src": "file"}],["哪怕","哪怕","Liên từ, biểu thị dù cho, ngay cả (giả định cực đoan), thường đi kèm với 也 hoặc 都 ở vế sau.",[["哪怕只剩下微弱的希望，我们也要坚持不懈地努力下去.","Nǎ pà zhǐ shèng xià wēi ruò de xī wàng, wǒ men yě yào jiān chí bú xiè dì nǔ lì xià qù","Ngay cả khi chỉ còn lại tia hy vọng mong manh, chúng ta vẫn phải kiên trì nỗ lực không ngừng."]],{"py": "nǎ pà","use": "","note": "","src": "file"}],["反之","反之","Liên từ, biểu thị sự ngược lại. Thường dùng để chuyển ý, đưa ra điều kiện hoặc kết quả đối lập.",[["采取积极的应对策略有助于化解危机；反之，消极逃避只会使局势更加恶化.","Cǎi qǔ jī jí de yìng duì cè lüè yǒu zhù yú huà jiě wēi jī; fǎn zhī, xiāo jí táo bì zhǐ huì shǐ jú shì gèng jiā è huà","Áp dụng chiến lược ứng phó tích cực sẽ giúp hóa giải khủng hoảng; ngược lại, trốn tránh tiêu cực chỉ làm tình hình thêm tồi tệ."]],{"py": "fǎn zhī","use": "","note": "","src": "file"}],["A的A, B的B","A的A, B的B","Cấu trúc liệt kê, biểu thị sự liệt kê của một số tình huống hoặc sự vật, thường dùng trong khẩu ngữ.",[["晚会上，人们唱歌的唱歌，跳舞的跳舞，尽情享受欢乐的时光.","Wǎn huì shàng, rén men chàng gē de chàng gē, tiào wǔ de tiào wǔ, jìn qíng xiǎng shòu huān lè de shí guāng","Trong buổi tiệc tối, mọi người người hát thì hát, người nhảy thì nhảy, tận hưởng thời gian vui vẻ."]],{"py": "","use": "","note": "","src": "file"}],["一时","一时","Phó từ, biểu thị tạm thời, đột ngột (xảy ra trong thời gian ngắn). Cũng có thể dùng để biểu thị sự lặp lại.",[["面对媒体的追问，发言人一时语塞，不知如何回应.","Miàn duì méi tǐ de zhuī wèn, fā yán rén yī shí yǔ sè, bù zhī rú hé huí yìng","Trước sự truy vấn của truyền thông, người phát ngôn bất chợt nghẹn lời, không biết trả lời thế nào."]],{"py": "yī shí","use": "","note": "","src": "file"}],["尚且","尚且","Liên từ, biểu thị vẫn còn, còn (một sự vật/tình huống ở mức độ thấp đã xảy ra), vế sau thường dùng 何况/更 để nhấn mạnh điều ở mức độ cao hơn.",[["像他这样精明能干的人尚且犯错，何况是我们这些缺乏经验的新手.","Xiàng tā zhè yàng jīng míng néng gàn de rén shàng qiě fàn cuò, hé kuàng shi wǒ men zhè xiē quē fá jīng yàn de xīn shǒu","Người tài giỏi như anh ấy còn mắc sai lầm, huống chi là những người mới thiếu kinh nghiệm như chúng ta."]],{"py": "shàng qiě","use": "","note": "","src": "file"}],["当","当","Giới từ, biểu thị đang ở thời điểm hoặc địa điểm nào đó",[["他当时正在国外出差，错过了公司重要的年度会议.","Tā dāng shí zhèng zài guó wài chū chāi, cuò guò le gōng sī zhòng yào de nián dù huì yì","Anh ấy khi đó đang đi công tác nước ngoài, nên đã bỏ lỡ cuộc họp thường niên quan trọng của công ty."]],{"py": "dāng","use": "","note": "","src": "file"}],["终究","终究","Phó từ, biểu thị rốt cuộc, cuối cùng (nhấn mạnh kết quả hoặc bản chất).",[["经过多方的努力，这件悬而未决的法律纠纷终究得到了公正的解决.","Jīng guò duō fāng de nǔ lì, zhè jiàn xuán ér wèi jué de fǎ lǜ jiū fēn zhōng jiū dé dào le gōng zhèng de jiě jué","Sau nỗ lực của nhiều bên, tranh chấp pháp lý còn bỏ ngỏ này rốt cuộc đã được giải quyết công bằng."]],{"py": "zhōng jiū","use": "","note": "","src": "file"}],["愈……愈……","愈……愈……","Cấu trúc liên từ, biểu thị càng...càng... (mức độ tăng tiến song song).",[["随着学习的深入，我们愈发愈认识到汉语文化的博大精深.","Suí zhe xué xí de shēn rù, wǒ men yù fā yù rèn shí dào Hàn yǔ wén huà de bó dà jīng shēn","Học càng sâu, chúng ta càng nhận thức được sự uyên thâm của văn hóa Hán ngữ."]],{"py": "yù...yù...","use": "","note": "","src": "file"}],["一经","一经","Phó từ, dùng cho câu trên, biểu thị chỉ cần qua một hành động/bước nào đó, sẽ có kết quả tương ứng xảy ra.",[["这项新政策一经宣布，立即引起了社会各界的广泛关注.","Zhè xiàng xīn zhèng cè yī jīng xuān bù, lì jí yǐn qǐ le shè huì gè jiè de guǎng fàn guān zhù","Chính sách mới này vừa được công bố, lập tức đã thu hút sự quan tâm rộng rãi từ mọi tầng lớp xã hội"]],{"py": "yī jīng","use": "","note": "","src": "file"}],["本着 + 名词","本着 + 名词","Cấu trúc giới từ, biểu thị dựa trên một nguyên tắc, tinh thần, thái độ nào đó.",[["我们始终本着互利共赢的原则，与合作伙伴共同发展.","Wǒ men shǐ zhōng běn zhe hù lì gòng yíng de yuán zé, yǔ hé zuò huǒ bàn gòng tóng fā zhǎn","Chúng tôi luôn dựa trên nguyên tắc cùng có lợi, cùng phát triển với đối tác."]],{"py": "běn zhe + míng cí","use": "","note": "","src": "file"}],["为……起见","为……起见","Cấu trúc giới từ, biểu thị vì lợi ích của, vì mục đích nào đó.",[["为保障施工质量起见，工程团队对原材料进行了严格的筛选.","Wèi bǎo zhàng shī gōng zhì liàng qǐ jiàn, gōng chéng tuán duì duì yuán cái liào jìn xíng le yán gé de shāi xuǎn","Vì mục đích đảm bảo chất lượng thi công, đội ngũ kỹ thuật đã tiến hành sàng lọc nghiêm ngặt đối với nguyên vật liệu."]],{"py": "wèi...qǐ jiàn","use": "","note": "","src": "file"}],["暂且","暂且","Phó từ, biểu thị sự tạm thời, tạm gác lại.",[["既然现在无法达成共识，我们暂且搁置争议，以后再议.","Jì rán xiàn zài wú fǎ dá chéng gòng shí, wǒ men zàn qiě gē zhì zhēng yì, yǐ hòu zài yì","Vì hiện tại không thể đạt được sự đồng thuận, chúng ta tạm thời gác lại tranh cãi, bàn sau."]],{"py": "zàn qiě","use": "","note": "","src": "file"}],["屡次","屡次","Phó từ, biểu thị nhiều lần, lặp đi lặp lại (xảy ra một lần, một lần nữa).",[["他屡次违背合同条款，我们不得不考虑终止与他的合作关系.","Tā lǚ cì wéi bèi hé tóng tiáo kuǎn, wǒ men bù dé bù kǎo lǜ zhōng zhǐ yǔ tā de hé zuò guān xi","Anh ta nhiều lần vi phạm các điều khoản hợp đồng, chúng tôi buộc phải xem xét chấm dứt quan hệ hợp tác với anh ta."]],{"py": "lǚ cì","use": "","note": "","src": "file"}],["依据","依据","Động từ/Danh từ/Giới từ, biểu thị căn cứ, cơ sở để lập luận hoặc hành động",[["这项决策是依据最新的市场调研数据和专家意见做出的.","Zhè xiàng jué cè shi yī jù zuì xīn de shì chǎng diào yán shù jù hé zhuān jiā yì jiàn zuò chū de","Quyết định này được đưa ra dựa trên dữ liệu khảo sát thị trường và ý kiến chuyên gia mới nhất."]],{"py": "yī jù","use": "","note": "","src": "file"}],["任意","任意","Phó từ, biểu thị tùy ý, thoải mái, không có sự ràng buộc hay hạn chế.",[["在民主社会中，公民可以任意表达自己的观点，但需对言论负责.","Zài mín zhǔ shè huì zhōng, gōng mín kě yǐ rèn yì biǎo dá zì jǐ de guān diǎn, dàn xū duì yán lùn fù zé","Trong xã hội dân chủ, công dân có thể tự do bày tỏ quan điểm của mình, nhưng phải chịu trách nhiệm về lời nói."]],{"py": "rèn yì","use": "","note": "","src": "file"}],["尚末","尚末","Phó từ, biểu thị vẫn chưa.",[["尽管我们已经取得了初步进展，但距离最终成功尚末可知.","Jǐn guǎn wǒ men yǐ jīng qǔ dé le chū bù jìn zhǎn, dàn lí jù zuì zhōng chéng gōng shàng wèi kě zhī","Mặc dù chúng tôi đã đạt được tiến triển ban đầu, nhưng vẫn chưa thể biết được còn cách thành công cuối cùng bao xa."]],{"py": "shàng wèi","use": "","note": "","src": "file"}]]};
